window.ARTICLES_DATA = [{"id": "druckenmiller-exits-copper-steel-and-chip-stocks-93605e", "cat": "precious", "date": "2026-11-18", "title": "دروکن میلر از مس، فولاد و نیمه‌رساناها خارج شد و به سرمایه‌گذاری در معدن‌کاران طلا روی آورد", "lede": "فایل جدید نشان می‌دهد میلیاردر سرمایه‌گذار سبد خود را از فلزات صنعتی و چیپ‌ست‌ها به سمت شرکت‌های استخراج طلا می‌چرخاند.", "tags": ["دروکن میلر", "سرمایه‌گذاری", "فلزات صنعتی", "طلا", "معدن‌کاری", "بازار سرمایه"], "facts": [["دروکن میلر", "سرمایه‌گذار میلیاردر و مدیر صندوق DDM"], ["سهم‌های فروخته‌شده", "مس، فولاد و شرکت‌های نیمه‌رسانا"], ["سرمایه‌گذاری جدید", "سهام شرکت‌های استخراج طلا"], ["منبع", "فایل SEC اخیر منتشر شده توسط MINING.COM"]], "body": [{"t": "p", "x": "دروکن میلر، یکی از شناخته‌شده‌ترین سرمایه‌گذاران جهان، در یک فایل جدید به‌روزرسانی سبد سرمایه‌گذاری خود را اعلام کرد. این تغییر استراتژیک نشان می‌دهد که او به‌جای تمرکز بر فلزات صنعتی مانند مس و فولاد و همچنین سهام شرکت‌های فناوری نیمه‌رسانا، به سمت دارایی‌های طلا می‌چرخد."}, {"t": "p", "x": "در سال‌های اخیر، میلر به‌طور قابل‌توجهی در بخش‌های صنعتی سرمایه‌گذاری کرده بود؛ به‌ویژه در شرکت‌های استخراج مس و فولاد که از رشد تقاضای ساخت‌وساز بهره‌مند می‌شدند. اما با نوسانات شدید در بازارهای انرژی و افزایش فشارهای تورمی، او تصمیم گرفت ریسک‌های مرتبط با این صنایع را کاهش دهد."}, {"t": "p", "x": "فایل SEC منتشر شده نشان می‌دهد که میلر تمام یا بخش عمده‌ای از سهام خود در شرکت‌های مس‌کاوی، فولادسازی و تولید چیپ‌ست را به‌صورت کامل یا جزئی فروخته است. جزئیات دقیق حجم معاملات در این سند ذکر نشده، اما تأکید بر «خروج کامل» از این دسته‌بندی‌ها شده است."}, {"t": "p", "x": "در عوض، میلر به‌سرعت سرمایه‌گذاری خود را به سمت سهام شرکت‌های استخراج طلا متمرکز کرده است. این حرکت نشانگر این است که او طلا را به‌عنوان یک پناهگاه امن در برابر تورم و نوسانات اقتصادی می‌بیند؛ رویکردی که پیش از این در سبدهای سرمایه‌گذاری خود نیز بارها به کار گرفته بود."}, {"t": "p", "x": "تحلیل‌گران بازار به این تغییر استراتژیک به‌عنوان نشانه‌ای از نگرانی‌های گسترده دربارهٔ رشد اقتصادی جهانی و احتمال ادامه فشارهای تورمی اشاره می‌کنند. افزایش تقاضا برای طلا می‌تواند فشار صعودی بر قیمت این فلز گرانبها ایجاد کند و به‌ویژه برای شرکت‌های استخراج طلا که در حال حاضر ارزش‌گذاری بالاتری دارند، سودآور باشد."}, {"t": "p", "x": "از سوی دیگر، خروج سرمایه‌گذاری‌های صنعتی میلر می‌تواند فشار فروش بر سهام شرکت‌های مس، فولاد و نیمه‌رسانا را افزایشی کند؛ به‌ویژه در بازاری که پیش از این شاهد کاهش تقاضا برای این محصولات به‌دلیل رکودهای منطقه‌ای بوده است. این تحولات می‌تواند به‌صورت کوتاه‌مدت نوسان بیشتری در این بخش‌ها ایجاد کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر میلر به‌عنوان یک سرمایه‌گذار با سابقهٔ موفق در پیش‌بینی روندهای کلان بازار عمل کند، حرکت او به سمت طلا می‌تواند روندی مشابه را در میان سایر سرمایه‌گذاران بزرگ ایجاد کند. این امر نه تنها می‌تواند قیمت طلا را به‌سوی سطوح بالاتر سوق دهد، بلکه ممکن است فشار فروش بر فلزات صنعتی را ادامه دهد. در نهایت، این تغییر سبد سرمایه‌گذاری نشانگر یک تغییر در اولویت‌های ریسک‑پذیری سرمایه‌گذاران بزرگ در مواجهه با عدم‌اطمینان‌های اقتصادی جهانی است."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/druckenmiller-exits-copper-steel-and-chip-stocks-to-buy-gold-miners/", "orig": "Druckenmiller exits copper, steel and chip stocks to buy gold miners"}}, {"id": "li-ft-cuts-high-grade-lithium-ahead-of-quebec-st-ff1744", "cat": "battery", "date": "2026-11-18", "title": "Li-FT با برش‌های لیتیوم با درجه بالا پیش از مطالعه کبک", "lede": "Li-FT با حفاری‌های هدفمند برای استخراج لیتیوم با درجه بالا، داده‌های لازم برای به‌روزرسانی منابع و ارزیابی اقتصادی مقدماتی را برای اوایل 2027 فراهم می‌کند.", "tags": ["لیتیوم", "کبک", "حفاری", "منابع معدنی", "ارزیابی اقتصادی"], "facts": [["منطقه هدف", "کبک، کانادا"], ["نوع معدن", "لِتیوم با درجه بالا (High‑grade)"], ["هدف برنامه", "به‌روزرسانی منابع و ارزیابی اقتصادی مقدماتی (PEA)"], ["زمان‌بندی هدف", "اوایل سال 2027"]], "body": [{"t": "p", "x": "شرکت Li-FT، فعال در حوزه استخراج لیتیوم، در ماه‌های اخیر برنامه‌ای گسترده از حفاری‌های اکتشافی در پروژهٔ خود در استان کبک، کانادا، آغاز کرده است. این برنامه با هدف استخراج لیتیوم با درجه بالا و جمع‌آوری داده‌های ژئولوژیکی دقیق برای به‌روزرسانی منابع معدنی و تهیه یک ارزیابی اقتصادی مقدماتی (PEA) برنامه‌ریزی شده است."}, {"t": "p", "x": "کبک به‌عنوان یکی از مناطق پرپتانسیل جهان برای استخراج لیتیوم شناخته می‌شود؛ ذخایر این استان عمدتاً به‌صورت لیتیوم‑کربنات (LCE) با غلظت‌های بالاتر از ۲٪ Li₂O گزارش شده‌اند. در این زمینه، Li‑FT به‌دنبال شناسایی لایه‌های سنگی با غلظت‌های بالاتر از میانگین صنعتی است تا بتواند هزینه‌های استخراج را کاهش داده و ارزش افزودهٔ بیشتری برای سرمایه‌گذاران ایجاد کند."}, {"t": "p", "x": "در چارچوب این برنامه، تیم‌های مهندسی و ژئولوژی شرکت بیش از ۲,۰۰۰ متر حفاری عمودی و افقی را در چندین نقطه کلیدی انجام داده‌اند. نتایج اولیه نشان می‌دهد که برخی از نمونه‌ها حاوی لیتیوم با غلظت ۲٫۵ تا ۳٫۲٪ Li₂O هستند که به‌عنوان «درجه بالا» طبقه‌بندی می‌شوند. این ارقام، اگر به‌صورت تجاری استخراج شوند، می‌توانند بازدهی اقتصادی پروژه را به‌طور قابل‌توجهی بهبود بخشند."}, {"t": "p", "x": "سخنگن Li‑FT در بیانیه‌ای اعلام کرد: «ما خوشحالیم که توانستیم لیتیوم با کیفیت بالا را در این منطقه شناسایی کنیم. این نتایج مثبت، گام مهمی در مسیر به‌روزرسانی منابع و تکمیل ارزیابی اقتصادی مقدماتی است که هدفمان انتشار آن در اوایل سال ۲۰۲۷ می‌باشد». این اظهار نظر نشان‌دهندهٔ اعتماد شرکت به توانمندی‌های فنی و مالی خود برای پیشبرد پروژه است."}, {"t": "p", "x": "به‌روزرسانی منابع که پس از تکمیل داده‌های حفاری منتشر خواهد شد، می‌تواند حجم ذخایر برآوردی را به‌صورت «منابع برآوردی» (Inferred) یا «منابع تأییدشده» (Indicated) طبقه‌بندی کند. این طبقه‌بندی‌ها نقش کلیدی در جذب سرمایه‌گذاری‌های جدید و اخذ مجوزهای محیط‌زیستی دارند. همچنین، ارزیابی اقتصادی مقدماتی می‌تواند هزینهٔ استخراج، سرمایه‌گذاری اولیه، و زمان بازگشت سرمایه را برای سرمایه‌گذاران روشن کند."}, {"t": "p", "x": "از منظر بازار، افزایش ذخایر لیتیوم با درجه بالا می‌تواند فشارهای قیمتی را در بازارهای جهانی کاهش دهد و به‌ویژه برای تولیدکنندگان باتری‌های خودروهای الکتریکی (EV) و ذخیره‌سازی انرژی (ESS) مفید باشد. تحلیل‌گران معتقدند که پروژه‌های مشابه در کبک می‌توانند به‌عنوان منبعی پایدار برای تأمین تقاضای رو به رشد لیتیوم در سال‌های آینده عمل کنند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به نتایج اولیه حفاری‌های Li‑FT و برنامهٔ زمان‌بندی شده برای انتشار به‌روزرسانی منابع و ارزیابی اقتصادی در اوایل ۲۰۲۷، انتظار می‌رود که این پروژه نقش مهمی در تقویت زنجیره تأمین لیتیوم برای صنایع باتری ایفا کند. اگر نتایج نهایی تأیید کنندهٔ درجه بالای لیتیوم باشند، Li‑FT می‌تواند نه تنها سرمایه‌گذاری‌های جدید جذب کند، بلکه موقعیت استراتژیک خود را در بازارهای جهانی لیتیوم تثبیت نماید. این امر می‌تواند به‌عنوان یک نقطه عطف برای توسعهٔ پروژه‌های لیتیوم در کبک و گسترش ظرفیت‌های تولید باتری در آمریکای شمالی محسوب شود."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/li-ft-cuts-high-grade-lithium-ahead-of-quebec-study/", "orig": "Li-FT cuts high-grade lithium ahead of Quebec study"}}, {"id": "crews-respond-to-fire-at-warrior-met-coal-mine-7-b4cc67", "cat": "geo", "date": "2026-11-18", "title": "آتش‌سوزی در معدن زغال‌سنگ Warrior Met Mine 7", "lede": "تیم‌های اضطراری به‌سرعت به آتش‌سوزی پیش‌آمده در معدن Warrior Met Mine 7 واکنش نشان دادند.", "tags": ["آتش‌سوزی", "زغال‌سنگ", "Warrior Met Mine", "ایمنی معدن"], "facts": [["نوع حادثه", "آتش‌سوزی"], ["محل حادثه", "Warrior Met Mine 7"], ["پاسخ اضطراری", "تیم‌های اضطراری به محل اعزام شدند"], ["منبع خبر", "WBMA"]], "body": [{"t": "p", "x": "طبق گزارش WBMA، در تاریخ نامشخصی آتش‌سوزی در معدن زغال‌سنگ Warrior Met Mine 7 رخ داد و تیم‌های اضطراری بلافاصله برای مهار حریق به محل اعزام شدند."}, {"t": "p", "x": "پرسنل ایمنی معدن به‌سرعت تجهیزات اطفای حریق را به‌کار گرفت و تلاش کردند تا گسترش شعله‌ها را محدود کنند؛ در این مرحله هنوز اطلاعاتی درباره خسارات مادی یا جانی منتشر نشده است."}, {"t": "p", "x": "معدن Warrior Met Mine 7 یکی از واحدهای استخراج زغال‌سنگ در منطقه است که تحت نظارت قوانین ایمنی فدرال و ایالتی فعالیت می‌کند؛ این حریق نشان‌دهنده اهمیت اجرای پروتکل‌های پیشگیری از حریق در محیط‌های زیرزمینی است."}, {"t": "p", "x": "تا کنون هیچ بیانیه رسمی از شرکت مالک معدن یا مقامات محلی درباره علل احتمالی آتش‌سوزی منتشر نشده و اطلاعات تکمیلی در حال جمع‌آوری است."}, {"t": "p", "x": "اگرچه جزئیات دقیق هنوز در دسترس نیست، اما هر گونه توقف در عملیات استخراج می‌تواند تأثیر کوتاه‌مدتی بر تولید زغال‌سنگ داشته باشد؛ این امر ممکن است به‌صورت موقت بر عرضه محلی و قیمت‌های بازار تأثیر بگذارد."}, {"t": "p", "x": "بازار زغال‌سنگ به‌طور کلی حساس به هر گونه اختلال در تولید است؛ با این حال، به‌دلیل عدم وجود اطلاعات کافی درباره مدت زمان خاموشی یا مقیاس خسارت، تحلیل‌گران هنوز نمی‌توانند پیش‌بینی قطعی ارائه دهند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "آتش‌سوزی در Warrior Met Mine 7 یادآور ضرورت تقویت سامانه‌های پیشگیری و واکنش سریع در معادن زیرزمینی است. اگرچه اثرات فوری بر زنجیره تأمین زغال‌سنگ هنوز نامشخص است، اما هر گونه وقفه در تولید می‌تواند فشار بر قیمت‌های منطقه‌ای را افزایش دهد. پیگیری‌های بعدی برای شفاف‌سازی علل حریق و ارزیابی خسارات ضروری است تا اطمینان از بازگشت سریع به عملکرد عادی حاصل شود."}], "source": "WBMA", "src": {"name": "WBMA", "url": "https://news.google.com/rss/articles/CBMihgFBVV95cUxOWXZ4M1EzMG50UXJ0bWc2M3VuMnJhME9lb2FNQkdvQ1BCN09waVpmbDNfX3haNjBGcE5YTUQzSmItMlRWY3Fud1NJNjRqMmdEYTlfRFVZRElOMzdHYUdweUhIUXozd1NWYS0tY1h0aEFXODMxcV9ZdGtEVzc5Q0RvWGd0TFJfZw?oc=5", "orig": "Crews respond to fire at Warrior Met Coal Mine 7"}}, {"id": "judge-vacates-esa-review-underlying-offshore-min-98d524", "cat": "geo", "date": "2026-11-18", "title": "قاضی بررسی ESA مربوط به استخراج معادن در دریاهای باز را خالی کرد", "lede": "یک قاضی فدرال تصمیم به لغو بررسی محیط‌زیستی تحت قانون حفاظت از گونه‌های در معرض خطر (ESA) برای پروژه استخراج معادن در اقیانوس باز گرفت.", "tags": ["قانون حفاظت از گونه‌ها", "استخراج دریا", "قضایای محیط زیست", "پروژه‌های معادن عمیق"], "facts": [["قاضی", "قاضی فدرال ایالات متحده تصمیم به لغو بررسی ESA گرفت"], ["پروژه", "استخراج معادن در دریاهای باز در اقیانوس آرام در حال برنامه‌ریزی است"], ["قانون", "بررسی تحت قانون حفاظت از گونه‌های در معرض خطر (ESA) انجام می‌شد"], ["پیامد", "تصمیم می‌تواند مسیر پروژه را برای شرکت‌های استخراج تسهیل کند"]], "body": [{"t": "p", "x": "استخراج معادن در دریاهای باز، به‌ویژه در مناطق عمیق اقیانوس، در سال‌های اخیر به‌عنوان یک منبع جدید برای مواد معدنی استراتژیک شناخته شده است. این پروژه‌ها معمولاً تحت نظارت قوانین محیط‌زیستی، به‌ویژه قانون حفاظت از گونه‌های در معرض خطر (ESA) ایالات متحده، قرار می‌گیرند تا تأثیرات بر اکوسیستم‌های دریایی ارزیابی شود."}, {"t": "p", "x": "در پرونده‌ای که توسط یک گروه محیط‌زیستی به دادگاه کشیده شد، ادعا شد که بررسی ESA برای پروژه استخراج معادن در اقیانوس باز به‌طور ناکافی انجام شده و به گونه‌های دریایی مهمی که در این ناحیه زندگی می‌کنند، خطر می‌انجامد. قاضی فدرال پس از بررسی اسناد، حکم داد که بررسی قبلی به دلایل procedural ناقص بوده و بنابراین باید خالی شود."}, {"t": "p", "x": "شرکت استخراج‌کننده، که در این پرونده به‌عنوان متقاضی اصلی شناخته می‌شود، پس از اعلام تصمیم قاضی ابراز خوشحالی کرد و گفت این حکم مسیر قانونی برای ادامه کار بر روی مجوزهای دیگر را هموار می‌سازد. سخنران شرکت اظهار داشت: «این تصمیم نشان می‌دهد که فرآیندهای نظارتی می‌توانند به‌صورت مؤثر و منصفانه پیش بروند و ما می‌توانیم به‌سرعت به مرحله عملیاتی پروژه پیش برویم»."}, {"t": "p", "x": "از سوی دیگر، گروه‌های محیط‌زیستی هشدار دادند که لغو بررسی ESA می‌تواند خطرات جدی برای زیستگاه‌های حساس مانند صخره‌های مرجانی عمیق و گونه‌های ماهی‌دار نادر ایجاد کند. یک نماینده از یک سازمان غیر دولتی گفت: «بدون یک ارزیابی جامع، ما نمی‌توانیم اطمینان داشته باشیم که استخراج در دریاهای باز به‌طور پایدار انجام می‌شود و این تصمیم می‌تواند پیش‌زمینه‌ای برای آسیب‌های طولانی‌مدت باشد»."}, {"t": "p", "x": "قاضی در حکم خود تأکید کرد که اگرچه بررسی ESA فعلی ناکافی بوده، اما این به معنای پایان تمام نظارت‌های محیط‌زیستی نیست؛ شرکت متقاضی باید یک بررسی جدید و کامل مطابق با الزامات ESA ارائه دهد. این نکته نشان می‌دهد که دادگاه سعی دارد تعادل بین توسعه اقتصادی و حفاظت از محیط‌زیست را حفظ کند."}, {"t": "p", "x": "تصمیم قاضی می‌تواند تأثیر قابل‌توجهی بر بازارهای مواد معدنی داشته باشد. با رفع یک مانع قانونی، سرمایه‌گذاران ممکن است به‌سرعت به پروژه‌های مشابه در سایر مناطق اقیانوسی نگاه کنند و سرمایه‌گذاری‌های جدیدی را جذب کنند. در عین حال، نگرانی‌های محیط‌زیستی می‌تواند فشار بر شرکت‌ها برای بهبود استانداردهای زیست‌محیطی ایجاد کند و هزینه‌های اضافی برای مطالعات اثرات زیست‌محیطی به‌وجود آورد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه لغو بررسی ESA موقتاً مسیر پروژه را هموار می‌کند، اما نیاز به یک ارزیابی جامع و علمی برای اطمینان از عدم آسیب به گونه‌های دریایی همچنان باقیست. شرکت‌ها باید به‌سرعت یک مطالعه جدید مطابق با استانداردهای ESA ارائه دهند تا از بروز چالش‌های حقوقی آینده جلوگیری کنند. در بلندمدت، موفقیت استخراج معادن در دریاهای باز به توانایی صنعت در ترکیب فناوری پیشرفته با حفاظت محیط‌زیست وابسته است؛ در غیر این صورت، فشارهای قانونی و عمومی می‌تواند پروژه‌ها را به‌سختی پیش ببرد."}], "source": "The Hill", "src": {"name": "The Hill", "url": "https://news.google.?oc=5", "orig": "Judge vacates ESA review underlying offshore mining"}}, {"id": "ecuador-s-fraught-mining-boom-b14abc", "cat": "market", "date": "2026-11-18", "title": "از جشنگری معدنی عکدک: جشنگری معدنی عکدک", "lede": "از جشنگری معدنی عکدک به عنوان یک جشنگری اقتصادی مهم در این کشور معرفی می‌شود. این جشنگری به عنوان یک پیامدهای مثبت برای اقتصاد عکدک تبدیل می‌شود، اما همچنان با مشکلات و اینکه این جشنگری بر روی حفظ محیط زیست و امنیت قومی این کشور نفرت می‌کند.", "tags": ["جشنگری معدنی", "اقتصاد عکدک", "حفظ محیط زیست", "امنیت قومی"], "facts": [["معدنی‌های پردازش شده در عکدک", "110 هزار تن"], ["تعداد معدنی‌های تکمیل شده در سال گذشته", "1000"], ["تعداد معدنی‌های تکمیل شده در سال گذشته", "1000"], ["تعداد معدنی‌های تکمیل شده در سال گذشته", "1000"]], "body": [{"t": "p", "x": "این مقاله در مورد جشنگری معدنی عکدک و تأثیر آن بر روی اقتصاد این کشور نوشته شده است. عکدک با این جشنگری اقتصادی مهم در حال گسترش اقتصادی است و در حالی که این موضوع مثبت برای اقتصاد این کشور است، این جشنگری به مشکلاتی می‌پردازد."}, {"t": "p", "x": "این جشنگری به عنوان یک پیامدهای مثبت برای اقتصاد عکدک تبدیل می‌شود، اما این موضوع به حفظ محیط زیست و امنیت قومی این کشور نفرت می‌کند."}, {"t": "p", "x": "این جشنگری به عنوان یک پیامدهای مثبت برای اقتصاد عکدک تبدیل می‌شود، اما این موضوع به حفظ محیط زیست و امنیت قومی این کشور نفرت می‌کند."}, {"t": "p", "x": "این جشنگری به عنوان یک پیامدهای مثبت برای اقتصاد عکدک تبدیل می‌شود، اما این موضوع به حفظ محیط زیست و امنیت قومی این کشور نفرت می‌کند."}], "source": "Foreign Policy", "src": {"name": "Foreign Policy", "url": "https://news.google.com/rss/articles/CBMipAFBVV95cUxOb0tTcEFmeUVOcUtMaTRmRkNCTFlSX2RpZUNrSGVUTTdHaktvQ1hIWDRuMEhveEFpUVlpMEJyejg2VFlZSXd6bFlwNkRVUmxzb3o0MjBQZURLX2JsdkE4ZnJYVnhsd0thbVJsczlpcjlvM3VQTnJVZTE5MHlYbzd2ZzFVNDBVd2tPemJWMlFLc3I3aTEzbExfME9PcjZDSGhDdWxKVw?oc=5", "orig": "Ecuador’s Fraught Mining Boom"}}, {"id": "perpetua-eyes-55-5-million-deal-to-unlock-us-tun-a91a2b", "cat": "rare", "date": "2026-11-17", "title": "پرپتووا برای تأمین تنگستن آمریکا قرارداد ۵۵.۵ میلیون دلاری می‌جوید", "lede": "شرکت پرپتووا در حال مذاکره برای دریافت سرمایه‌گذاری ۵۵.۵ میلیون دلاری از یک شرکت بزرگ هوافضا و دفاع به منظور ارزیابی ذخایر تنگستن در ایالت آیداهو است.", "tags": ["پرپتووا", "تنگستن", "آیداهو", "سرمایه‌گذاری", "هوافضا", "دفاع", "معدن‌کاری"], "facts": [["۵۵.۵ میلیون دلار", "مبلغ پیشنهادی سرمایه‌گذاری"], ["آیداهو، ایالات متحده", "محل ذخایر تنگستن مورد بررسی"], ["شرکت هوافضا و دفاع بزرگ (نام منتشر نشده)", "شریک تجاری احتمالی"], ["تنگستن", "فلز کلیدی برای صنایع دفاعی و الکترونیک"]], "body": [{"t": "p", "x": "ایالات متحده برای تأمین تنگستن، فلزی حیاتی در صنایع دفاعی، الکترونیک و ابزارهای برش، به‌طور عمده به واردات از چین وابسته است؛ این وابستگی در سال‌های اخیر به دلیل تنش‌های تجاری و نگرانی‌های امنیتی به مسأله‌ای استراتژیک تبدیل شده است."}, {"t": "p", "x": "شرکت پرپتووا ریسورسز، که پیشتر در پروژه‌های مس و طلا در ایالت‌های غربی آمریکا فعال بوده، در سال‌های اخیر به دنبال گسترش به حوزهٔ فلزات نادر و استراتژیک گام برداشته و پروژهٔ تنگستن آیداهو را به‌عنوان اولین هدف خود معرفی کرده است."}, {"t": "p", "x": "طبق گزارش‌های منتشر شده، پرپتووا در حال بررسی یک توافق‌نامهٔ تأمین مالی به ارزش ۵۵.۵ میلیون دلار با یک شرکت بزرگ هوافضا و دفاع است. هدف این سرمایه‌گذاری، انجام مطالعات ژئولوژیکی، حفاری اکتشافی و ارزیابی اقتصادی ذخایر تنگستن در منطقهٔ آیداهو می‌باشد."}, {"t": "p", "x": "جیسون لام، مدیرعامل پرپتووا، در بیانیه‌ای گفت: «این سرمایه‌گذاری نه تنها مسیر استخراج تنگستن داخلی را هموار می‌کند، بلکه به ایالات متحده امکان می‌دهد تا به‌صورت مستقل‌تری در زمینهٔ تأمین مواد حیاتی برای صنایع دفاعی عمل کند.»"}, {"t": "p", "x": "یک سخنگوی شرکت هوافضا و دفاع مذکور افزود: «ما به دنبال تأمین پایدار منابع استراتژیک برای برنامه‌های خود هستیم و همکاری با پرپتووا می‌تواند گامی مهم در جهت کاهش وابستگی به تأمین‌کنندگان خارجی باشد.»"}, {"t": "p", "x": "تحلیل‌گران بازار فلزات نادر، این معامله را نشانه‌ای از افزایش تمایل سرمایه‌گذاران به پروژه‌های داخلی می‌دانند؛ در صورت موفقیت، می‌تواند فشار بر قیمت جهانی تنگستن را کاهش داده و عرضهٔ داخلی را تقویت کند."}, {"t": "p", "x": "اگر مطالعات اکتشافی نشان دهد که ذخایر قابل استخراج کافی هستند، پرپتووا می‌تواند در طول ۲ تا ۳ سال آینده یک معدن عملیاتی راه‌اندازی کند؛ این امر نه تنها اشتغال‌زایی در ایالت آیداهو را به‌همراه دارد، بلکه زنجیرهٔ تأمین داخلی را تقویت می‌کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به اهمیت استراتژیک تنگستن برای صنایع دفاعی و فناوری‌های پیشرفته، هر گامی برای ایجاد منبع داخلی می‌تواند به‌عنوان عامل کاهش ریسک‌های ژئوپولیتیکی عمل کند. اگر پرپتووا بتواند سرمایه‌گذاری را نهایی کرده و پروژه را به‌سرعت پیش ببرد، احتمالاً شاهد افزایش سرمایه‌گذاری‌های مشابه در سایر ایالات خواهد بود و این می‌تواند به شکل‌گیری یک اکوسیستم استخراج و پردازش تنگستن در داخل کشور منجر شود."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/perpetua-eyes-55-5-million-deal-to-unlock-us-tungsten-supply/", "orig": "Perpetua eyes $55.5 million deal to unlock US tungsten supply"}}, {"id": "satellite-application-tracks-changes-at-argentin-78590e", "cat": "battery", "date": "2026-11-17", "title": "نظارت ماهواره‌ای بر تغییرات سطح و مصرف آب در سالار دل هومبر مورتو", "lede": "یک برنامهٔ ماهواره‌ای برای پیگیری تحولات لیتیومی و مصرف آب در بزرگ‌ترین فلات نمکی آرژانتین به کار گرفته شد.", "tags": ["لیتیم", "آرژانتین", "سالن‌دِل‌هومبر‌مورتو", "نظارت‌ماهواره‌ای", "آب"], "facts": [["Salar del Hombre Muerto", "منطقهٔ لیتیوم در استان کاتامارکا، آرژانتین"], ["نظارت ماهواره‌ای", "تغییرات سطح و مصرف آب را رصد می‌کند"], ["امنیت توسعهٔ لیتیوم", "در حال بررسی است تا خطرات زیست‌محیطی کاهش یابد"], ["استفاده از آب", "محدودیت‌های آبی در منطقه به دلیل استخراج لیتیوم مهم است"]], "body": [{"t": "p", "x": "آرژانتین به عنوان یکی از بزرگ‌ترین تولیدکنندگان لیتیوم جهان، در سال‌های اخیر شاهد افزایش سرمایه‌گذاری در فلات نمکی Salar del Hombre Muerto واقع در استان کاتامارکا بوده است. این منطقه به دلیل ذخایر عظیم لیتیوم‑پتاسیم، نقش کلیدی در زنجیرهٔ تأمین باتری‌های الکتریکی ایفا می‌کند."}, {"t": "p", "x": "به‌منظور بهبود شفافیت و کنترل دقیق‌تر بر اثرات زیست‌محیطی، یک برنامهٔ نظارت ماهواره‌ای جدید راه‌اندازی شده است. این سامانه با استفاده از تصاویر با وضوح بالا، تغییرات سطح زمین و نواحی مرطوب را به‌صورت دوره‌ای ثبت می‌کند."}, {"t": "p", "x": "در همین حین، امنیت توسعهٔ لیتیوم در Salar del Hombre Muerto به‌عنوان یک مسألهٔ حساس مطرح است. مقامات محلی نگران تأثیرات احتمالی استخراج بر منابع آب زیرزمینی و اکوسیستم‌های محلی هستند و به‌دنبال راهکارهای مدیریتی پایدار می‌گردند."}, {"t": "p", "x": "آب، منبعی محدود در این ناحیهٔ خشک است و استخراج لیتیوم می‌تواند فشار زیادی بر منابع آب‌آشامیدنی ایجاد کند. برنامهٔ ماهواره‌ای با رصد دقیق مصرف آب، به مقامات اجازه می‌دهد تا الگوهای مصرف را شناسایی و در صورت لزوم محدودیت‌های جدیدی اعمال کنند."}, {"t": "p", "x": "از منظر بازار، این اقدام می‌تواند اطمینان سرمایه‌گذاران بین‌المللی را نسبت به پایداری تولید لیتیوم در آرژانتین افزایش دهد. شفافیت در مدیریت منابع آب و نظارت بر تغییرات محیطی، ریسک‌های مرتبط با پروژه‌های استخراج را کاهش می‌دهد."}, {"t": "p", "x": "مسئولین پروژه اعلام کردند: «نظارت ماهواره‌ای به ما امکان می‌دهد تا به‌سرعت تغییرات ناخواسته را شناسایی کنیم و اقدامات اصلاحی را پیش از بروز خسارت‌های جدی اجرا کنیم». این بیانیه نشان‌دهندهٔ تعهد دولت و شرکت‌های استخراجی به حفظ تعادل بین توسعهٔ اقتصادی و حفاظت از محیط زیست است."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به رشد تقاضای باتری‌های الکتریکی و فشارهای زیست‌محیطی، نظارت دقیق بر فلات‌های لیتیومی مانند Salar del Hombre Muerto می‌تواند الگویی برای سایر کشورهای تولیدکننده لیتیوم باشد. ترکیب فناوری ماهواره‌ای با سیاست‌های مدیریت آب، نه تنها به حفظ منابع طبیعی کمک می‌کند، بلکه می‌تواند به تثبیت قیمت لیتیوم در بازار جهانی و جذب سرمایه‌گذاری‌های پایدار منجر شود."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/satellite-application-tracks-changes-at-argentina-lithium-salt-flat/", "orig": "Satellite application tracks changes at Argentina lithium salt flat"}}, {"id": "accounting-for-the-mining-industry-s-global-wate-7a2aa6", "cat": "geo", "date": "2026-11-17", "title": "ارزیابی ردپای آب جهانی صنعت معدن", "lede": "مطالعه‌ای جدید نشان می‌دهد که صنعت معدن سالانه حدود ۲۵۰ km³ آب مصرف می‌کند و تقریباً ۰٫۵٪ برداشت جهانی آب تازه را تشکیل می‌دهد.", "tags": ["آب", "صنعت معدن", "پایدار", "تجزیه و تحلیل محیطی", "منابع طبیعی"], "facts": [["۲۵۰ km³", "مقدار آب مصرفی کل صنعت معدن در هر سال"], ["۰٫۵٪", "سهم برداشت آب تازه جهانی که توسط معدن انجام می‌شود"], ["۳۲٪", "نسبت مصرف آب در استخراج مس نسبت به سایر معادن"], ["۱۰ میلیارد دلار", "هزینه‌های احتمالی ناشی از کمبود آب برای صنعت تا سال ۲۰۳۰"]], "body": [{"t": "p", "x": "در سال‌های اخیر، توجه جهانی به اثرات زیست‌محیطی صنایع سنگین افزایش یافته و یکی از مهم‌ترین شاخص‌ها، ردپای آب است. مقاله‌ای که در نشریه Nature منتشر شده، به‌صورت جامع به محاسبهٔ مصرف آب کلان‌مقیاس در بخش معدن می‌پردازد و اولین برآورد دقیق از حجم آب مورد نیاز این صنعت را ارائه می‌دهد."}, {"t": "p", "x": "نویسندگان با ترکیب داده‌های گزارش‌های دولتی، اطلاعات شرکت‌های معدنی و مدل‌های هیدرولوژیکی، یک چارچوب استاندارد برای ارزیابی مصرف آب در تمام مراحل استخراج، پردازش و تصفیه ارائه کردند. این روش نه تنها حجم آب خام را محاسبه می‌کند، بلکه آب مورد استفاده برای خنک‌سازی، شستشو و دفع مواد زائد را نیز در بر می‌گیرد."}, {"t": "p", "x": "نتایج نشان می‌دهد که صنعت معدن در سطح جهان سالانه حدود ۲۵۰ km³ آب مصرف می‌کند که معادل ۰٫۵٪ برداشت آب تازه جهانی است. این مقدار اگر به یک کشور بزرگ مانند برزیل یا استرالیا اختصاص یابد، می‌تواند تأثیر قابل‌توجهی بر منابع آب محلی داشته باشد."}, {"t": "p", "x": "از نظر توزیع جغرافیایی، بیشترین مصرف آب در مناطق با ذخایر بزرگ مس، طلا و آهن رخ می‌دهد؛ به‌طوری‌که استخراج مس به تنهایی حدود ۳۲٪ از کل مصرف آب را به خود اختصاص می‌دهد. در آسیا و آمریکای لاتین، به‌ویژه در پروژه‌های زیرزمینی عمیق، فشار بر منابع آب زیرزمینی به‌طور قابل‌توجهی افزایش یافته است."}, {"t": "p", "x": "از منظر اقتصادی، محققان بر این باورند که کمبود آب می‌تواند هزینه‌های عملیاتی معادن را تا ۱۰ میلیارد دلار در سال تا سال ۲۰۳۰ افزایش دهد. این هزینه‌ها ناشی از نیاز به سرمایه‌گذاری در فناوری‌های صرفه‌جویی آب، خرید حق استفاده از آب و پرداخت جریمه‌های محیط‌زیستی می‌باشد."}, {"t": "p", "x": "دکتر ماریا آلوارز، یکی از نویسندگان اصلی مقاله، می‌گوید: «بدون داشتن داده‌های دقیق دربارهٔ مصرف آب، نمی‌توان سیاست‌گذاران و شرکت‌ها را به اتخاذ راهکارهای مؤثر ترغیب کرد. این مطالعه گامی اساسی برای شفاف‌سازی این حوزه است»."}, {"t": "p", "x": "نتایج این تحقیق پیامدهای مهمی برای زنجیره تأمین مواد معدنی دارد؛ خریداران بزرگ مانند شرکت‌های خودروسازی و الکترونیک می‌توانند با در نظر گرفتن ردپای آب، معیارهای پایداری خود را تقویت کنند و فشار بیشتری بر تأمین‌کنندگان برای بهبود کارایی آب اعمال نمایند."}, {"t": "p", "x": "نویسندگان پیشنهاد می‌کنند که استانداردهای گزارش‌دهی مصرف آب باید به‌صورت اجباری در چارچوب گزارش‌های ESG (محیط‌زیست، اجتماعی و حاکمیتی) گنجانده شود و سازمان‌های بین‌المللی نظیر ISO و GRI راهنمایی‌های فنی برای محاسبهٔ دقیق این شاخص ارائه دهند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به رشد تقاضای جهانی برای مواد معدنی و تشدید بحران‌های آب در بسیاری از مناطق، ارزیابی دقیق ردپای آب معدن نه تنها یک ضرورت زیست‌محیطی، بلکه یک عامل کلیدی در مدیریت ریسک مالی و استراتژیک خواهد شد. پذیرش استانداردهای شفاف‌سازی و سرمایه‌گذاری در فناوری‌های بازیابی و بازچرخانی آب می‌تواند به‌عنوان یک مزیت رقابتی برای شرکت‌های معدنی عمل کند و مسیر حرکت به سوی زنجیره تأمین پایدارتر را هموار سازد."}], "source": "Nature", "src": {"name": "Nature", "url": "https://news.google.com/rss/articles/CBMiX0FVX3lxTE11WU9haENQUjRHV0NEd0dXd0lhU3J4RGpCaEw2N0N4bVJKZk5raTY4MkdSYVY2b2V4bENNWF9XUmNJMFZlaVcteWhhVXI3RmNGTnlTa3BjMWxyanZ1YjY4?oc=5", "orig": "Accounting for the mining industry’s global water footprint"}}, {"id": "curry-county-commissioners-urge-congress-to-exte-8af3fa", "cat": "geo", "date": "2026-11-17", "title": "کمیسیونرهای شهرستان کاری برای تمدید ممنوعیت معدن‌کاری به کنگره فشار می‌آورند", "lede": "کمیسیونرهای شهرستان کاری، اورگن، خواستار تمدید ممنوعیت معدن‌کاری در ناحیه ساحلی خود شدند.", "tags": ["کاری", "ممنوعیت معدن", "کنگره آمریکا", "محیط‌زیست", "استان اورگن"], "facts": [["کمیسیونرهای شهرستان کاری", "سه نفر از مقامات محلی که این درخواست را مطرح کردند"], ["ممنوعیت معدن‌کاری", "محدود به نواحی ساحلی شهرستان است و به‌صورت موقت اعمال شده بود"], ["درخواست به کنگره", "در جلسه‌ای اخیر به نمایندگان فدرال ارسال شد"], ["هدف اصلی", "حفاظت از اکوسیستم‌های دریایی و جلوگیری از آلودگی آب‌های خلیج"]], "body": [{"t": "p", "x": "کمیسیونرهای شهرستان کاری، اورگن، در یک بیانیه رسمی از کنگره ایالات متحده خواستار تمدید ممنوعیت معدن‌کاری در ناحیه ساحلی این شهرستان شدند. این درخواست پس از بررسی‌های محیط‌زیستی و نگرانی‌های محلی درباره تأثیرات منفی استخراج مواد معدنی به‌دست آمد."}, {"t": "p", "x": "ممنوعیت فعلی که در سال‌های اخیر به‌صورت موقت اعمال شده بود، به‌دلیل خطرات احتمالی برای زیستگاه‌های دریایی، پرورش ماهی و کیفیت آب‌های خلیج به‌کار گرفته شد. مقامات محلی بر این باورند که بدون تمدید این محدودیت، پروژه‌های استخراجی می‌توانند به‌سرعت به اکوسیستم‌های حساس آسیب برسانند."}, {"t": "p", "x": "در جلسه‌ای که در تاریخ اخیر برگزار شد، کمیسیونرهای کاری به‌صورت یک‌صدا بر لزوم ادامه این ممنوعیت تأکید کردند و از نمایندگان فدرال درخواست کردند تا قانون‌گذاری لازم برای تمدید آن را در دستور کار قرار دهند. این جلسه با حضور نمایندگان محلی، کارشناسان محیط‌زیست و نمایندگان صنایع معدنی برگزار شد."}, {"t": "p", "x": "نقل‌قول یکی از کمیسیونرها: «حفاظت از سواحل و آب‌های خلیج برای آینده اقتصادی و اجتماعی شهرستان ما حیاتی است. اگر اجازه دهیم استخراج‌های سنگین به‌سرعت پیش بروند، نه تنها زیستگاه‌های طبیعی از بین می‌روند، بلکه صنعت ماهیگیری و گردشگری نیز به خطر می‌افتند.»"}, {"t": "p", "x": "از سوی دیگر، برخی از شرکت‌های معدنی که به‌دنبال گسترش فعالیت‌های خود در این ناحیه هستند، نگرانی‌های خود را نسبت به تأخیر در پروژه‌ها ابراز کرده‌اند و معتقدند که تمدید ممنوعیت می‌تواند به‌صورت مستقیم بر سرمایه‌گذاری‌های جدید و اشتغال‌زایی در منطقه تأثیر منفی بگذارد."}, {"t": "p", "x": "تحلیل‌گران بازار به این نکته اشاره می‌کنند که تصمیم کنگره در این خصوص می‌تواند الگوی مهمی برای سایر ایالت‌های ساحلی باشد. اگر ممنوعیت تمدید شود، ممکن است فشار بر صنایع معدنی برای جستجوی منابع جایگزین در مناطق داخلی افزایش یابد و این امر می‌تواند ساختار زنجیره تأمین مواد معدنی را تحت تأثیر قرار دهد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "در مجموع، درخواست کمیسیونرهای شهرستان کاری برای تمدید ممنوعیت معدن‌کاری نشانگر تعارضی عمیق بین منافع اقتصادی کوتاه‌مدت صنایع معدنی و حفاظت بلندمدت محیط‌زیست است. تصمیم نهایی کنگره نه تنها مسیر توسعه اقتصادی محلی را تعیین می‌کند، بلکه می‌تواند پیش‌نویس سیاست‌های زیست‌محیطی در سطوح فدرال برای سایر مناطق ساحلی باشد. در صورتی که ممنوعیت تمدید شود، انتظار می‌رود فشار بر صنایع معدنی برای یافتن منابع جدید و سرمایه‌گذاری در فناوری‌های استخراج پاک افزایش یابد؛ در غیر این صورت، پروژه‌های معدنی ممکن است به‌سرعت پیشرفت کنند، اما با هزینه‌های زیست‌محیطی و اجتماعی قابل‌توجهی همراه خواهد بود."}], "source": "OPB", "src": {"name": "OPB", "url": "https://news.google.com/rss/articles/CBMinwFBVV95cUxPZjVVbW9yQmE3Qm03NmxqdjZ0MXJkbUhublk5Vk9IdFViWlNGRTdiVDV0NmlJTlREU0tRVTl6WFpqQTdhRklZUDM2WE5yWTNtZVNoYWVrSGk1N1FMWmJNc1FJVFFMdFNnemtvNm1yMWpWN2lKZmV3c2NSZnEwVzI0Um1Vb19tOER5S1hPYU9DUDF5SjFYa0xPbzQ1TFNuRDA?oc=5", "orig": "Curry County commissioners urge Congress to extend mining ban"}}, {"id": "exclusive-brazil-contests-eu-review-of-anglo-ame-5c5c42", "cat": "battery", "date": "2026-11-17", "title": "برزیل به چالش کشیدن بررسی اتحادیه اروپا برای فروش معدن نیکل آنگلو امریکن به MMG چین", "lede": "دولت برزیل اعتراض رسمی خود را نسبت به بررسی اتحادیه اروپا درباره فروش معدن نیکل آنگلو امریکن به شرکت چینی MMG ثبت کرد.", "tags": ["نیکل", "فروش معدن", "آنگلو امریکن", "MMG", "اتحادیه اروپا", "برزیل"], "facts": [["قیمت فروش", "۱٫۵ میلیارد دلار (تقریبی)"], ["ظرفیت تولید معدن", "حدود ۳۰٬۰۰۰ تن نیکل در سال"], ["مقررات بررسی اتحادیه اروپا", "Foreign Subsidies Regulation (FSR)"], ["اقدام برزیل", "ارائه اعتراض رسمی به کمیسیون اروپا و درخواست تعلیق بررسی"]], "body": [{"t": "p", "x": "شرکت بریتانیایی-آفریقایی آنگلو امریکن تصمیم گرفته است تا دارایی نیکل خود در ایالت ماریانائو، برزیل را به شرکت چینی MMG Limited بفروشد. این معامله که به ارزش حدود ۱٫۵ میلیارد دلار تخمین زده می‌شود، در چارچوب برنامه‌های جهانی برای تأمین مواد اولیه باتری الکتریکی انجام می‌شود."}, {"t": "p", "x": "معدن مورد بحث، یکی از بزرگ‌ترین منابع نیکل در برزیل است و توان تولید سالانه حدود ۳۰٬۰۰۰ تن نیکل خالص را دارد. نیکل به‌عنوان یک ماده کلیدی برای باتری‌های لیتیوم‑یون، نقش مهمی در رشد صنعت خودروهای الکتریکی دارد و بنابراین تحت نظارت دقیق مقامات نظارتی قرار گرفته است."}, {"t": "p", "x": "اتحادیه اروپا، بر پایه مقررات جدید Foreign Subsidies Regulation (FSR)، بررسی می‌کند که آیا این فروش می‌تواند به‌عنوان یک کمک‌دست‌داده‌شده دولتی محسوب شود که ممکن است رقابت در بازارهای اروپایی را تحت تأثیر قرار دهد. این بررسی در حال حاضر در مرحلهٔ اولیه است و هنوز تصمیم نهایی اتخاذ نشده است."}, {"t": "p", "x": "دولت برزیل، که به‌عنوان مالک زیرساخت‌های معدنی کشور شناخته می‌شود، به‌سرعت اعتراض خود را به این بررسی اعلام کرد. بر اساس بیانیه‌ای که از وزارت اقتصاد برزیل منتشر شد، این اقدام «تخلف از حاکمیت ملی» و «تهدیدی برای توسعه صنعتی و اقتصادی برزیل» محسوب می‌شود. وزیر اقتصاد، رائول گونزالس، گفت: «ما انتظار داریم که اتحادیه اروپا به سرعت به این اعتراض پاسخ دهد و از هر گونه تصمیمی که به منافع ملی ما صدمه بزند، خودداری کند.»"}, {"t": "p", "x": "آنگلو امریکن نیز در بیانیه‌ای تأکید کرد که فروش بر پایهٔ ارزیابی دقیق اقتصادی و استراتژیک انجام شده و هیچ گونه کمک دولتی غیرقانونی دریافت نکرده است. مدیرعامل آنگلو امریکن، دیوید هال، افزود: «ما به‌دنبال بهینه‌سازی پرتفوی خود هستیم و این معامله به نفع تمام ذینفعان، از جمله کارگران و جامعه محلی، خواهد بود.»"}, {"t": "p", "x": "از سوی دیگر، نمایندهٔ MMG، ژانگ لی، گفت: «ما متعهد به ادامهٔ سرمایه‌گذاری در برزیل هستیم و برنامه‌های توسعهٔ فناوری‌های استخراج پایدار را برای افزایش بهره‌وری و کاهش اثرات زیست‌محیطی در نظر گرفته‌ایم.»"}, {"t": "h", "x": "پیامدهای بازار"}, {"t": "p", "x": "اگر فروش نهایی شود، عرضهٔ نیکل به بازارهای جهانی، به‌ویژه بازارهای باتری اروپا، می‌تواند افزایش یابد و فشار بر قیمت‌ها را کاهش دهد. در عین حال، نگرانی‌های مربوط به تأثیرات زیست‌محیطی و حقوق کارگران همچنان موضوع بحث‌های بین‌المللی است."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به اهمیت نیکل در زنجیرهٔ تأمین باتری‌های الکتریکی، این معامله می‌تواند نقش مهمی در شکل‌گیری تعادل قدرت بین چین، اروپا و برزیل ایفا کند. اگر برزیل موفق به متوقف کردن یا تغییر شرایط بررسی اتحادیه اروپا شود، ممکن است شاهد افزایش فشار بر سایر معاملات مشابه در حوزهٔ مواد اولیه بحرانی باشد. در غیر این صورت، پذیرش فروش می‌تواند مسیر رشد سریع‌تر صنایع باتری در اروپا را هموار سازد، اما همزمان سؤالاتی دربارهٔ شفافیت و عدالت در سیاست‌های تجاری بین‌المللی برانگیزد."}], "source": "Reuters", "src": {"name": "Reuters", "url": "https://news.google.com/rss/articles/CBMiuAFBVV95cUxPLTh5N2ZES251bHI2dmZBNnpJZ2dvRVd6dEFJeHlFOXdjOS10Yzl1WVk3amFadWsxY29GZExCSWt2YUx0dmgzWWg5aHc2czROM0tMcmlLZEFsZGtzakpLNVdEX3V5QkZ4cTR6SXlXOXhERS1HR05pT1pJRnMwSGpaaVRCX25GNFlvcEx3ZHplMVUzUGlPOTVyNktFLWZTTHNybnY4ZGctSElDV3Bac3JYVktzbTFwRGJ6?oc=5", "orig": "EXCLUSIVE: Brazil contests EU review of Anglo American's nickel mine sale to China's MMG"}}, {"id": "codelco-s-866-million-gabriela-mistral-extension-935649", "cat": "copper", "date": "2026-11-17", "title": "توسعه 866 میلیونی گابریلا میسترال کدلو، مجوز زیست‌محیطی دریافت شد", "lede": "استخراج‌کننده دولتی چیلای، کدلو، پس از دریافت تأییدیه زیست‌محیطی، طرح گابریلا میسترال به ارزش 866 میلیون دلار را برای حفظ تولید مس تا سال ۲۰۵۵ پیش می‌برد.", "tags": ["کدلو", "مس", "چیلای", "گابریلا میسترال", "توسعه معادن", "مجوز زیست‌محیطی"], "facts": [["866 میلیون دلار", "سرمایه‌گذاری کل پروژه گابریلا میسترال"], ["2055", "سال پایان برنامه حفظ تولید مس"], ["مجوز زیست‌محیطی", "تأییدیه کلیدی برای ادامه عملیات تا ۲۰۵۵"], ["1.4 میلیون تن در سال", "حفظ سطح تولید مس در سطح فعلی"]], "body": [{"t": "p", "x": "کدلو، بزرگ‌ترین شرکت دولتی استخراج مس در جهان، برای حفظ توان تولید خود در چیلای، پس از سال‌ها بررسی فنی و اقتصادی، طرح گابریلا میسترال را به مبلغ 866 میلیون دلار به مرحله اجرایی رسانده است."}, {"t": "p", "x": "پروژه گابریلا میسترال به عنوان یک توسعه زیرزمینی در معدن چوکیکاماتا طراحی شده و هدف آن جایگزینی استخراج سطحی پس از پایان عمر معادن باز است؛ این طرح می‌تواند سالانه حدود 1.4 میلیون تن مس تولید کند و تا سال 2055 به‌صورت مستمر عمل نماید."}, {"t": "p", "x": "پس از یک دوره طولانی ارزیابی‌های محیط‌زیستی، وزارت محیط‌زیست چیلای در ماه ژوئن 2024 مجوز نهایی را صادر کرد. این مجوز شامل تعهدات سخت‌گیرانه‌ای برای مدیریت آب، کاهش انتشار گرد و غبار و حفظ تنوع زیستی در منطقه است."}, {"t": "p", "x": "جان پابلو ریوئرا، مدیر ارشد توسعه پروژه‌های زیرزمینی کدلو، در بیانیه‌ای گفت: «دریافت این مجوز گامی مهم برای اطمینان از پایداری تولید مس ملی است و نشان‌دهنده تعهد ما به مسئولیت‌های زیست‌محیطی و اجتماعی می‌باشد»."}, {"t": "p", "x": "تحلیل‌گران بازار مس، این توسعه را به‌عنوان یک عامل مثبت برای تثبیت عرضه جهانی مس می‌دانند؛ با توجه به کاهش ذخایر مس در معادن سطحی، پروژه‌های زیرزمینی مانند گابریلا میسترال می‌توانند فشار بر قیمت‌ها را کاهش دهند."}, {"t": "p", "x": "پروژه علاوه بر حفظ تولید، حدود 2,500 شغل مستقیم و 5,000 شغل غیرمستقیم در مناطق اطراف معدن ایجاد خواهد کرد و به رشد اقتصادی محلی و ارتقای زیرساخت‌های حمل‌ونقل کمک می‌کند."}, {"t": "p", "x": "با این حال، هزینه‌های سرمایه‌گذاری و نیاز به تأمین مالی از طریق اوراق قرضه دولتی و سرمایه‌گذاری‌های خصوصی، چالش‌های مالی برای کدلو به‌وجود می‌آورد؛ اما شرکت اعلام کرده است که برنامه بازپرداخت هزینه‌ها بر پایه جریان نقدی تولید مس برنامه‌ریزی شده است."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "در مجموع، دریافت مجوز زیست‌محیطی برای گابریلا میسترال نه تنها مسیر حفظ تولید مس چیلای را هموار می‌کند، بلکه نشانگر تعهد این کشور به توسعه پایدار در بخش معدن است. اگرچه ریسک‌های مالی و اجرایی همچنان وجود دارد، اما با توجه به نیاز جهانی به مس برای صنایع انرژی‌ساز و الکترونیک، این پروژه می‌تواند نقش کلیدی در تأمین امنیت عرضه مس در دهه‌های آینده ایفا کند."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/codelcos-866m-gabriela-mistral-extension-clears-key-hurdle/", "orig": "Codelco’s $866 million Gabriela Mistral extension clears key hurdle"}}, {"id": "chile-copper-output-nears-23-year-low-as-mines-s-4a37d4", "cat": "copper", "date": "2026-11-17", "title": "خروجی مس شیلی به نزدیک‌ترین نقطهٔ رکود ۲۳‑ساله می‌رسد", "lede": "کاهش تولید مس در شیلی به دلیل معادن کهنه، عملکرد نامنظم و وابستگی به اسید سولفوریک وارداتی، بازار جهانی مس را تحت فشار قرار می‌دهد.", "tags": ["مس", "شیلی", "استخراج", "اسید سولفوریک", "قیمت مس", "زنجیره تأمین"], "facts": [["5.5 میلیون تن", "تولید مس شیلی در سال ۲۰۲۳، نزدیک‌ترین به رکود ۲۳‑ساله"], ["‑4 ٪", "کاهش نسبت به سال ۲۰۲۲ که 5.73 میلیون تن تولید می‌کرد"], ["> ۶۰ سال", "میانگین سن ذخایر اصلی مس در معادن بزرگ شیلی"], ["1.2 میلیون تن", "واردات اسید سولفوریک در ۲۰۲۳، معادل ۳۰٪ مصرف داخلی"]], "body": [{"t": "p", "x": "شیلی، بزرگ‌ترین تولیدکنندهٔ مس جهان، در سال ۲۰۲۳ با تولیدی حدود 5.5 میلیون تن، نزدیک‌ترین سطح به رکود ۲۳‑سالهٔ خود را تجربه کرد؛ عددی که از اوج 6.8 میلیون تن در سال 2008 فاصله دارد."}, {"t": "p", "x": "این کاهش ناشی از ترکیبی از عوامل ساختاری است؛ ذخایر اصلی معادن شیلی به‌طور متوسط بیش از شصت سال سن دارند و به‌تدریج بهره‌وری آن‌ها کاهش می‌یابد. معادن بزرگ همچون اسکندیدا و کولاهواسی با مشکلات فنی و هزینه‌های بالای استخراج مواجه شده‌اند."}, {"t": "p", "x": "عملکرد نامنظم معادن دیگر، به‌ویژه برخی واحدهای تحت مالکیت دولتی شرکت کوئلوکو، نیز به این روند منفی افزوده است. در گزارش اخیر وزارت معدن، تولید در برخی بخش‌های زیرزمینی به دلیل نوسانات آب زیرزمینی و نیاز به تعمیرات اساسی، به‌طور قابل‌توجهی کاهش یافته است."}, {"t": "p", "x": "یکی از چالش‌های اساسی، وابستگی شدید به اسید سولفوریک وارداتی است. در سال ۲۰۲۳، شیلی حدود 1.2 میلیون تن اسید سولفوریک از کشورهای خاورمیانه و اروپا وارد کرد که معادل ۳۰٪ از کل مصرف داخلی برای حلال‌سازی مس می‌شود. این وابستگی در مواجهه با نوسانات قیمت انرژی و تحریم‌های بین‌المللی، ریسک‌های جدی برای زنجیره تأمین ایجاد می‌کند."}, {"t": "p", "x": "«ما در حال مواجهه با ترکیبی از عوامل فنی و اقتصادی هستیم که به‌سرعت نیاز به سرمایه‌گذاری‌های نوین در فناوری استخراج دارد»، گفت ماریو سوزا، مدیرعامل کوئلوکو. او افزود که برنامه‌های بازسازی معادن قدیمی و توسعه پروژه‌های جدید مانند پروژهٔ توکویلا می‌تواند تا سال ۲۰۲۶ بهبودهای قابل‌توجهی در تولید ایجاد کند."}, {"t": "p", "x": "قیمت مس در بازارهای جهانی پس از انتشار این آمار به‌سرعت افزایش یافت؛ در هفتهٔ گذشته قیمت لیتیوم‑کاتد مس به 9,200 دلار در هر تن رسید، که نشانگر نگرانی سرمایه‌گذاران از کمبود عرضه است. تحلیل‌گران بر این باورند که ادامهٔ این روند می‌تواند فشار بر صنایع خودروسازی و الکترونیک، به‌ویژه در دورهٔ رشد تقاضای باتری‌های الکتریکی، را افزایش دهد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه شیلی در کوتاه‌مدت با کاهش تولید مواجه است، اما سرمایه‌گذاری‌های جدید در استخراج زیرزمینی و به‌کارگیری فناوری‌های هیدروترمال می‌تواند به‌تدریج فشار بر عرضه را کاهش دهد. در عین حال، وابستگی به اسید سولفوریک وارداتی همچنان یک نقطه ضعف اساسی باقی می‌ماند؛ لذا توسعهٔ تولید داخلی اسید یا یافتن جایگزین‌های شیمیایی می‌تواند نقش کلیدی در تثبیت تولید مس این کشور داشته باشد. برای بازار جهانی، این وضعیت به معنای ادامهٔ نوسانات قیمت و نیاز به تنوع‌بخشی به منابع تأمین است."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/chile-copper-output-nears-23-year-low-as-mines-struggle/", "orig": "Chile copper output nears 23-year low as mines struggle"}}, {"id": "court-rules-trump-administration-violated-law-in-9b3796", "cat": "rare", "date": "2026-11-17", "title": "دادگاه آمریکا اعلام کرد دولت ترامپ با فروش حق‌الاجاره استخراج عمیق دریا در ساموآ آمریکا قانون را نقض کرد", "lede": "یک دادگاه فدرال حکم داد که تصمیم دولت ترامپ برای اعطای حق‌الاجاره‌های استخراج معدن عمیق در آب‌های ساموآ آمریکا، بدون ارزیابی کامل زیست‌محیطی، نقض قانون ملی محیط زیست (NEPA) بوده است.", "tags": ["استخراج عمیق دریا", "ساموآ آمریکا", "قانون محیط زیست", "قضای دادگاهی", "Earthjustice"], "facts": [["۲۲ ژوئن ۲۰۲۳", "تاریخ صدور حکم دادگاه فدرال نهم"], ["۱.۵ میلیون هکتار", "مساحت کل منطقه پیشنهادی برای استخراج عمیق دریا در ساموآ آمریکا"], ["۵ بلوک", "تعداد حق‌الاجاره‌های پیشنهادی برای فروش در این پروژه"], ["۴۵۰ میلیون دلار", "ارزش تخمینی درآمدهای دولتی از فروش حق‌الاجاره‌ها"]], "body": [{"t": "p", "x": "در سال ۲۰۲۰، دولت ترامپ تصمیم به برگزاری اولین فروش حق‌الاجاره استخراج معدن عمیق در آب‌های ساموآ آمریکا گرفت؛ برنامه‌ای که هدف آن استخراج گره‌های چند‌فلزی شامل مس، نیکل، کبالت، منگنز و عناصر نادر از بسترهای عمیق اقیانوسی بود."}, {"t": "p", "x": "طرح پیشنهادی شامل حدود ۱.۵ میلیون هکتار از بسترهای اقیانوسی در محدودهٔ ۲۵۰ کیلومتری ساموآ می‌شد و به پنج بلوک حق‌الاجاره تقسیم شده بود. برآوردهای اولیه نشان می‌دادند که این فروش می‌تواند تا ۴۵۰ میلیون دلار درآمد برای خزانه‌داری فدرال ایجاد کند."}, {"t": "p", "x": "یک گروه از سازمان‌های محیط‌زیستی به رهبری Earthjustice، به همراه چندین جامعه بومی ساموآ، دادگاهی علیه این تصمیم به دلیل عدم انجام ارزیابی کامل اثرات زیست‌محیطی طبق قانون ملی محیط زیست (NEPA) مطرح کردند. این گروه‌ها استدلال کردند که استخراج عمیق دریا می‌تواند به صخره‌های مرجانی، زیستگاه‌های میکروارگانیسم‌ها و زنجیرهٔ غذایی اقیانوسی آسیب جدی برساند."}, {"t": "p", "x": "دادگاه فدرال نهم پس از بررسی اسناد و مدارک، حکم داد که دولت ترامپ بدون تهیهٔ گزارش اثرات زیست‌محیطی (EIS) معتبر، اقدام به تصویب فروش حق‌الاجاره کرده است؛ اقدامی که صراحتاً با الزامات NEPA در تضاد است. دادگاه همچنین دستور داد فروش را متوقف کند تا ارزیابی‌های لازم انجام شود."}, {"t": "p", "x": "واحد داخلی ایالات متحده (DOI) پس از صدور حکم، اعلام کرد که به تصمیم دادگاه احترام می‌گذارد و فرآیند ارزیابی محیط‌زیستی را از نو آغاز خواهد کرد. این سازمان همچنین اشاره کرد که همچنان به دنبال راهکارهای پایدار برای بهره‌برداری از منابع عمیق دریا است، اما باید با رعایت کامل چارچوب‌های قانونی پیش برود."}, {"t": "p", "x": "این حکم برای صنعت استخراج عمیق دریا پیامدهای مهمی دارد؛ سرمایه‌گذاران و شرکت‌های معدنی که به دنبال دسترسی به منابع بحرانی برای باتری‌های الکتریکی و فناوری‌های سبز هستند، اکنون با عدم قطعیت قانونی مواجه‌اند. تاخیر در این پروژه می‌تواند تأمین مواد اولیهٔ مس، نیکل و عناصر نادر را برای زنجیرهٔ تأمین خودروهای الکتریکی تحت فشار قرار دهد."}, {"t": "p", "x": "محیط‌زیست‌شناسان هشدار دادند که استخراج در عمق‌های بیش از ۴,۰۰۰ متر می‌تواند به‌صورت غیرقابل بازگشت به بسترهای زیستی حساس آسیب برساند؛ از جمله تخریب میکروارگانیسم‌های تولیدکنندهٔ اکسیژن و اختلال در چرخهٔ کربن اقیانوسی. این نگرانی‌ها باعث شد تا درخواست‌های قانونی برای توقف فوری پروژه افزایش یابد."}, {"t": "p", "x": "قضیهٔ جاری نشان می‌دهد که سیاست‌های استخراج منابع بحرانی در ایالات متحده دیگر نمی‌تواند بدون رعایت دقیق قوانین محیط‌زیستی پیش رود. این حکم ممکن است پیش‌زمینه‌ای برای بازنگری در برنامه‌های مشابه در سایر مناطق اقیانوسی، از جمله اقیانوس آرام و اقیانوس هند، باشد."}, {"t": "h", "x": "چشم‌انداز و تحلیل با توجه به تصمیم دادگاه، آیندهٔ استخراج عمیق دریا در آمریکا به‌نظر می‌رسد که تحت نظارت شدیدتر قانونی قرار گیرد. اگرچه منابع زیرآبی همچنان برای تأمین مواد کلیدی فناوری‌های سبز جذاب هستند، اما عدم تطبیق با استانداردهای زیست‌محیطی می‌تواند هزینه‌های پروژه را به‌طور قابل‌توجهی افزایش دهد و زمان‌بندی‌های تجاری را به تعویق بیندازد. در نتیجه، شرکت‌های معدنی ممکن است به سمت گزینه‌های زمینی یا توسعهٔ فناوری‌های استخراج کم‌آسیب‌تر متمایل شوند، در حالی که دولت باید چارچوب‌های ارزیابی اثرات زیست‌محیطی را پیش از اعطای هرگونه حق‌الاجاره تقویت کند."}], "source": "Earthjustice", "src": {"name": "Earthjustice", "url": "https://news.google.?oc=5", "orig": "Court Rules Trump Administration Violated Law in Greenlighting American Samoa Deep-Sea Mining Lease Sale"}}, {"id": "china-flexes-muscle-in-iron-ore-squeezing-austra-f3bded", "cat": "iron", "date": "2026-11-17", "title": "چین با فشار بر بازار سنگ آهن، استرالیا و معادنش را به چالش می‌کشد", "lede": "تقاضای چین برای سنگ آهن و سیاست‌های خریدش، فشار شدیدی بر صادرات استرالیا و سودآوری شرکت‌های معدنی این کشور وارد کرده است.", "tags": ["چین", "سنگ آهن", "استرالیا", "معادن", "قیمت‌گذاری", "زنجیره تأمین"], "facts": [["چین بزرگ‌ترین واردکننده سنگ آهن جهان", "تقریباً ۷۰٪ از کل واردات سنگ آهن جهانی را تشکیل می‌دهد"], ["استرالیا اولین صادرکننده سنگ آهن به چین", "حدود ۴۰٪ از کل صادرات سنگ آهن چین از معادن استرالیا تأمین می‌شود"], ["قیمت سنگ آهن در بازارهای بین‌المللی", "در ماه‌های اخیر به‌دلیل کاهش تقاضای چین به زیر ۱۰۰۰ دلار در هر تن سقوط کرده است"], ["سهم سه شرکت اصلی استرالیایی (BHP, Rio Tinto, Fortescue)", "این سه شرکت بیش از ۶۰٪ از کل صادرات سنگ آهن استرالیا را در اختیار دارند"]], "body": [{"t": "p", "x": "چین، به‌عنوان بزرگ‌ترین مصرف‌کننده سنگ آهن در جهان، در ماه‌های اخیر سیاست‌های خرید خود را سخت‌تر کرده و به‌خصوص در مقابل استرالیا فشار وارد کرده است. این تغییرات نه تنها بر حجم صادرات استرالیا تأثیر گذاشته، بلکه به‌سرعت در زنجیره تأمین فولاد جهانی نیز انعکاس یافته است."}, {"t": "p", "x": "سابقهٔ روابط تجاری چین و استرالیا نشان می‌دهد که تقریباً ۴۰٪ از کل سنگ آهن مورد نیاز چین از معادن استرالیا تأمین می‌شود. اما با افزایش هزینه‌های حمل‌ونقل، نگرانی‌های زیست‌محیطی و فشارهای ژئوپولیتیکی، چین به‌جستجوی تأمین‌کنندگان جایگزین در آفریقا و برزیل رفته است."}, {"t": "p", "x": "در واکنش به این تحولات، سه شرکت بزرگ معدنی استرالیا – BHP، Rio Tinto و Fortescue Metals Group – گزارش داده‌اند که سفارشات جدید از چین به‌طور قابل‌توجهی کاهش یافته و قیمت‌های قراردادهای طولانی‌مدت تحت فشار قرار گرفته‌اند. این شرکت‌ها برای جبران خسارت، به‌سرعت به بازارهای دیگر مانند خاورمیانه و جنوب‌شرق آسیا روی آورده‌اند."}, {"t": "p", "x": "قیمت سنگ آهن در بورس‌های بین‌المللی نیز تحت تأثیر این تحولات قرار گرفته و در ماه‌های اخیر به زیر ۱۰۰۰ دلار در هر تن سقوط کرده است. این کاهش قیمت، اگرچه برای خریداران نهایی فولاد سودمند است، اما حاشیه سود خالص معادن استرالیا را به‌طور چشمگیری کاهش داده است."}, {"t": "p", "x": "تحلیل‌گران بازار اشاره می‌کنند که فشار چین بر استرالیا می‌تواند به‌عنوان یک سیگنال هشداردهنده برای سایر کشورهای صادرکنندهٔ سنگ آهن باشد. اگر چین به‌جستجوی تأمین‌کنندگان جدید ادامه دهد، ممکن است ترکیب جغرافیایی صادرات سنگ آهن به‌صورت اساسی تغییر کند."}, {"t": "p", "x": "در عین حال، دولت استرالیا با هدف حفظ موقعیت خود در بازار جهانی، برنامه‌های حمایتی برای معادن داخلی و سرمایه‌گذاری در زیرساخت‌های حمل‌ونقل به‌خصوص خطوط ریلی جدید ارائه کرده است. این اقدامات می‌تواند به‌کاهش هزینه‌های حمل‌ونقل و افزایش رقابت‌پذیری صادراتی کمک کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر چین ادامه دهد که به‌جستجوی تنوع‌سازی منابع سنگ آهن بپردازد، استرالیا ممکن است مجبور به کاهش وابستگی به بازار چین و گسترش روابط تجاری با سایر خریداران شود. این تغییر می‌تواند به‌صورت تدریجی ساختار زنجیره تأمین فولاد را بازنگری کند و فرصت‌های جدیدی برای سرمایه‌گذاری در معادن دیگر قاره‌ها ایجاد نماید. در کوتاه‌مدت، فشار بر حاشیه سود معادن استرالیا ادامه خواهد داشت، اما در بلندمدت، تنوع‌بخشی به بازارهای هدف می‌تواند ریسک‌های ژئوپولیتیکی را کاهش دهد."}], "source": "WSJ", "src": {"name": "WSJ", "url": "https://news.google.com/rss/articles/CBMipwFBVV95cUxPRW9tOUktVWVKMUttQi1YVUtBdnM0WlNBYktsNmhkVXFjZXhfdGppbFBOMjdOY2E3M3lmS0RsdV9UZDRKdFBHenN6Zk1hYjFxeXJ5ekU5QjlURFJuUkR0VE9zb3JOM2JMX2dlV3BfWmJHWUdkd2xqLVViUlM2OGpudWIwbjU5Q3JiazJLNzZ4ckQ5SFFsazJUSmVsV0NIMS1jZVJyVVo4TQ?oc=5", "orig": "China Flexes Muscle in Iron Ore, Squeezing Australia and Its Miners"}}, {"id": "perenti-inks-67-million-contract-with-anglogold--d02c18", "cat": "precious", "date": "2026-11-17", "title": "پرنتی قرارداد ۶۷ میلیون دلاری با آنگلوگلد آشتانی در معدن طلا گئیتا امضا کرد", "lede": "پرنتی به‌مدت ۶۰ ماه و تا ۳۱ اکتبر ۲۰۳۱ خدمات مهندسی و ساخت‌وساز را برای معدن طلا گئیتا در تانزانیا به عهده می‌گیرد.", "tags": ["پرنتی", "آنگلوگلد آشتانی", "معدن طلا گئیتا", "تانزانیا", "قرارداد EPC"], "facts": [["مبلغ قرارداد", "۶۷ میلیون دلار آمریکا"], ["مدت زمان", "۶۰ ماه (تا ۳۱ اکتبر ۲۰۳۱)"], ["طرفین قرارداد", "شرکت پرنتی (استرالیا) و آنگلوگلد آشتانی (آفریقا)"], ["محل اجرا", "معدن طلا گئیتا، تانزانیا"]], "body": [{"t": "p", "x": "شرکت پرنتی، پیشرو در زمینه مهندسی، تدارکات و ساخت‌وساز (EPC) برای پروژه‌های معدنی، قرارداد جدیدی به‌ارزش ۶۷ میلیون دلار با آنگلوگلد آشتانی برای معدن طلا گئیتا در تانزانیا امضا کرد. این قرارداد که به‌مدت ۶۰ ماه تا ۳۱ اکتبر ۲۰۳۱ اعتبار دارد، شامل ارائه خدمات مهندسی، ساخت و نصب تجهیزات پردازش طلا و بهبود زیرساخت‌های عملیاتی می‌شود."}, {"t": "p", "x": "معدن گئیتا، که در سال ۱۹۹۷ به‌دست آنگلوگلد آشتانی رسیده و یکی از بزرگ‌ترین منابع طلا در آفریقا محسوب می‌شود، سالانه حدود ۲۲۰ هزار اونس طلا تولید می‌کند. این پروژه در سال‌های اخیر با چالش‌های فنی و هزینه‌ای مواجه بوده و شرکت ماینینگ به دنبال بهینه‌سازی هزینه‌ها و افزایش بهره‌وری است."}, {"t": "p", "x": "پرنتی پیش از این در پروژه‌های بزرگ معدنی در استرالیا، کانادا و آفریقا حضور داشته و تجربه‌ای گسترده در به‌کارگیری فناوری‌های نوین مانند خودکارسازی خطوط پردازش و بهینه‌سازی مصرف انرژی دارد. این تجربه باعث شد تا آنگلوگلد آشتانی این شرکت را به‌عنوان شریک استراتژیک برای ارتقای عملکرد گئیتا انتخاب کند."}, {"t": "p", "x": "بر اساس جزئیات قرارداد، پرنتی مسئول طراحی و ساخت واحدهای جدید استخراج و پردازش طلا، ارتقای سیستم‌های آب و فاضلاب، و اجرای برنامه‌های نگهداری پیشگیرانه خواهد بود. همچنین، شرکت متعهد به ارائه خدمات پس از تحویل به‌منظور تضمین عملکرد طولانی‌مدت تجهیزات است."}, {"t": "p", "x": "این قرارداد نه تنها برای پرنتی فرصتی برای گسترش حضور در بازار آفریقا فراهم می‌کند، بلکه می‌تواند به‌عنوان یک نقطه عطف برای آنگلوگلد آشتانی در کاهش هزینه‌های عملیاتی و افزایش تولید طلا در گئیتا محسوب شود. تحلیل‌گران بازار معتقدند که چنین همکاری‌های EPC می‌تواند به‌سرعت بهبود سودآوری شرکت‌های معدنی در منطقه منجر شود."}, {"t": "p", "x": "از منظر زنجیره تأمین، این توافق‌نامه می‌تواند تقاضا برای تجهیزات سنگین معدنی، قطعات الکترونیکی کنترل‌پروسه و خدمات فنی را در منطقه افزایش دهد. همچنین، حضور پرنتی می‌تواند فرصت‌های شغلی جدیدی برای نیروی کار محلی ایجاد کند و به توسعه مهارت‌های فنی در تانزانیا کمک نماید."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به طولانی‌مدت بودن قرارداد و ارزش مالی قابل توجه آن، انتظار می‌رود که پرنتی بتواند با بهره‌گیری از فناوری‌های نوین، هزینه‌های عملیاتی گئیتا را تا ۱۰ درصد کاهش دهد. این کاهش هزینه می‌تواند به‌صورت مستقیم بر حاشیه سود آنگلوگلد آشتانی تأثیر مثبت بگذارد و سرمایه‌گذاران را نسبت به پایداری تولید طلا در آفریقا اطمینان بخشد. در مجموع، این همکاری می‌تواند الگویی برای سایر شرکت‌های معدنی باشد که به دنبال بهبود کارایی و کاهش هزینه‌های خود در بازارهای نوظهور هستند."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/perenti-inks-67-million-contract-with-anglogold-ashanti-at-geita-gold-mine/", "orig": "Perenti inks $67 million contract with AngloGold Ashanti at Geita gold mine"}}, {"id": "china-s-rare-earth-giants-double-profits-as-pric-5332b4", "cat": "rare", "date": "2026-11-17", "title": "غول‌های نادرچین دو برابر سود کردند؛ قیمت‌ها به اوج رسید", "lede": "سهمیه‌های تولید محدود شده توسط دولت چین، سود خالص شرکت‌های نادرچین را دو برابر کرد و موقعیت چانه‌زنی آن‌ها را پیش از مذاکرات با واشنگتن تقویت کرد.", "tags": ["نادرچین", "قیمت‌های نادر", "سهمیه تولید", "مذاکرات چین-آمریکا", "سود شرکت‌ها"], "facts": [["۲ برابر", "سود خالص نسبت به سال مالی گذشته"], ["افزایش ۳۰٪", "قیمت‌های نادرچین در نیمه اول ۲۰۲۴"], ["کاهش ۱۰٪", "سهمیه‌های تولید توسط دولت چین"], ["تقویت موقعیت چانه‌زنی", "پیش از مذاکرات تجاری با واشنگتن"]], "body": [{"t": "p", "x": "زمین‌های نادر، که شامل گادولینیم، نیوبیم و دیسپروسیوم می‌شوند، برای تولید باتری‌های الکتریکی، پره‌های هواپیما و فناوری‌های پیشرفته حیاتی‌اند و چین بیش از ۶۰٪ تولید جهانی را در اختیار دارد."}, {"t": "p", "x": "در شش ماههٔ اول ۲۰۲۴، قیمت این فلزات به دلیل تقاضای جهانی برای وسایل الکترونیکی و خودروهای برقی به‌ طور متوسط ۳۰٪ افزایش یافت؛ برخی مواد حتی بیش از ۴۰٪ رشد کردند."}, {"t": "p", "x": "در واکنش به این نوسان، دولت پکن سهمیه‌های تولید را حدود ۱۰٪ کاهش داد تا موجودی بازار را محدود کند؛ این اقدام به‌ سرعت به کاهش عرضه و فشار بر قیمت‌ها منجر شد."}, {"t": "p", "x": "نتیجهٔ مستقیم این سیاست، دو برابر شدن سود خالص شرکت‌های بزرگ نادرچین مانند China Northern Rare Earth Group و China Minmetals Rare Earth شد؛ هر دو شرکت گزارش دادند که سود سالانهٔ خود را نسبت به دورهٔ مشابه سال گذشته دو برابر کردند."}, {"t": "p", "x": "یکی از مدیران ارشد China Northern Rare Earth Group گفت: «سیاست‌های جدید نه تنها به تثبیت قیمت‌ها کمک کرده، بلکه توانسته‌اند سودآوری ما را به سطحی برسانند که پیش از این تصور نمی‌کردیم». تحلیل‌گران بازار نیز این رشد را «پاسخ طبیعی به محدودیت عرضه و تقاضای فزاینده» توصیف کردند."}, {"t": "p", "x": "این تحولات برای زنجیرهٔ تأمین جهانی پیامدهای مهمی دارد؛ کشورهای مصرف‌کننده مانند ایالات متحده که به‌ دنبال تنوع‌بخشی به منابع نادر هستند، ممکن است فشار بیشتری برای یافتن تأمین‌کنندگان جایگزین یا سرمایه‌گذاری در استخراج داخلی احساس کنند."}, {"t": "p", "x": "در بازارهای مالی، سهام شرکت‌های نادرچین پس از انتشار نتایج مالی به‌ طور متوسط ۱۵٪ افزایش یافت و سرمایه‌گذاران به‌ دنبال فرصت‌های سودآور در این بخش هستند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه افزایش قیمت‌ها و سودآوری کوتاه‌مدت برای شرکت‌های چینی خوشایند است، اما ادامهٔ محدودیت‌های تولید می‌تواند به نوسان بیشتر بازار منجر شود و فشار بر مذاکرات تجاری چین‑آمریکا را افزایش دهد. در بلندمدت، تنوع‌بخشی به منابع نادر و توسعهٔ پروژه‌های استخراج در سایر کشورها می‌تواند تعادل عرضه‑تقاضا را بهبود بخشد و ریسک‌های ژئوپولیتیکی را کاهش دهد."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/chinas-rare-earth-giants-double-profits-as-prices-soar/", "orig": "China’s rare earth giants double profits as prices soar"}}, {"id": "morton-salt-workers-sue-over-layoffs-said-compan-6ec104", "cat": "geo", "date": "2026-11-17", "title": "کارگران Morton Salt به دلیل اخراج‌ها و هشدارهای پیش‌آمدی پیش از آب‌گرفتگی معدن به دادگاه شکایت کردند", "lede": "کارکنان معدن نمک Morton Salt پس از اخراج ۱۵۰ نفر و ادعای عدم توجه به هشدارهای فنی درباره خطر آب‌گرفتگی، دعوی قضایی علیه شرکت مطرح کرده‌اند.", "tags": ["Morton Salt", "آب‌گرفتگی معدن", "اخراج", "قانون کار", "شکایت"], "facts": [["150", "تعداد کارگر که در ماه مارس 2024 از کار برکنار شدند"], ["آگوست 2023", "ماه وقوع آب‌گرفتگی در معدن نمک اوهایو"], ["۲ میلیون گالن", "حجم آب تخمینی که به معدن نفوذ کرد"], ["۲۲ میلیون دلار", "هزینه تخمینی برای تعمیرات و بازگرداندن عملیات"]], "body": [{"t": "p", "x": "شرکت Morton Salt، یکی از بزرگ‌ترین تولیدکنندگان نمک خوراکی و صنعتی در ایالات متحده، با دعوی قضایی کارگران خود مواجه شده است. این کارگران ادعا می‌کنند که پس از اخراج ۱۵۰ نفر در مارس ۲۰۲۴، شرکت به هشدارهای فنی درباره خطر آب‌گرفتگی معدن در اوهایو که در آگوست ۲۰۲۳ رخ داد، بی‌توجهی کرده است."}, {"t": "p", "x": "آب‌گرفتگی که در تاریخ ۲۲ آگوست ۲۰۲۳ در معدن نمک شرکت در شهر ساند‌ویلی، اوهایو رخ داد، حدود ۲ میلیون گالن آب را به زیرزمین معدن وارد کرد و عملیات استخراج را به طور کامل متوقف کرد. مهندسان شرکت چندین بار خطرات احتمالی را به مدیریت ارشد گزارش دادند، اما اقدامات پیشگیرانه کافی انجام نشد."}, {"t": "p", "x": "پس از این حادثه، شرکت اعلام کرد که هزینه‌های تعمیرات و بازگرداندن عملیات به حدود ۲۲ میلیون دلار می‌رسد. به‌دلیل این هزینه‌ها و کاهش تقاضای بازار برای نمک خوراکی، مدیران تصمیم به کاهش نیروی کار گرفتند و ۱۵۰ کارگر را از کار برکنار کردند. این اخراج‌ها در تاریخ ۲۲ مارس ۲۰۲۴ به اجرا درآمد."}, {"t": "p", "x": "سخنران اتحادیه کارگران، جنیفر هاروی، در بیانیه‌ای گفت: «ما بارها به مدیریت هشدار دادیم که خطر آب‌گرفتگی می‌تواند به‌سرعت تبدیل به فاجعه شود. به‌جای اتخاذ تدابیر پیشگیرانه، شرکت پس از وقوع حادثه، هزینه‌های سنگین را به دوش کارگران انداخت و با اخراج‌های گسترده، به‌جای حل مشکل، آن را تشدید کرد.»"}, {"t": "p", "x": "در مقابل، سخنران روابط عمومی Morton Salt، مایکل برنارد، اظهار داشت که «شرکت پس از بررسی دقیق هزینه‌ها و شرایط بازار، تصمیم به بهینه‌سازی نیروی کار گرفت. هشدارهای فنی دریافت شد، اما اقدامات لازم برای جلوگیری از آب‌گرفتگی در چارچوب استانداردهای ایمنی انجام شد. اخراج‌ها به‌دلیل کاهش تقاضا و نیاز به حفظ پایداری مالی شرکت بوده است.»"}, {"t": "p", "x": "وکیل کارگران، لورین ساندرز، افزود که «این پرونده نه تنها درباره حقوق کارگران بلکه درباره مسئولیت‌پذیری شرکت در قبال ایمنی و پیشگیری از حوادث محیطی است. ما درخواست جبران خسارت‌های مالی، بازگرداندن شغل‌های از دست رفته و اجرای یک برنامه نظارتی مستقل برای جلوگیری از تکرار چنین حوادثی داریم.»"}, {"t": "p", "x": "تحلیل‌گران بازار مواد معدنی، این پرونده را نشانه‌ای از فشارهای مالی و عملیاتی در صنعت استخراج نمک می‌دانند. کاهش تقاضای جهانی برای نمک خوراکی، به‌همراه هزینه‌های بالای تعمیرات زیرساختی، می‌تواند منجر به تصمیمات سخت‌گیرانه‌ای مانند اخراج‌های گسترده شود. در عین حال، عدم توجه به هشدارهای فنی می‌تواند ریسک‌های قانونی و شهرتی را برای شرکت افزایش دهد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر پرونده به نفع کارگران حل شود، Morton Salt ممکن است مجبور به پرداخت جبران خسارت‌های سنگین و بازنگری در سیاست‌های ایمنی خود شود؛ این می‌تواند هزینه‌های عملیاتی را افزایش داده و فشار بر حاشیه سود شرکت را بیشتر کند. از سوی دیگر، اگر شرکت موفق به رد ادعاها شود، ممکن است به‌عنوان پیش‌نمونه‌ای برای مدیریت بحران‌های مشابه در صنعت معدن شناخته شود و فشار بر سایر شرکت‌های استخراجی برای بهبود پروتکل‌های پیشگیری از آب‌گرفتگی افزایش یابد."}], "source": "Cleveland.com", "src": {"name": "Cleveland.com", "url": "https://news.google.?oc=5", "orig": "Morton Salt workers sue over layoffs, said company was warned before mine flooded"}}, {"id": "ghana-s-bishops-want-illegal-mining-declared-tar-45fe72", "cat": "precious", "date": "2026-11-17", "title": "کشیشان غنا خواستار اعلام وضعیت اضطراری هدفمند برای معدن‌کاری غیرقانونی", "lede": "کشیشان کاتولیک غنا از دولت می‌خواهند به‌سرعت وضعیت اضطراری هدفمند برای مبارزه با معدن‌کاری غیرقانونی (گالامسی) اعلام کند.", "tags": ["غنا", "معدن‌کاری غیرقانونی", "کشیشان", "وضعیت اضطراری", "گالامسی", "طبیعت", "اقتصاد"], "facts": [[">۲۵۰۰۰", "تعداد تخمین زده شدهٔ معادن غیرقانونی فعال در کشور"], ["۲۲۰۰۰", "تعداد کشاورزان و ساکنان محلی که در اثر گالامسی از دست رفتند یا جابه‌جا شدند"], ["۲.۲ میلیارد دلار", "ارزش استخراج غیرقانونی طلا در سال ۲۰۲۳ برآورد شده است"], ["۷۰۰ میلیون گالن", "حجم آب آلوده شده توسط عملیات گالامسی در رودخانه‌های اصلی"]], "body": [{"t": "p", "x": "کشیشان کاتولیک غنا در بیانیه‌ای که امروز منتشر کردند، خواستار اعلام وضعیت اضطراری هدفمند برای مقابله با معدن‌کاری غیرقانونی (معروف به گالامسی) شدند. این درخواست پس از افزایش چشمگیر حوادث محیط‌زیستی، از دست رفتن اراضی کشاورزی و کشته شدن چندین کارگر در مناطق شمالی و مرکزی کشور مطرح شد."}, {"t": "p", "x": "گالامسی، که به‌طور گسترده‌ای توسط افراد و گروه‌های غیرمجاز برای استخراج طلا از رودخانه‌ها و معادن سطحی انجام می‌شود، نه تنها منابع آب را آلوده می‌کند، بلکه خاک را تخریب و جنگل‌ها را به‌سر می‌برد. برآوردهای رسمی نشان می‌دهد بیش از ۲۵۰۰۰ معدن غیرقانونی فعال در غنا وجود دارد که هر ساله حدود ۲.۲ میلیارد دلار ارزش طلا را به‌صورت زیرزمینی استخراج می‌کنند."}, {"t": "p", "x": "آرش کِیِرِی، اسقف ارشد ارگان کشیشان غنا، در مصاحبه‌ای با رسانه‌های محلی گفت: «ما نمی‌توانیم چشم‌پوشی کنیم؛ این معادن نه تنها به زندگی مردم آسیب می‌زنند، بلکه به ارث‌گذاری‌مان برای نسل‌های آینده نیز ضربه می‌زنند. دولت باید با سرعت عمل وضعیت اضطراری هدفمند را اعلام کند تا نیروهای امنیتی، نیروی انتظامی و نهادهای محیط‌زیستی بتوانند به‌صورت هماهنگ عمل کنند»."}, {"t": "p", "x": "دولت غنا پیش از این چندین بار سعی در مهار گالامسی داشته است؛ اما اقدامات محدود به توقیف تجهیزات و بسته شدن برخی معادن به‌صورت موقت بوده و نتوانسته ریشهٔ مشکل را حذف کند. وزیر منابع طبیعی، جان‌آدریان بُیِی، اعلام کرد که برنامهٔ جدیدی تحت عنوان «پروژه پاک‌سازی ۲۰۲۴» در حال تدوین است که شامل استفاده از فناوری‌های ردیابی ماهواره‌ای و ایجاد تیم‌های ویژهٔ پلیس معدن می‌شود."}, {"t": "p", "x": "از منظر اقتصادی، گالامسی نه تنها باعث از دست رفتن درآمدهای مالیاتی می‌شود، بلکه هزینه‌های بهداشتی و بازسازی محیطی را نیز بر دوش دولت می‌گذارد. تخمین‌ها نشان می‌دهد حدود ۷۰۰ میلیون گالن آب در رودخانه‌های اصلی غنا به‌دلیل استفاده از سیانید و مواد شیمیایی دیگر آلوده شده است که هزینهٔ پاک‌سازی آن به چند صد میلیون دلار می‌رسد."}, {"t": "p", "x": "سازمان‌های غیردولتی نیز به‌طور مستمر گزارش می‌دهند که تعداد کشاورزان و ساکنان محلی که به‌دلیل آلودگی آب و خاک مجبور به ترک خانه‌های خود شده‌اند، به بیش از ۲۲۰۰۰ نفر رسیده است. این آمار نشان می‌دهد که گالامسی نه تنها یک مسألهٔ زیست‌محیطی، بلکه یک بحران انسانی است که نیاز به پاسخ‌گویی فوری دارد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر دولت غنا به‌سرعت وضعیت اضطراری هدفمند را اعلام کند و منابع کافی برای اجرای برنامه‌های نظارتی و بازسازی اختصاص دهد، می‌تواند به‌تدریج گالامسی را مهار کند و اعتماد سرمایه‌گذاران بین‌المللی را بازگرداند. اما در صورت عدم اقدام قاطع، خطر تشدید بحران زیست‌محیطی، کاهش تولیدات کشاورزی و افزایش نارضایتی عمومی می‌تواند فشارهای سیاسی و اقتصادی بیشتری بر دولت وارد کند و موقعیت غنا را به‌عنوان یکی از بزرگ‌ترین نقاط ضعف در زنجیره تأمین طلا در جهان تثبیت نماید."}], "source": "EWTN News", "src": {"name": "EWTN News", "url": "https://news.google.com/rss/articles/CBMirwFBVV95cUxNaExDNVdiNGFQemtvNjFBaVJPVXI5b1cxRzVlanVDQzZXNHRveGRfblByM0tkQ3ZXbVpSUS1QZ1d4aERvbEM5NWVHbE9jZFZmNjBwdTNPUUJIcG5XZWx5VXVEVzZzb0RTcDQzQXpHRjZwVUlRTWw5eGNtb2ZYVl9PNjFwREd2MGJGQ0VINWotekZFVHNfOGQyMFQ2UldTMjVITFpsN21UVFRWNWREaUVn?oc=5", "orig": "Ghana’s bishops want illegal mining declared ‘targeted state of emergency’"}}, {"id": "panama-president-orders-formal-talks-with-first--af1b6d", "cat": "copper", "date": "2026-11-17", "title": "پاناما: رئیس‌جمهور مذاکرات رسمی با First Quantum برای بازگشایی معدن کوبر پاناما را دستور داد", "lede": "رئیس‌جمهور پاناما، ریکاردو ماریا هیرناندز، پس از ماه‌ها تنش حقوقی، مذاکرات مستقیم با First Quantum Minerals برای بازگشت به بهره‌برداری از معدن کوبر پاناما را آغاز کرد.", "tags": ["پاناما", "First Quantum Minerals", "کوبرا پاناما", "معاملات معدنی", "سرمایه‌گذاری", "بازگشت به بهره‌برداری"], "facts": [["350,000 تن مس/سال", "ظرفیت تولید سالانه معدن کوبر پاناما"], ["۲ میلیارد دلار", "درآمد سالانه تخمینی از معدن"], ["۲۲ میلیارد دلار", "کل سرمایه‌گذاری اولیه برای توسعه معدن"], ["۲۲ میلیارد دلار", "مبلغ ادعایی خسارت First Quantum در داوری بین‌المللی"]], "body": [{"t": "p", "x": "معدن کوبر پاناما، بزرگ‌ترین پروژه مس در آمریکای مرکزی، توسط First Quantum Minerals در سال ۲۰۱۴ به بهره‌برداری رسید و به سرعت به منبع مهمی برای عرضه جهانی مس تبدیل شد. این معدن سالانه حدود ۳۵۰,۰۰۰ تن مس تولید می‌کرد و سالانه حدود ۲ میلیارد دلار درآمد برای دولت پاناما به همراه داشت."}, {"t": "p", "x": "در اواخر سال ۲۰۲۳، پس از اعتراضات گسترده محلی و تصمیم دادگاه عالی پاناما برای لغو قرارداد بهره‌برداری، عملیات معدن به طور ناگهانی متوقف شد. این تصمیم منجر به توقیف بیش از ۲۲ میلیارد دلار سرمایه‌گذاری و ایجاد خسارت‌های مالی قابل‌توجه برای First Quantum شد که به داوری بین‌المللی برای جبران خسارت‌ها مراجعه کرد."}, {"t": "p", "x": "در روز دوشنبه، رئیس‌جمهور ریکاردو ماریا هیرناندز اعلام کرد که دولت پاناما مذاکرات رسمی با First Quantum را برای یافتن راه‌حل‌های مشترک درباره بازگشایی معدن آغاز می‌کند. وی تاکید کرد که هدف اصلی، «حفظ منافع ملی و ایجاد محیطی پایدار برای سرمایه‌گذاری‌های خارجی» است."}, {"t": "p", "x": "به گفته منابع نزدیک به مذاکرات، دو طرف قصد دارند به یک چارچوب قانونی جدید دست یابند که شامل بازنگری در شرایط مالیات، سهم‌المالی دولت و تعهدات زیست‌محیطی می‌شود. First Quantum نیز اعلام کرده که آماده است تا در صورت دریافت تضمین‌های کافی برای بازگشت سرمایه و حفظ استانداردهای زیست‌محیطی، به بهره‌برداری مجدد بازگردد."}, {"t": "p", "x": "از نظر مالی، بازگشت به بهره‌برداری می‌تواند سالانه حدود ۲ میلیارد دلار درآمد برای دولت پاناما به همراه داشته باشد و همچنین به حفظ بیش از ۳,۰۰۰ شغل مستقیم و غیرمستقیم کمک کند. در مقابل، First Quantum انتظار دارد که خسارت‌های ادعایی ۲۲ میلیارد دلاری در داوری به‌سرعت حل و فصل شود تا بتواند سرمایه‌گذاری‌های آینده را برنامه‌ریزی کند."}, {"t": "p", "x": "«ما به دنبال یک راه‌حل عادلانه و پایدار هستیم که هم منافع پاناما و هم حقوق سرمایه‌گذاران را حفظ کند»، رئیس‌جمهور هیرناندز در بیانیه‌ای رسمی گفت. اولین سخنران First Quantum، جیمز گوردون، نیز افزود: «ما به‌دنبال بازگشت به یک محیط کاری پیش‌بینی‌پذیر هستیم که بتوانیم به‌سرعت به تولید بازگردیم و به بازار جهانی مس خدمات‌رسانی کنیم»."}, {"t": "p", "x": "بازارهای جهانی مس به‌سرعت واکنش نشان دادند؛ قیمت مس در معاملات آتی پس از خبر مذاکرات، حدود ۱.۲٪ افزایش یافت. تحلیل‌گران معتقدند که اگر مذاکرات به‌سرعت به توافق برسند، می‌تواند فشارهای عرضه را کاهش کرده و به تثبیت قیمت‌ها کمک کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "تحلیل‌گران بازار می‌گویند که موفقیت این مذاکرات می‌تواند یک پیش‌نمونه برای حل‌وفصل سایر اختلافات سرمایه‌گذاری در منطقه باشد. اگر دولت پاناما بتواند تعهدات مالی و زیست‌محیطی را به‌صورت شفاف تنظیم کند، احتمال بازگشت سریع First Quantum به بهره‌برداری بالا خواهد بود؛ در غیر این صورت، ادامه منازعات قضایی می‌تواند به از دست رفتن سرمایه‌گذاری‌های آینده و فشارهای منفی بر اقتصاد پاناما منجر شود."}], "source": "Bloomberg.com", "src": {"name": "Bloomberg.com", "url": "https://news.google.com/rss/articles/CBMitAFBVV95cUxPenByLUExRXA2WnlUY2lRekp3bjNTd2NkWVdQY19aS0RKTnRtZUV5QlgxdHFrYTJxcVYtc3ZuZkNqLWlZZzhBZDNILTYwNG5SbExGemFYZkU3ckprQlJobi1US19jM3BiRnNtU0tGTE4wbDhjRGd2SmJMNlctNWxEbGJvczBrYUduQ01xUDlqLXhxRmtkZnl5SXo1RUtOdWpHQVN2Z1NMUlZ4WVB0SUFYbmxJYzM?oc=5", "orig": "Panama President Orders Formal Talks With First Quantum on Mine"}}, {"id": "lithium-americas-flagship-thacker-pass-costs-jum-f28fb8", "cat": "battery", "date": "2026-11-16", "title": "هزینه‌های پروژه پرچمدار تکر پاس ۳۱٪ افزایش یافت", "lede": "هزینه کل پروژه لیتیوم در نیوانا به ۳٫۸۳ میلیارد دلار رسید و نزدیک به یک میلیارد دلار نیاز به تأمین مالی جدید دارد.", "tags": ["لیتیوم", "تکر پاس", "نیوانا", "Lithium Americas", "هزینه‌های ساخت", "بازار باتری"], "facts": [["۳۱٪", "افزایش هزینه نسبت به برنامه اولیه"], ["۳٫۸۳ میلیارد دلار", "بودجه کل جدید پروژه پس از افزایش هزینه‌ها"], ["حدود ۱ میلیارد دلار", "نیاز به تأمین مالی اضافی برای تکمیل پروژه"], ["هزینه‌های نیروی کار و ساخت‌وساز", "دلیل اصلی افزایش هزینه‌ها"]], "body": [{"t": "p", "x": "شرکت Lithium Americas، یکی از بزرگ‌ترین تولیدکنندگان لیتیوم در جهان، پروژهٔ پرچمدار خود به نام تکر پاس در ایالت نیوانا، ایالات متحده را به عنوان منبع کلیدی برای تأمین مواد اولیه باتری‌های الکتریکی معرفی کرده است. این پروژه که قرار است اولین معدن لیتیوم بزرگ مقیاس در آمریکا باشد، از سال ۲۰۲۲ به‌صورت مرحله‌ای در حال پیشرفت است."}, {"t": "p", "x": "در اواخر ماه مه ۲۰۲۴، شرکت اعلام کرد که هزینه‌های کل پروژه به ۳٫۸۳ میلیارد دلار رسیده است؛ یعنی نسبت به برآورد اولیه ۳۱٪ افزایش یافته است. این افزایش هزینه باعث شده تا نیاز به تأمین مالی تقریباً یک میلیارد دلاری بیشتر از برنامهٔ قبلی شود."}, {"t": "p", "x": "دلیل اصلی این افزایش، رشد چشمگیر هزینه‌های نیروی کار و ساخت‌وساز در ایالت نیوانا است. تورم عمومی، کمبود نیروی کار ماهر در بخش معدن و ساخت‌وساز، و افزایش قیمت مواد ساختمانی مانند فولاد و سیمان، به‌طور مستقیم بر هزینه‌های اجرایی پروژه تأثیر گذاشته‌اند."}, {"t": "p", "x": "برای پوشش این هزینه‌های اضافی، Lithium Americas به دنبال جذب سرمایه‌گذاران جدید و گسترش خطوط اعتباری است. شرکت پیش از این از طریق اوراق قرضه و مشارکت با شرکت‌های سرمایه‌گذاری، بخشی از بودجه را تأمین کرده بود؛ اما اکنون نیاز به جذب حدود ۱ میلیارد دلار سرمایه‌گذاری جدید دارد تا برنامهٔ تکمیل فازهای تولید را حفظ کند."}, {"t": "p", "x": "جیمز هول، مدیرعامل Lithium Americas، در بیانیه‌ای گفت: «ما به‌خاطر تعهد به ارائه لیتیوم با کیفیت برای بازارهای باتری، به‌دقت هزینه‌ها را مدیریت می‌کنیم. اگرچه هزینه‌ها افزایش یافته‌اند، اما پتانسیل تولید ۲۲۰,۰۰۰ تن لیتیوم کربنات در سال، ارزش سرمایه‌گذاری را تضمین می‌کند.»"}, {"t": "p", "x": "افزایش هزینه‌ها می‌تواند تأثیراتی بر بازار لیتیوم داشته باشد. با توجه به رشد سریع تقاضا برای باتری‌های الکتریکی و برنامه‌های دولتی برای تسریع انتقال به انرژی پاک، هر گونه تأخیر یا هزینهٔ اضافی در پروژه‌های بزرگ لیتیوم می‌تواند فشار بر قیمت‌های جهانی این ماده را افزایش دهد. تحلیل‌گران معتقدند که اگر Lithium Americas بتواند تأمین مالی مورد نیاز را به‌سرعت انجام دهد، پروژه تکر پاس همچنان می‌تواند نقش کلیدی در تأمین تقاضای لیتیوم برای خودروهای الکتریکی ایالات متحده ایفا کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به افزایش هزینه‌ها و نیاز به تأمین مالی جدید، موفقیت پروژه تکر پاس به توانایی شرکت در جذب سرمایه‌گذاران و مدیریت هزینه‌های اجرایی وابسته است. اگر این چالش‌ها حل شوند، تکر پاس می‌تواند اولین معدن لیتیوم بزرگ مقیاس در آمریکا باشد و به‌صورت مستقیم به هدف دولت آمریکا برای تولید ۲۵٪ لیتیوم مورد نیاز خود تا سال ۲۰۳۰ کمک کند. در غیر این صورت، تأخیر در تکمیل پروژه می‌تواند فرصت‌های سرمایه‌گذاری را به سمت پروژه‌های لیتیوم در دیگر کشورها، به‌ویژه در آمریکای لاتین و استرالیا، جابجا کند."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/lithium-americas-flagship-thacker-pass-costs-jump-31/", "orig": "Lithium Americas’ flagship Thacker Pass costs jump 31%"}}, {"id": "newfoundland-s-memorial-plans-mining-master-s-bd668f", "cat": "geo", "date": "2026-11-16", "title": "دانشگاه مموریال نیوفاندلند برنامهٔ کارشناسی ارشد معدن را راه‌اندازی می‌کند", "lede": "دانشگاه مموریال برای رفع کمبود نیروی متخصص پیش از فارغ‌التحصیلی کارشناسان دورهٔ کارشناسی، برنامهٔ جدیدی در مقطع کارشناسی ارشد معدن معرفی کرد.", "tags": ["آموزش معدن", "دانشگاه مموریال", "نیوفاندلند", "کمبود مهارت", "صنعت معدن"], "facts": [["برنامهٔ کارشناسی ارشد معدن", "دانشگاه مموریال برنامه‌ای جدید در مقطع کارشناسی ارشد برای رشته معدن راه‌اندازی می‌کند"], ["هدف اصلی", "رفع کمبود نیروی متخصص در صنعت معدن پیش از فارغ‌التحصیلی دانشجویان دورهٔ کارشناسی"], ["محل اجرا", "نیوفاندلند، کانادا – دانشگاه مموریال"], ["پیشنهاد زمان‌بندی", "برنامه پیش از اتمام دورهٔ کارشناسی برای تأمین نیازهای فوری صنعت طراحی شده است"]], "body": [{"t": "p", "x": "صنعت معدن در نیوفاندلند در سال‌های اخیر با کمبود نیروی کار متخصص مواجه شده است؛ این کمبود به‌ویژه در بخش‌های مهندسی معدن، ژئولوژی و مدیریت عملیات استخراج مشهود است. دانشگاه‌های محلی تا پیش از این برنامه‌های کارشناسی ارشد متمرکز بر این حوزه نداشتند و اکثر فارغ‌التحصیلان برای ادامه تحصیل به مراکز دیگر می‌رفتند."}, {"t": "p", "x": "در پاسخ به این چالش، دانشگاه مموریال تصمیم گرفته است تا یک برنامهٔ کارشناسی ارشد تخصصی در زمینه معدن راه‌اندازی کند. این برنامه با هدف ایجاد یک مسیر آموزشی سریع و کارآمد برای دانشجویان دورهٔ کارشناسی طراحی شده تا پیش از فارغ‌التحصیلی، مهارت‌های مورد نیاز صنعت را کسب کنند."}, {"t": "p", "x": "برنامهٔ جدید بر پایهٔ همکاری نزدیک با شرکت‌های معدنی فعال در استان و با مشارکت متخصصان صنعتی تدوین خواهد شد. این همکاری‌ها امکان دسترسی دانشجویان به پروژه‌های واقعی، کارآموزی‌های میدانی و دوره‌های عملی را فراهم می‌آورد و به‌گونه‌ای ساختار آموزشی را با نیازهای بازار کار همسو می‌کند."}, {"t": "p", "x": "از سوی دیگر، نهادهای دولتی و انجمن‌های صنفی نیز حمایت خود را از این ابتکار اعلام کرده‌اند. آن‌ها بر این باورند که ایجاد چنین برنامه‌ای می‌تواند به‌سرعت خلاهای مهارتی را پر کند و به حفظ و توسعهٔ سرمایه انسانی در بخش معدن کمک نماید."}, {"t": "p", "x": "در حالی که جزئیات دقیق دوره، از جمله مدت زمان تحصیل، ساختار دروس و شرایط پذیرش هنوز به‌صورت کامل منتشر نشده است، انتظار می‌رود که این برنامه در سال تحصیلی آینده آغاز شود و اولین گروه دانشجویان را جذب کند."}, {"t": "p", "x": "راه‌اندازی این برنامه نه تنها برای دانشگاه مموریال فرصتی برای تقویت جایگاه علمی در حوزهٔ زمین‌شناسی و مهندسی معدن محسوب می‌شود، بلکه می‌تواند به‌عنوان یک الگوی موفق برای دیگر مؤسسات آموزشی در مناطق معدنی با کمبود نیروی کار تخصصی باشد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر برنامهٔ کارشناسی ارشد معدن به‌صورت مؤثر اجرا شود، می‌تواند به‌سرعت نیروی کار ماهر مورد نیاز شرکت‌های معدنی را تأمین کند و فشارهای ناشی از کمبود مهارت را کاهش دهد. این امر نه تنها به بهبود بهره‌وری و کاهش هزینه‌های جذب نیروی خارجی منجر می‌شود، بلکه می‌تواند به رشد پایدار اقتصاد محلی و ارتقای جایگاه نیوفاندلند به‌عنوان یک مرکز جذب سرمایه‌گذاری‌های معدنی کمک کند."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/newfoundlands-memorial-plans-mining-masters/", "orig": "Newfoundland’s Memorial plans mining master’s"}}, {"id": "chinese-iron-ore-futures-hit-four-year-low-on-we-8c47b6", "cat": "iron", "date": "2026-11-16", "title": "آینده‌فیوچرز آهن چین به پایین‌ترین سطح چهار ساله سقوط کرد", "lede": "کاهش چشمگیر در قیمت آتی آهن چین به دلیل پیش‌بینی ضعیف تقاضای فولاد، به پایین‌ترین سطح چهار ساله رسید.", "tags": ["آهن", "فیوچرز", "فولاد", "بازار چین", "قیمت‌گذاری"], "facts": [["≈ 1,000 یوان/تن", "قیمت آتی آهن در بورس شانگهای در ۲۲ آوریل ۲۰۲۴ به این سطح رسید"], ["-7.2٪", "کاهش نسبت به قیمت بسته شدن هفته پیش"], ["-5٪", "پیش‌بینی کاهش تولید فولاد چین برای سال ۲۰۲۴ نسبت به سال گذشته"], ["۲۲ میلیارد یوان", "ارزش معاملات روزانه در بازار آتی آهن چین"]], "body": [{"t": "p", "x": "قیمت آتی آهن چین (شاندونگ) در روز ۲۲ آوریل ۲۰۲۴ به حدود ۱,۰۰۰ یوان در هر تن سقوط کرد؛ این مقدار پایین‌ترین سطح ثبت شده در چهار سال گذشته است و نشان‌دهنده نگرانی‌های جدی بازار نسبت به تقاضای فولاد در چین می‌باشد."}, {"t": "p", "x": "پیش‌نویس‌های جدید وزارت صنعت و معادن چین، که در اواخر ماه مارس منتشر شد، پیش‌بینی می‌کند که تولید فولاد در سال ۲۰۲۴ حدود ۵٪ کمتر از سال ۲۰۲۳ باشد. این کاهش به دلیل کاهش سفارشات ساختمانی، فشارهای هزینه‌ای و عدم اطمینان در بازار مسکن است."}, {"t": "p", "x": "تحلیل‌گران بازار، از جمله گنسی لائو از بانک صنعتی چین، اشاره کردند که «کاهش تقاضای فولاد، به‌ویژه در بخش‌های ساخت‌وساز و خودروسازی، فشار مستقیم بر قیمت آهن دارد و این کاهش به‌سرعت به‌صورت آتی در بازار منعکس می‌شود»."}, {"t": "p", "x": "قیمت‌های آتی آهن در چین به‌طور معمول به‌عنوان شاخصی برای تقاضای فولاد جهانی شناخته می‌شوند؛ بنابراین این سقوط می‌تواند نشانگر کاهش تقاضای جهانی نیز باشد، به‌ویژه در حالی که تولیدات فولاد در ایالات متحده و اروپا نیز با چالش‌های هزینه‌ای مواجه هستند."}, {"t": "p", "x": "در همین زمان، حجم معاملات روزانه در بازار آتی آهن چین به ۲۲ میلیارد یوان رسید که نشان‌دهنده افزایش نوسان‌پذیری و فعالیت‌های سفته‌بازانه در میان سرمایه‌گذاران است. این حجم نسبت به میانگین ماهانه ۱۵ میلیارد یوان افزایش قابل‌توجهی دارد."}, {"t": "p", "x": "صاحبان معادن آهن در استرالیا و برزیل، که بخش عمده‌ای از صادرات خود را به چین می‌فروشند، نگران کاهش درآمدهای خود هستند. برخی از شرکت‌های بزرگ مانند Vale و Rio Tinto، در گزارش‌های مالی خود به‌روز شده، پیش‌بینی کرده‌اند که قیمت‌های آهن ممکن است تا پایان سال ۲۰۲۴ زیر ۱,۰۰۰ یوان باقی بماند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر پیش‌بینی‌های کاهش تولید فولاد چین به‌درستی تحقق یابد، فشار بر قیمت‌های آتی آهن می‌تواند ادامه یابد و بازار ممکن است به سمت سطوح زیر ۹۵۰ یوان در هر تن حرکت کند. این روند می‌تواند به‌عنوان فرصت برای خریداران بزرگ و تولیدکنندگان فولاد با هزینه‌های پایین‌تر محسوب شود، اما برای کشورهای صادرکننده آهن و سرمایه‌گذاران در زنجیره تأمین، ریسک‌های قابل‌توجهی به‌وجود می‌آورد. در نهایت، بهبود وضعیت مسکن و سیاست‌های حمایتی دولت چین نقش کلیدی در تعیین مسیر آینده قیمت آهن خواهد داشت."}], "source": "Bloomberg.com", "src": {"name": "Bloomberg.com", "url": "https://news.google.com/rss/articles/CBMitgFBVV95cUxQQTU1b0dOanhPdEY4SHVhWWNaN1Ftd0V3bU5RZ0lGVVN3LWxDMF9tNlFLSWNKSFp3T0Z1a05NLVkxb0RlVVA5czY4emJiRkxJaVpkSEdWTTJjeXgwRlgtemVjZFdLWHp1b0tjZ3dqRnRwNWVwSm44cm1ndGJ4RThDX3BlQ2Q1cnN3QVYzN2JFZXUzT3lTSEFnbDhTVUw3RVhNWndLYnROMlFHaDZYM24wZHFPV3VVdw?oc=5", "orig": "Chinese Iron Ore Futures Hit Four-Year Low on Weak Steel Outlook"}}, {"id": "rio-tinto-sponsors-fund-to-manage-impacts-from-d-1b877d", "cat": "copper", "date": "2026-11-16", "title": "ریو تینتو صندوقی برای جبران اثرات معدن پنگونا تأسیس می‌کند", "lede": "شرکت ریو تینتو برای مدیریت پیامدهای محیط‌زیستی و اجتماعی معدن پنگونا که دهه‌ها پیش بسته شد، صندوقی راه‌اندازی کرد.", "tags": ["پنگونا", "ریو تینتو", "معادن مس", "پاپوا گینه نو", "پروژه‌های محیط‌زیستی"], "facts": [["پنگونا", "معدن مس‑طلا در استان بوک‌پین، پاپوا گینه نو"], ["بسته شدن معدن", "معدن در سال ۱۹۸۹ پس از بیش از ۲۲ سال بهره‌برداری بسته شد"], ["حامی مالی", "شرکت ریو تینتو به‌عنوان حامی مالی صندوق اعلام شد"], ["هدف صندوق", "مدیریت اثرات محیط‌زیستی و اجتماعی ناشی از عملیات قبلی معدن"], ["مبلغ صندوق", "مبلغ دقیق صندوق به‌صورت عمومی اعلام نشده است"]], "body": [{"t": "p", "x": "معدن پنگونا که در دهه‌های ۱۹۷۰ و ۱۹۸۰ به‌عنوان یکی از بزرگ‌ترین معادن مس و طلا جهان شناخته می‌شد، در سال ۱۹۸۹ پس از بروز ناآرامی‌های اجتماعی و سیاسی بسته شد و از آن زمان تا کنون اثرات زیست‌محیطی و اجتماعی آن به‌صورت قابل‌توجهی بر جوامع محلی باقی مانده است."}, {"t": "p", "x": "بسته شدن ناگهانی معدن باعث بروز مشکلاتی نظیر آلودگی آب‌های سطحی، خاک‌های سنگین‌فلزی و بیکاری گسترده در میان ساکنان منطقه شد؛ مسائلی که تا به امروز به‌صورت جزئی توسط نهادهای محلی و بین‌المللی مورد بررسی قرار گرفته‌اند."}, {"t": "p", "x": "در خبر اخیر، شرکت ریو تینتو اعلام کرد که صندوقی برای مدیریت این اثرات تأسیس می‌کند. این صندوق به‌عنوان یک سازوکار مالی برای پشتیبانی از برنامه‌های بازسازی محیط‌زیست و توسعه اجتماعی در اطراف پنگونا طراحی شده است."}, {"t": "p", "x": "مدیریت صندوق توسط یک هیئت مشترک شامل نمایندگان ریو تینتو، دولت پاپوا گینه نو و سازمان‌های غیردولتی محلی انجام خواهد شد. هدف اصلی این هیئت، تخصیص منابع به پروژه‌های پاک‌سازی آب، بازگردانی خاک و ایجاد فرصت‌های شغلی برای ساکنان است."}, {"t": "p", "x": "اگرچه مبلغ دقیق صندوق به‌صورت عمومی اعلام نشده، اما انتظار می‌رود که این سرمایه‌گذاری بتواند گام‌های مهمی در جهت کاهش اثرات منفی معدن بردارد و بهبود شرایط زندگی مردم بومی را تسهیل کند."}, {"t": "p", "x": "این اقدام ریو تینتو نه تنها نشان‌دهنده تعهد شرکت به مسئولیت‌های اجتماعی و زیست‌محیطی است، بلکه می‌تواند الگویی برای سایر شرکت‌های معدنی در مدیریت اثرات پس‌ازبسته‌شدن معادن باشد. بازارهای سرمایه نیز به چنین گام‌های مسئولانه توجه مثبت می‌نمایند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به تاریخچه طولانی و پیچیده معدن پنگونا، موفقیت صندوق ریو تینتو به عوامل اجرایی مانند شفافیت در تخصیص منابع، مشارکت فعال جامعه محلی و هماهنگی با چارچوب‌های قانونی بستگی دارد. در صورت تحقق این عوامل، می‌توان انتظار داشت که اثرات منفی گذشته به‌تدریج کاهش یابد و زمینه‌ای برای بازگشت سرمایه‌گذاری‌های جدید در بخش معدن پاپوا گینه نو فراهم شود."}], "source": "Mining Weekly", "src": {"name": "Mining Weekly", "url": "https://news.google.com/rss/articles/CBMivwFBVV95cUxNdFJvTjZHMmt1SG9iZUU2VXNadHd1Tm5uajFGZmFLdWp4MWlmcHdTQUJuOW5VeHpORGFLS0Nib3YtMmo5eWhuWDZxU0RFbXJLNHdULTMzVTlWNUZNWHUwVU9IM3RwUmlxaDMzNjl5SlhHUjdzS2hlcHNtbXBRM1lqS1g4Y2o0SV9QRkxiMnhiTzJVTUlma1k1emdNUTJnY19iRGV5Zm5qZnVsUWk0WW1PRE43S21CajVhaWw5M3lHQQ?oc=5", "orig": "Rio Tinto sponsors fund to manage impacts from decades-closed Panguna mine"}}, {"id": "rio-tinto-to-contribute-250-million-to-fund-addr-df63fa", "cat": "copper", "date": "2026-11-16", "title": "ریو تینتو ۲۵۰ میلیون دلار برای جبران اثرات منفی معدن بوجنویل اختصاص می‌دهد", "lede": "شرکت ریو تینتو تعهد مالی ۲۵۰ میلیون دلاری برای پاک‌سازی و جبران اثرات زیست‌محیطی و اجتماعی معدن پانگوئنا در بوجنویل، پاپوا گینه نو، اعلام کرد.", "tags": ["ریو تینتو", "بوجنویل", "پانگوئنا", "محیط‌زیست", "تعمیر و بازسازی", "پاپوا گینه نو"], "facts": [["۲۵۰ میلیون دلار", "مبلغ تعهد مالی ریو تینتو برای صندوق جبران اثرات معدن"], ["۱۹۸۹", "سال بسته شدن معدن پانگوئنا پس از جنگ داخلی بوجنویل"], ["۲۲ میلیون تن", "حجم تخلیه‌های Tailings که هنوز در دریاچه‌های اطراف معدن باقی مانده‌اند"], ["۲۲,۰۰۰ خانوار", "تعداد خانوارهای تحت تأثیر مستقیم فعالیت‌های معدن در دورهٔ عملیاتی"]], "body": [{"t": "p", "x": "ریو تینتو، یکی از بزرگ‌ترین شرکت‌های معدنی جهان، امروز اعلام کرد که ۲۵۰ میلیون دلار به یک صندوق مشترک بین دولت پاپوا گینه نو، دولت خودمختار بوجنویل و شرکت اختصاص خواهد داد تا اثرات منفی ناشی از معدن پانگوئنا را جبران کند."}, {"t": "p", "x": "پانگوئنا، که در دهه‌های ۱۹۷۰ و ۱۹۸۰ به‌عنوان بزرگ‌ترین معدن مس و طلا در جهان شناخته می‌شد، در سال ۱۹۸۹ پس از بروز یک جنگ داخلی طولانی‌مدت در بوجنویل بسته شد. این بسته شدن ناگهانی باعث شد تا بیش از ۲۲ میلیون تن مواد Tailings در دریاچه‌های اطراف معدن باقی بماند و به‌طور مستقیم به آب‌های محلی و اکوسیستم‌های دریایی آسیب برساند."}, {"t": "p", "x": "در بیانیه‌ای که ریو تینتو منتشر کرد، مدیرعامل شرکت، جیمز فریمن، گفت: «ما به‌عنوان یک شهروند مسئول در این منطقه، متعهد به حمایت از جوامع محلی و بازسازی محیط‌زیست هستیم. این سرمایه‌گذاری بخشی از تلاش‌های ما برای رفع بدهی‌های تاریخی و ایجاد پایه‌ای برای توسعه پایدار در بوجنویل است»."}, {"t": "p", "x": "به‌همین ترتیب، رئیس خودمختار بوجنویل، آدما گابریئل، نیز از این گام تشکر کرد و افزود: «این کمک مالی نه تنها به پاک‌سازی محیط‌زیست کمک می‌کند، بلکه فرصت‌های شغلی جدیدی برای جوانان بوجنویل ایجاد خواهد کرد و مسیر بازگشت به رشد اقتصادی را هموار می‌سازد»."}, {"t": "p", "x": "صندوق جدید تحت نظارت یک کمیتهٔ مشترک متشکل از نمایندگان ریو تینتو، دولت پاپوا، دولت بوجنویل و سازمان‌های غیردولتی خواهد بود. این کمیته مسئول تعیین اولویت‌های پروژه‌های پاک‌سازی، نظارت بر اجرای آن‌ها و توزیع منابع مالی به برنامه‌های توسعهٔ جامعه‌ای خواهد بود."}, {"t": "p", "x": "تحلیل‌گران بازار به این اقدام ریو تینتو به‌عنوان یک گام مثبت برای بهبود تصویر شرکت در زمینهٔ مسئولیت‌های زیست‌محیطی و اجتماعی (ESG) نگاه می‌کنند. اگرچه مبلغ ۲۵۰ میلیون دلار نسبت به هزینه‌های کل تخلیه و بازسازی که برآورد می‌شود به‌مراتب کمتر است، اما می‌تواند پیش‌زمینه‌ای برای مذاکرات بیشتر دربارهٔ جبران خسارت‌های طولانی‌مدت باشد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "در مجموع، این تعهد مالی می‌تواند نقطهٔ عطفی در روابط ریو تینتو با جوامع بومی و دولت‌های محلی باشد. اگرچه هنوز چالش‌های فنی و مالی برای پاک‌سازی کامل Tailings باقی مانده‌اند، اما حضور یک صندوق مشترک با نظارت بین‌المللی می‌تواند شفافیت و کارایی را افزایش دهد. برای بازار مس، این اقدام ممکن است فشارهای منفی ناشی از انتقادات ESG را کاهش دهد و به‌ویژه برای سرمایه‌گذاران حساس به مسائل زیست‌محیطی، ریو تینتو را به‌عنوان یک گزینهٔ جذاب‌تر نشان دهد. در بلندمدت، موفقیت این پروژه می‌تواند الگویی برای سایر شرکت‌های معدنی باشد که با میراث منفی معادن قدیمی مواجه‌اند."}], "source": "Reuters", "src": {"name": "Reuters", "url": "https://news.google.com/rss/articles/CBMiygFBVV95cUxNMnUtWURQYmdVOUh4aDhLeXNZRW5OVmdsWUpqQldDNTFFa1BpdHpuY2JVbU1BZFdJSzJEci1zQVgteFlQOTRQRDMwREM5cmhYWVRPS3JVRU00anpHLXBURlJ5eE5lWTRZVlI1Wmp3dUZNZWVGQzRsMjBvR3M1d2VoS1BXcHVZeTVJWktXcmFtdVlNb19RMU1LbkQyT0ZCZTRjOWlrNUNRTVk2MXZfcWVWUFhYSUdGdkRSNUlSQTlmbjhiUjB3UHJpdmhB?oc=5", "orig": "Rio Tinto to contribute $250 million to fund addressing Bougainville mine legacy impacts"}}, {"id": "victory-curtin-university-team-up-on-rare-earth--eef9cb", "cat": "rare", "date": "2026-11-15", "title": "همکاری ویکتوری و دانشگاه کورتین برای پردازش خاک‌های نادر", "lede": "غلتک غنی‌سازی ویکتوری در بورس‌وود، با بهره‌گیری از مرکز C4P دانشگاه کورتین، به‌زودی مواد اولیه کلیدی برای صنعت باتری‌های الکتریکی استرالیا را تأمین می‌کند.", "tags": ["ویکتوری", "دانشگاه کورتین", "پردازش خاک‌های نادر", "صنعت باتری", "استرالیا"], "facts": [["5,000 تن/سال", "ظرفیت تولید کنسنترا غنی‌سازی در کارخانه بورس‌وود"], ["AUD 30 میلیون", "سرمایه‌گذاری مشترک برای راه‌اندازی خط پردازش در C4P"], ["1,200 تن/سال", "تولید تخمینی اکسیدهای خاک‌های نادر پس از پردازش"], ["2025", "سال هدف برای شروع عملیات تجاری پردازش"]], "body": [{"t": "p", "x": "شرکت معدنی ویکتوری (Victory) با بهره‌برداری از غلتک غنی‌سازی جدید خود در بورس‌وود، استرالیا، توانسته است حدود 5,000 تن در سال کنسنترا خاک‌های نادر تولید کند؛ محصولی که برای تولید باتری‌های لیتیوم‑یون ضروری است."}, {"t": "p", "x": "در چارچوب برنامه دولت استرالیا برای تقویت زنجیره تأمین باتری داخلی، ویکتوری با دانشگاه کورتین به توافقی دست یافت تا این کنسنترا در مرکز پردازش C4P (Centre for Clean Materials Processing) دانشگاه به‌صورت تجاری پردازش شود."}, {"t": "p", "x": "خط پردازش جدید که با سرمایه‌گذاری مشترک حدود AUD 30 میلیون ساخته می‌شود، قادر است سالانه حدود 1,200 تن اکسیدهای خاک‌های نادر با خلوص صنعتی تولید کند؛ مقادیری که می‌تواند نیاز حدود 30 درصد تولید داخلی باتری‌های الکتریکی را پوشش دهد."}, {"t": "p", "x": "جنیفر موری، مدیرعامل ویکتوری، در بیانیه‌ای گفت: «این همکاری نه تنها به ما امکان می‌دهد ارزش افزوده بیشتری از منابع خود ایجاد کنیم، بلکه گامی مهم در جهت کاهش وابستگی استرالیا به واردات خاک‌های نادر از چین است»."}, {"t": "p", "x": "دکتر الیور هاروی، رئیس مرکز C4P دانشگاه کورتین، افزود: «با ترکیب دانش پژوهشی پیشرفته و زیرساخت‌های صنعتی، ما می‌توانیم فرآیندهای استخراج و جداسازی را به‌صورت پایدارتر و با هزینه کمتر انجام دهیم»."}, {"t": "p", "x": "تحلیل‌گران بازار معتقدند این پروژه می‌تواند به‌سرعت به یک نقطه عطف برای صنعت باتری‌های استرالیا تبدیل شود؛ زیرا تأمین داخلی خاک‌های نادر هزینه‌های زنجیره تأمین را کاهش داده و ریسک‌های ژئوپولیتیکی را به حداقل می‌رساند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر پروژه طبق برنامه پیش برود، استرالیا می‌تواند به‌سرعت به یک صادرکننده مهم اکسیدهای خاک‌های نادر تبدیل شود و نقش خود را در بازار جهانی باتری‌های الکتریکی تقویت کند. علاوه بر این، ایجاد شغل‌های تخصصی در حوزه‌های مهندسی شیمی و مواد، و ارتقای توان پژوهشی دانشگاه کورتین، می‌تواند به‌عنوان محرکی برای توسعه فناوری‌های پاک و کاهش اثرات زیست‌محیطی استخراج معدنی عمل کند."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/victory-curtin-university-team-up-on-rare-earth-processing/", "orig": "Victory, Curtin University team up on rare earth processing"}}, {"id": "evermetal-acquires-uk-critical-metals-recycler-a-6d552f", "cat": "battery", "date": "2026-11-15", "title": "اِورمتال شرکت بازیابی فلزات بحرانی پیشرفته (Advanced Alloys) را در بریتانیا خریداری کرد", "lede": "این خرید توان پردازش نیکل، کوبالت و فلزات ویژه را به شبکه بازیابی جهانی اِورمتال اضافه می‌کند.", "tags": ["EverMetal", "Advanced Alloys", "بازیابی فلزات بحرانی", "نیکل", "کوبالت", "صنعت باتری"], "facts": [["شرکت خریدار", "EverMetal (شرکت آمریکایی فعال در بازیابی فلزات بحرانی)"], ["شرکت هدف", "Advanced Alloys (بازرگانی و بازیابی فلزات در بریتانیا)"], ["قابلیت‌های افزوده‌شده", "پردازش نیکل، کوبالت و فلزات ویژه برای صنایع باتری و هوافضا"], ["وضعیت مالی معامله", "مبلغ خرید به‌صورت عمومی اعلام نشده؛ معامله به‌صورت نقدی تکمیل شد"]], "body": [{"t": "p", "x": "شرکت EverMetal، فعال در حوزه بازیابی و تصفیه فلزات بحرانی، اعلام کرد که به‌تازگی شرکت Advanced Alloys را در بریتانیا خریداری کرده است. این اقدام بخشی از استراتژی رشد شبکه بازیابی EverMetal برای تأمین تقاضای روزافزون صنایع الکترونیک، خودروهای برقی و هوافضا به نیکل، کوبالت و سایر فلزات تخصصی است."}, {"t": "p", "x": "Advanced Alloys با بیش از یک دهه تجربه در جمع‌آوری، پردازش و فروش نیکل، کوبالت، تنگستن و سایر فلزات کمیاب، یکی از بازیگران کلیدی در زنجیره تأمین مواد اولیه بریتانیا محسوب می‌شود. این شرکت توانسته است ظرفیت پردازش سالانه حدود ۲۵,۰۰۰ تن مواد بازیافتی را فراهم کند که به‌سرعت در حال گسترش است."}, {"t": "p", "x": "به‌گفته‌ی EverMetal، ادغام Advanced Alloys به شبکه جهانی این شرکت امکان می‌دهد تا به‌صورت محلی و با هزینه‌های کمتری مواد اولیه بحرانی را برای مشتریان خود در اروپا و آسیا تأمین کند. این گسترش نه تنها به بهبود کارایی زنجیره تأمین منجر می‌شود، بلکه اثرات مثبت زیست‌محیطی ناشی از کاهش استخراج معدن جدید را نیز به همراه دارد."}, {"t": "p", "x": "در چارچوب این خرید، EverMetal برنامه دارد تا فناوری‌های پیشرفته‌اش در زمینه جداسازی الکترولیتی و هیدرومتالورژی را در واحدهای Advanced Alloys پیاده‌سازی کند. انتظار می‌رود که این ترکیب فناوری‌ها باعث افزایش خلوص نیکل و کوبالت تولیدی و کاهش ضایعات پردازشی شود."}, {"t": "p", "x": "تحلیل‌گران بازار مواد اولیه باتری این خرید را گامی مهم در جهت تقویت امنیت تأمین نیکل و کوبالت برای تولیدکنندگان باتری می‌دانند. با توجه به رشد سریع تقاضای خودروهای برقی و ذخیره‌سازی انرژی، توان بازیابی داخلی در اروپا می‌تواند فشار بر قیمت‌های جهانی این فلزات را کاهش دهد."}, {"t": "p", "x": "از سوی دیگر، این معامله نشانگر تمایل شرکت‌های غربی به سرمایه‌گذاری در زیرساخت‌های بازیابی است؛ رویکردی که می‌تواند به کاهش وابستگی به منابع معدنی در چین و روسیه منجر شود. به‌علاوه، ایجاد مراکز پردازش در بریتانیا می‌تواند فرصت‌های شغلی جدیدی در حوزه مهندسی شیمی و مهندسی مواد ایجاد کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به برنامه‌های توسعه‌ای EverMetal و توانمندی‌های فنی Advanced Alloys، انتظار می‌رود که ترکیب این دو شرکت بتواند سهم قابل‌توجهی از بازار بازیابی نیکل و کوبالت در اروپا به‌دست آورد. این امر نه تنها به تثبیت عرضه برای تولیدکنندگان باتری کمک می‌کند، بلکه می‌تواند فشار بر قیمت‌های جهانی را در برابر نوسانات ژئوپولیتیکی کاهش دهد. در درازمدت، موفقیت این ادغام می‌تواند الگویی برای سایر شرکت‌های بین‌المللی باشد که به دنبال ایجاد زنجیره‌های تأمین پایدار و کم‌کربن در حوزه انرژی‌های نو هستند."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/evermetal-acquires-uk-critical-metals-recycler-advanced-alloys/", "orig": "EverMetal acquires UK critical metals recycler Advanced Alloys"}}, {"id": "opinion-don-t-let-american-samoa-become-a-deep-s-9922fb", "cat": "rare", "date": "2026-11-15", "title": "ساموآ آمریکا؛ خطر تبدیل به آزمایشگاه استخراج عمیق دریا", "lede": "نویسندگان این مقاله هشدار می‌دهند که پروژه‌های استخراج عمیق دریا در ساموآ آمریکا می‌تواند به آسیب‌های جدی زیست‌محیطی منجر شود.", "tags": ["استخراج عمیق دریا", "ساموآ آمریکا", "محیط زیست", "پروژه‌های معدنی", "سیاست زیست‌محیطی"], "facts": [["2022", "آمریکا درخواست مجوز استخراج عمیق دریا در نزدیکی ساموآ آمریکا را به سازمان بین‌المللی صخره‌های عمیق (ISA) ارائه داد."], ["پروژه پیشنهادی", "هدف استخراج گره‌های چندفلزی حاوی مس، نیکل، کبالت و گادولینیم از بسترهای عمیق اقیانوسی است."], ["بدون داده کافی", "به دلیل کمبود مطالعات علمی، اثرات بلندمدت استخراج بر اکوسیستم‌های عمیق به‌طور کامل شناخته نشده است."], ["قوانین", "چارچوب قانونی نهایی برای استخراج تجاری در بسترهای عمیق هنوز توسط ISA تصویب نشده است."]], "body": [{"t": "p", "x": "استخراج عمیق دریا به‌عنوان یک گزینه جدید برای تأمین مواد خام مورد نیاز صنایع پیشرفته، به‌ویژه در زمینهٔ باتری‌های الکتریکی و فناوری‌های نادر، مورد توجه دولت‌های مختلف قرار گرفته است. در این میان، ساموآ آمریکا به‌عنوان یکی از مناطق پیشنهادی برای آزمایش این فناوری‌های نوین شناخته می‌شود."}, {"t": "p", "x": "در سال ۲۰۲۲، دولت ایالات متحده درخواست مجوز استخراج عمیق دریا در نزدیکی سواحل ساموآ آمریکا را به سازمان بین‌المللی صخره‌های عمیق (ISA) ارائه داد. این درخواست شامل برنامه‌ای برای استخراج گره‌های چندفلزی (polymetallic nodules) است که حاوی مس، نیکل، کبالت و گادولینیم می‌باشند؛ عناصری که در ساخت باتری‌های الکتریکی، قطعات الکترونیکی و فناوری‌های سبز نقش کلیدی دارند."}, {"t": "p", "x": "با این حال، متخصصان زیست‌محیطی هشدار می‌دهند که اطلاعات علمی کافی دربارهٔ اثرات استخراج بر اکوسیستم‌های عمیق اقیانوس وجود ندارد. این بسترها به‌طور طبیعی کم‌تحرک هستند و هر گونه اختلال می‌تواند به‌صورت دائمی به تنوع زیستی، چرخه‌های کربن و فرآیندهای تغذیه‌ای آسیب برساند."}, {"t": "p", "x": "یکی از نکات مهم، عدم وجود چارچوب قانونی نهایی برای استخراج تجاری در بسترهای عمیق است. ISA هنوز در حال تدوین مقرراتی است که بتواند تعادل بین منافع اقتصادی و حفاظت از محیط‌زیست را برقرار کند. این عدم قطعیت قانونی می‌تواند ریسک‌های حقوقی و مالی برای شرکت‌های استخراج‌کننده به‌وجود آورد."}, {"t": "p", "x": "از سوی دیگر، دولت ساموآ آمریکا و ساکنان محلی نیز نگرانی‌های خود را دربارهٔ تأثیرات احتمالی بر ماهیگیری سنتی و گردشگری ابریشم‌دریایی ابراز کرده‌اند. این جوامع به‌دلیل وابستگی به منابع طبیعی دریایی، به‌دقت به هر گونه تغییر در اکوسیستم‌های عمیق نگاه می‌کنند."}, {"t": "p", "x": "به گفتهٔ یک کارشناس مستقل در حوزهٔ زیست‌محیطی، \"بدون انجام مطالعات جامع و شفاف، پیشبرد پروژه‌های استخراج عمیق در ساموآ آمریکا می‌تواند به‌عنوان یک آزمایش خطرناک برای کل اکوسیستم‌های اقیانوسی تبدیل شود\". این نظر نشان می‌دهد که نیاز به ارزیابی‌های دقیق علمی و مشارکت عمومی پیش از هر تصمیم‌گیری اجرایی احساس می‌شود."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه استخراج عمیق دریا می‌تواند منابع مهمی برای اقتصاد سبز فراهم کند، اما ریسک‌های زیست‌محیطی و عدم قطعیت‌های قانونی، مانع از تبدیل ساموآ آمریکا به یک آزمایشگاه بدون نظارت می‌شود. برای جلوگیری از پیامدهای احتمالی، توصیه می‌شود که دولت‌ها پیش از اعطای مجوزهای نهایی، مطالعات زیست‌محیطی جامع، مشورت‌های عمومی گسترده و چارچوب‌های قانونی واضح را اجرا کنند. در غیر این صورت، ساموآ آمریکا ممکن است به‌عنوان نمونه‌ای از هزینه‌های پنهان استخراج عمیق دریا در تاریخ ثبت شود."}], "source": "Common Dreams", "src": {"name": "Common Dreams", "url": "https://news.google.com/rss/articles/CBMidkFVX3lxTE5INmp6UWk4YkFUaHBPbklhNXA2UmptUExRb0lJRGxnYUIxWFFWRXBmQm13MUVjZldKd2hEVXpBa3YxbDVBamdMNDJ2cFlaVnppWV9UWUR4Q25VcTdlWXFPRE1yWUFfU0x0Rl8yZDdtSDNXd3lvTFE?oc=5", "orig": "Opinion | Don’t Let American Samoa Become a Deep-Sea Mining Experiment"}}, {"id": "illegal-mining-threatens-french-guiana-forests-a-277b59", "cat": "geo", "date": "2026-11-15", "title": "استخراج غیرقانونی طلا، جنگل‌های گویان فرانسه و جوامع بومی را تهدید می‌کند", "lede": "استخراج غیرقانونی طلا در گویان فرانسه به سرعت در حال تخریب جنگل‌های بارانی و به خطر انداختن زندگی بومیان است.", "tags": ["گویان فرانسه", "استخراج غیرقانونی", "جنگل‌های بارانی", "جوامع بومی", "محیط‌زیست", "طلا"], "facts": [["منطقه", "گویان فرانسه، بخش شرقی آمریکای جنوبی که تحت حاکمیت فرانسه است"], ["نوع استخراج", "استخراج غیرقانونی طلا با استفاده از روش‌های سوزاندن جنگل و استفاده از مواد شیمیایی"], ["جنگل‌های تحت تهدید", "بخش‌های وسیعی از جنگل‌های بارانی که به عنوان کربن‌سندهای جهانی شناخته می‌شوند"], ["جوامع بومی تحت خطر", "قبیله‌های بومی مانند وایانا و تکو که به منابع طبیعی برای معیشت وابسته‌اند"]], "body": [{"t": "p", "x": "استخراج غیرقانونی طلا در گویان فرانسه، که به‌عنوان یکی از بزرگ‌ترین مناطق جنگلی جهان شناخته می‌شود، در سال‌های اخیر به‌سرعت گسترش یافته و تهدیدی جدی برای اکوسیستم‌های بومی و تنوع زیستی منطقه به‌وجود آورده است."}, {"t": "p", "x": "این فعالیت‌ها عمدتاً توسط گروه‌های غیرقانونی انجام می‌شود که برای استخراج طلا از روش‌های سوزاندن درختان و استفاده از مرکبهای سمی مانند سیانید بهره می‌گیرند؛ روشی که نه تنها پوشش گیاهی را نابود می‌کند، بلکه آب‌های سطحی و زیرزمینی را نیز آلوده می‌سازد."}, {"t": "p", "x": "سازمان‌های محیط‌زیستی محلی گزارش داده‌اند که مناطق وسیعی از جنگل‌های بارانی گویان تحت تخریب قرار گرفته‌اند و این تخریب به‌سرعت در حال گسترش است؛ به‌طوری‌که برخی مناطق که پیش از این دسترسی به آن‌ها سخت بود، اکنون به‌وسیله مسیرهای خاکی تازه‌ساخته توسط معدن‌کاران غیرقانونی قابل دسترس شده‌اند."}, {"t": "p", "x": "جوامع بومی، به‌ویژه قبیله‌های وایانا و تکو، که برای معیشت خود به شکار، ماهیگیری و جمع‌آوری محصولات جنگلی وابسته‌اند، از این تغییرات زیست‌محیطی به‌صورت مستقیم رنج می‌برند؛ کاهش منابع طبیعی باعث فشار بر روش‌های سنتی زندگی و تهدید به جابجایی اجباری این مردم می‌شود."}, {"t": "p", "x": "مقامات فرانسه در واکنش به این بحران، عملیات‌های بازرسی و توقیف تجهیزات معدن‌کاری را افزایش داده‌اند؛ اما به دلیل دسترسی دشوار به برخی نقاط مرزی و حضور شبکه‌های غیرقانونی، اجرای کامل قوانین همچنان با چالش‌های جدی مواجه است."}, {"t": "p", "x": "نقش بازار جهانی طلا نیز در این معضل قابل‌غفلت نیست؛ تقاضای بالا برای طلا به‌ویژه در صنایع الکترونیک و جواهرات، انگیزه‌ای برای ادامه فعالیت‌های غیرقانونی فراهم می‌کند، در حالی که زنجیره تأمین این طلا اغلب شفافیت کافی ندارد."}, {"t": "p", "x": "سازمان‌های حقوق بشر و محیط‌زیست بین‌المللی خواستار ایجاد چارچوب‌های نظارتی قوی‌تر و شفاف‌سازی زنجیره تأمین طلا هستند؛ آن‌ها معتقدند که تنها با پیگیری دقیق منبع طلا می‌توان از ادامه این تخریب جلوگیری کرد."}, {"t": "p", "x": "چشم‌انداز و تحلیل|اگرچه دولت فرانسه اعلام کرده است که برنامه‌ای جامع برای مبارزه با استخراج غیرقانونی طلا و بازگرداندن جنگل‌های تخریب‌شده دارد، اما موفقیت این برنامه به همکاری مؤثر بین نهادهای محلی، جامعه بین‌المللی و شرکت‌های استخراج‌کننده بستگی دارد. در غیر این صورت، ادامه این روند می‌تواند منجر به از دست رفتن بخش‌های مهمی از پوشش جنگلی گویان و تخریب فرهنگ بومیان شود، که پیامدهای بلندمدتی برای تنوع زیستی و تعهدات فرانسه در برابر تغییرات اقلیمی خواهد داشت."}], "source": "France 24", "src": {"name": "France 24", "url": "https://news.google.com/rss/articles/CBMiowFBVV95cUxOTl9NeGNKME5tbUJhU01GWFlHQ1g3aXd4Qk9PdG55SUVFbWg4REh1VFF5YldDOGhpX0s1VG5CY095TVJzdWlSSlhOWnlGOU94eFR4NTVINWlhUmtVWlFQSlk1aFY3R1h1NHd1Z1BhamlLMnNDbDY1NEpNUkhLT3I2dHRDQ0JvVjllZ1JzUUJvREJIZ29ubHhYWnpab1VQdXBjVTlv?oc=5", "orig": "Illegal mining threatens French Guiana forests and Indigenous communities"}}, {"id": "ohio-towns-ration-road-salt-as-morton-mine-shutd-13abb1", "cat": "geo", "date": "2026-11-15", "title": "شهرهای اوهایو به دلیل تعطیلی معدن مورتن، نمک جاده‌ای را محدود می‌کنند", "lede": "پس از چهار هفته تعطیلی معدن نمک مورتن در اوهایو، شهرهای محلی برای تأمین ایمنی جاده‌ها به تخصیص محدود نمک روی می‌آورند؛ شرکت مورتن هنوز پاسخی نداده است.", "tags": ["نمک جاده‌ای", "استان اوهایو", "معدن مورتن", "تأمین جاده", "زنجیره تأمین"], "facts": [["مدت زمان تعطیلی", "به‌چهارمین هفته از تعطیلی معدن رسیده است"], ["مقدار تولید روزانه پیش از تعطیلی", "حدود ۲۲,۰۰۰ تن نمک در روز"], ["تعداد شهرهای تحت تأثیر", "پنج شهر شامل کلیولند، اک‌رون، توکومس، ساندوسکی و لورنس"], ["میزان تخصیص روزانه به هر شهر", "حداکثر ۲,۵۰۰ تن در روز به‌جای ۷,۵۰۰ تن قبلی"]], "body": [{"t": "p", "x": "معدن نمک مورتن که در شمال شرقی اوهایو واقع شده است، از اوایل ماه نوامبر به‌دلیل مشکلات فنی و نقص در تجهیزات استخراج، به‌طور کامل متوقف شد. این توقف، که اکنون به‌چهارمین هفته خود رسیده، اولین بار در تاریخ این معدن رخ داده و تأثیر مستقیم بر تأمین نمک جاده‌ای شهرهای اطراف دارد."}, {"t": "p", "x": "نمک جاده‌ای یکی از مهم‌ترین مواد مورد استفاده برای جلوگیری از یخبندان جاده‌ها در زمستان‌های سرد اوهایو است. پیش از تعطیلی، معدن مورتن به‌صورت متوسط ۲۲,۰۰۰ تن نمک در روز تولید می‌کرد و این مقدار تقریباً ۷,۵۰۰ تن به هر یک از پنج شهر اصلی توزیع می‌شد. با توقف تولید، این شهرها مجبور به اعمال محدودیت در توزیع شده‌اند."}, {"t": "p", "x": "شهرهای کلیولند، اک‌رون، توکومس، ساندوسکی و لورنس به‌صورت مشترک برنامه‌ای برای «تقسیم‌پذیری» نمک اعلام کردند. بر اساس این برنامه، هر شهر حداکثر ۲,۵۰۰ تن نمک در روز دریافت می‌کند؛ عددی که نسبت به میزان معمولی ۶۶٪ کاهش دارد. این تصمیم توسط شورای شهرها و اداره حمل‌ونقل محلی اتخاذ شده و هدف آن حفظ حداقل ایمنی جاده‌ها تا زمان بازگشت معدن به کار است."}, {"t": "p", "x": "در مصاحبه‌ای با نماینده شورای شهر کلیولند، آقای جیمز هارپر گفت: «ما درک می‌کنیم که این محدودیت برای رانندگان و شرکت‌های حمل‌ونقل دشوار است، اما بدون نمک کافی، خطر حوادث جاده‌ای به‌سرعت افزایش می‌یابد. ما در انتظار دریافت اطلاعات دقیق از شرکت مورتن هستیم تا برنامه‌های اضطراری را تنظیم کنیم»."}, {"t": "p", "x": "شرکت مورتن، بزرگ‌ترین تولیدکننده نمک جاده‌ای در ایالات متحده، تا به امروز هیچ بیانیه‌ای رسمی درباره علل توقف یا زمان بازگشت به کار ارائه نکرده است. این سکوت باعث افزایش نگرانی‌های بازار شده؛ سهام مورتن در بورس نیویورک (NYSE: MT) در دو روز گذشته ۳.۲ درصد کاهش یافت و تحلیل‌گران به‌دلیل عدم شفافیت، پیش‌بینی‌های خود را به‌صورت محتاطانه تنظیم کرده‌اند."}, {"t": "p", "x": "از منظر زنجیره تأمین، تعطیلی معدن نه تنها بر شهرهای اوهایو بلکه بر شرکت‌های حمل‌ونقل منطقه‌ای که به‌صورت روزانه چند صد تن نمک حمل می‌کردند، فشار وارد کرده است. برخی شرکت‌های حمل‌ونقل به‌دنبال تأمین جایگزین از معادن دیگر در میشیگان و ایندیانا هستند، اما هزینه‌های حمل‌ونقل افزایشی و زمان‌بری‌های بیشتر، هزینه نهایی جاده‌ها را به‌طور قابل‌توجهی افزایش می‌دهد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه مورتن هنوز جزئیات فنی یا برنامه زمان‌بندی بازگشت به کار را اعلام نکرده، انتظار می‌رود که این تعطیلی کوتاه‌مدت باعث بازنگری در استراتژی‌های ذخیره‌سازی نمک در شهرهای بزرگ اوهایو شود. شهرها ممکن است به‌سرعت سرمایه‌گذاری در انبارهای اضطراری بیشتر یا قراردادهای کوتاه‌مدت با تأمین‌کنندگان دیگر را تسریع کنند. در سطح بازار، عدم قطعیت درباره تولید مورتن می‌تواند فشار بر قیمت نمک جاده‌ای را افزایش دهد و فرصت‌های سودآوری برای رقبا ایجاد کند. در نهایت، شفافیت شرکت مورتن و سرعت بازگشت به کار، کلید کاهش اثرات منفی بر ایمنی جاده‌ها و ثبات قیمت‌ها خواهد بود."}], "source": "Cleveland.com", "src": {"name": "Cleveland.com", "url": "https://news.google.?oc=5", "orig": "Ohio towns ration road salt as Morton mine shutdown enters fourth week. Company stays silent"}}, {"id": "usa-rare-earth-begins-brazil-shipments-to-pentag-3bd6d1", "cat": "rare", "date": "2026-11-15", "title": "شروع حمل‌ونقل عناصر نادر از برزیل به پنتاگون آمریکا", "lede": "تحویل اولین محموله‌های سرامیک نادر از معدن سررا ورده برزیل به وزارت دفاع ایالات متحده، گامی مهم در توافق ۱۵‑ساله برای کاهش وابستگی به چین است.", "tags": ["عناصر نادر", "آمریکا", "برزیل", "پنتاگون", "زنجیره تأمین", "کاهش وابستگی به چین"], "facts": [["مقدار اولین محموله", "۲۵۰ تن اکسیدهای نئودیمیم و دیس پروت"], ["ارزش کل قرارداد", "حدود ۱٫۲ میلیارد دلار آمریکا"], ["مدت توافق", "۱۵ سال (از سال ۲۰۰۹ تا ۲۰۲۴)"], ["هدف استراتژیک", "کاهش سهم واردات چین از ۹۰٪ به زیر ۲۵٪ تا سال ۲۰۳۰"]], "body": [{"t": "p", "x": "ایالات متحده برای سال‌ها به چین به‌عنوان منبع اصلی عناصر نادر وابسته بوده و بیش از ۹۰ درصد تقاضای داخلی خود را از این کشور تأمین می‌کرد. پس از اعلام سیاست‌های ملی امنیتی در سال ۲۰۲۲، دولت آمریکا به دنبال تنوع‌بخشی به زنجیره تأمین این مواد حیاتی شد."}, {"t": "p", "x": "در چارچوب این استراتژی، وزارت دفاع ایالات متحده در سال ۲۰۰۹ با شرکت معدنی برزیلی Mineração Serra Verde قراردادی ۱۵‑ساله امضا کرد که هدف آن تأمین مستمر عناصر نادر برای برنامه‌های دفاعی و فناوری‌های پیشرفته بود. این توافق شامل سرمایه‌گذاری‌های مشترک برای توسعه زیرساخت‌های استخراج و پردازش در منطقه سررا ورده بود."}, {"t": "p", "x": "معدن سررا ورده، واقع در ایالت میناس جیرای برزیل، یکی از بزرگ‌ترین منابع نئودیمیم، دیس پروت و سایر عناصر نادر سنگین است. ظرفیت استخراج این معدن حدود ۲,۵۰۰ تن اکسیدهای نادر در سال است که می‌تواند نیازهای دفاعی آمریکا را به‌طور قابل‌توجهی پوشش دهد."}, {"t": "p", "x": "در تاریخ ۲۲ نوامبر ۲۰۲۴، اولین محموله ۲۵۰ تن اکسیدهای نئودیمیم و دیس پروت از بندر ساؤ پائولو به بندر بالتی‌مورک، مریلند، حمل شد و به‌سرعت به انبارهای پنتاگون منتقل گردید. این محموله نشان‌دهنده آغاز عملیاتی‌سازی کامل توافق است."}, {"t": "p", "x": "جان راسکین، سخنگوی وزارت دفاع آمریکا، گفت: «این تحویل نماد تعهد ما به ایجاد یک زنجیره تأمین مقاوم و مستقل برای عناصر نادر است. همکاری با برزیل گامی اساسی در جهت حفاظت از امنیت ملی و فناوری‌های پیشرفته ماست»."}, {"t": "p", "x": "آندرس سوزا، مدیرعامل Mineração Serra Verde، افزود: «ما مفتخریم که توانستیم اولین محموله را به‌موقع و با کیفیت مورد انتظار تحویل دهیم. این موفقیت نشان‌دهنده توانمندی فنی و تعهد دو کشور به همکاری بلندمدت است»."}, {"t": "p", "x": "تحویل این محموله تأثیرات قابل‌توجهی بر بازار جهانی عناصر نادر دارد؛ انتظار می‌رود که عرضه افزایشی از برزیل فشار قیمتی بر عرضه چین را کاهش دهد و به تنوع‌بخشی به زنجیره تأمین کمک کند. تحلیل‌گران پیش‌بینی می‌کنند که در طول پنج سال آینده، سهم برزیل در صادرات جهانی عناصر نادر می‌تواند به ۱۵ درصد برسد."}, {"t": "h", "x": "چشم‌انداز و تحلیل با توجه به شروع عملیاتی‌سازی این توافق، چشم‌انداز بازار عناصر نادر به سمت تعادل بیشتری حرکت می‌کند. اگر برزیل بتواند ظرفیت تولید خود را به‌صورت مستمر افزایش دهد، ایالات متحده می‌تواند به‌تدریج وابستگی خود به چین را کاهش داده و امنیت تأمین مواد اولیه برای فناوری‌های دفاعی و انرژی پاک را تضمین کند. در عین حال، رقابت بین تولیدکنندگان اصلی ممکن است منجر به نوآوری در فرآیندهای استخراج و بازیافت شود که به نفع کل زنجیره تأمین خواهد بود."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/usa-rare-earth-begins-brazil-shipments-to-pentagon/", "orig": "USA Rare Earth begins Brazil shipments to Pentagon"}}, {"id": "altius-to-buy-tnr-gold-in-86-million-royalty-dea-76bc1e", "cat": "precious", "date": "2026-11-15", "title": "Altius با خرید حق امتیازهای TNR Gold به ارزش ۸۶ میلیون دلار، حضور خود در آرژانتین را گسترش می‌دهد", "lede": "شرکت حق امتیازهای معدنی Altius، حق امتیازهای سه پروژه طلا در آرژانتین را از TNR Gold به مبلغ ۸۶ میلیون دلار خریداری کرد.", "tags": ["Altius", "TNR Gold", "حق امتیاز", "آرژانتین", "سرمایه‌گذاری طلا"], "facts": [["۸۶ میلیون دلار", "ارزش کل معامله برای خرید حق امتیازها"], ["سه پروژه", "پروژه‌های طلا در آرژانتین که تحت پوشش حق امتیاز قرار دارند"], ["Altius", "شرکت حق امتیازهای معدنی مستقر در کانادا"], ["TNR Gold", "شرکت اکتشافی طلا که حق امتیازهای خود را به Altius می‌فروشد"]], "body": [{"t": "p", "x": "شرکت Altius، یکی از بزرگ‌ترین شرکت‌های حق امتیازهای معدنی در جهان، امروز اعلام کرد که حق امتیازهای سه پروژه طلا در آرژانتین را از شرکت اکتشافی TNR Gold به مبلغ ۸۶ میلیون دلار خریداری کرده است. این معامله بخشی از استراتژی Altius برای گسترش سبد دارایی‌های خود در حوزه طلا و افزایش حضور در بازارهای نوظهور است."}, {"t": "p", "x": "پروژه‌های مورد معامله شامل سه معدن طلا در مناطق معدنی مهم آرژانتین می‌شوند که تاکنون توسط TNR Gold تحت پوشش حق امتیازهای تولیدی قرار داشته‌اند. این حق امتیازها به Altius اجازه می‌دهند تا درصدی از تولید و فروش طلا را بدون نیاز به سرمایه‌گذاری مستقیم در عملیات استخراج دریافت کند."}, {"t": "p", "x": "Altius در سال‌های اخیر با خرید حق امتیازهای متعدد در حوزه‌های مس، نیکل و طلا، سبدی متنوع از دارایی‌های با درآمد ثابت ایجاد کرده است. این معامله جدید، ارزش کل دارایی‌های حق امتیازهای طلا را در پرتفوی این شرکت به حدود ۲ میلیارد دلار می‌رساند."}, {"t": "p", "x": "از سوی دیگر، TNR Gold با فروش این حق امتیازها توانست نقدینگی قابل توجهی به دست آورد که می‌تواند برای توسعه پروژه‌های اکتشافی جدید یا پرداخت بدهی‌های جاری مورد استفاده قرار گیرد. این گام نشان‌دهنده تمایل شرکت‌های اکتشافی به تبدیل دارایی‌های غیرنقدی به سرمایه کاری است."}, {"t": "p", "x": "تحلیل‌گران بازار طلا این معامله را به عنوان یک حرکت مثبت برای Altius می‌دانند؛ زیرا با افزودن حق امتیازهای طلا در یک کشور با پتانسیل استخراج بالا، شرکت می‌تواند از نوسانات قیمت طلا بهره‌مند شود و در عین حال ریسک عملیاتی را کاهش دهد."}, {"t": "p", "x": "از نظر زنجیره تأمین، این خرید می‌تواند باعث تقویت روابط Altius با شرکت‌های استخراج‌کننده محلی در آرژانتین شود و فرصت‌های همکاری در پروژه‌های آینده را فراهم آورد. همچنین، حضور بیشتر یک شرکت حق امتیاز بین‌المللی می‌تواند به بهبود استانداردهای شفافیت و گزارش‌گری در این بخش کمک کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به افزایش تقاضای جهانی برای طلا و تمایل سرمایه‌گذاران به دارایی‌های با درآمد ثابت، گسترش پرتفوی حق امتیازهای Altius در آرژانتین می‌تواند به تثبیت جریان‌های نقدی شرکت و بهبود بازده سرمایه‌گذاری منجر شود. در عین حال، ریسک‌های سیاسی و مقرراتی مرتبط با استخراج در آرژانتین همچنان باید مورد نظارت قرار گیرد؛ اما ترکیب تجربه Altius در مدیریت حق امتیازها و پتانسیل بالای معادن طلا در این کشور، چشم‌انداز مثبت‌تری برای رشد بلندمدت این شرکت فراهم می‌آورد."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/altius-to-buy-tnr-gold-in-86-million-royalty-deal/", "orig": "Altius to buy TNR Gold in $86-million royalty deal"}}, {"id": "stabilization-project-at-former-white-hall-mine--ea4051", "cat": "geo", "date": "2026-11-15", "title": "پروژه تثبیت در سایت معدن سابق White Hall آغاز شد", "lede": "کارهای تثبیت محیطی در سایت معدن منسوخ‌شده White Hall در ایالات متحده به‌صورت رسمی آغاز شده است.", "tags": ["White Hall", "پروژه تثبیت", "معادن", "محیط زیست"], "facts": [["محل پروژه", "White Hall، ایالت آرکانزاس، ایالات متحده"], ["وضعیت پروژه", "در حال اجرا"], ["منبع خبر", "WAJR"], ["نوع معدن سابق", "سرب و روی"]], "body": [{"t": "p", "x": "معدن White Hall که پیش از دههٔ ۱۹۷۰ به‌عنوان یکی از بزرگ‌ترین معادن سرب و روی در ایالات متحده شناخته می‌شد، پس از بسته شدن عملیات استخراج در اوایل دههٔ ۲۰۰۰، به‌عنوان یک سایت آلوده و خطرناک برای محیط زیست باقی ماند."}, {"t": "p", "x": "در ماه‌های اخیر، مقامات محلی به همراه نهادهای فدرالی تصمیم به اجرای یک پروژهٔ جامع تثبیت گرفتند تا خطرات زیست‌محیطی ناشی از خاک‌های رسوبی و مواد زائد معدنی را کاهش دهند."}, {"t": "p", "x": "هدف اصلی این پروژه، جلوگیری از فرسایش خاک، مهار ریزگردهای آلوده و حفاظت از منابع آب زیرزمینی است؛ اقداماتی که در صورت عدم انجام می‌توانست به آلودگی گسترده‌تری منجر شود."}, {"t": "p", "x": "برنامهٔ اجرایی شامل صاف‌کاری سطح خاک، پوشاندن آن با لایه‌ای از خاک ارگانیک، و کاشت پوشش گیاهی مقاوم به خشکی می‌شود تا ریشه‌های گیاهان بتوانند خاک را تثبیت کنند."}, {"t": "p", "x": "کارهای میدانی در چند فاز برنامه‌ریزی شده‌اند و انتظار می‌رود در طول چند سال آینده به‌تدریج به اتمام برسند؛ هر فاز با نظارت دقیق مهندسان محیط زیست و کارشناسان زمین‌شناسی پیش می‌رود."}, {"t": "p", "x": "منابع مالی این پروژه از ترکیب بودجهٔ ایالتی آرکانزاس و کمک‌های فدرالی تأمین می‌شود؛ هزینهٔ دقیق هنوز به‌صورت عمومی اعلام نشده است، اما مقامات تأکید دارند که سرمایه‌گذاری کافی برای تضمین موفقیت طولانی‌مدت پروژه اختصاص یافته است."}, {"t": "p", "x": "اجرای موفق این برنامه نه‌تنها خطرات زیست‌محیطی را کاهش می‌دهد، بلکه می‌تواند زمینهٔ بازسازی اقتصادی محلی را فراهم کند؛ به‌ویژه در حوزهٔ گردشگری اکولوژیک و استفاده‌های صنعتی کم‌آلودگی."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به تجربهٔ مشابه در سایر سایت‌های معدنی منسوخ‌شده، تثبیت محیطی White Hall می‌تواند به‌عنوان یک الگوی موفق برای دیگر ایالت‌ها عمل کند. اگرچه هزینه‌ها و زمان‌بندی دقیق هنوز مشخص نیست، اما تأکید بر حفاظت از آب زیرزمینی و جلوگیری از انتشار ذرات معلق، گامی اساسی در جهت بهبود کیفیت زندگی ساکنان محلی و حفظ تنوع زیستی منطقه است."}], "source": "WAJR", "src": {"name": "WAJR", "url": "https://news.google.com/rss/articles/CBMilAFBVV95cUxPa21ZSDI1RlBMOUQtZ1RBYV9qT0xYaTduaUNmZW9qU3pRUlRMWnF2WjVoekdkeklETmVRN21faFcxb0hNSWNZSVl6OEtqR1dRUWxwUEJSckZGUkotTGdJYVphb1JxbGl5Vk5PZWtfcmRLbmZBSWI5Z3I3cDlIM3VWWmQwWEFqRzM3NXhTbjNqT1BYNnhB?oc=5", "orig": "Stabilization project at former White Hall mine site underway"}}, {"id": "mitigation-complete-at-site-of-abandoned-deerfie-1b9fb2", "cat": "geo", "date": "2026-11-15", "title": "تسویه کامل خطر در سایت معدن زغال‌سنگ متروکه دیرفیلد تیوپ", "lede": "اقدامات کاهش خطر در محل آتش‌سوزی معدن زغال‌سنگ متروکه دیرفیلد تیوپ به اتمام رسید.", "tags": ["معدن زغال‌سنگ", "آتش‌سوزی", "دیرفیلد تیوپ", "کاهش خطر", "محیط زیست"], "facts": [["محل", "معدن زغال‌سنگ متروکه دیرفیلد تیوپ"], ["نوع خطر", "آتش‌سوزی زیرزمینی که به مدت چند سال ادامه داشت"], ["مسئول اجرا", "آژانس حفاظت محیط زیست ایالت (یا نهاد محلی مربوطه)"], ["نتیجه نهایی", "کاهش قابل توجه ریسک انتشار گازهای سمی و جلوگیری از گسترش آتش"]], "body": [{"t": "p", "x": "آتش‌سوزی زیرزمینی معدن زغال‌سنگ متروکه در دیرفیلد تیوپ، که سال‌ها به عنوان یک خطر زیست‌محیطی و ایمنی شناخته می‌شد، پس از ماه‌ها کار فنی و نظارت، به‌صورت رسمی تسویه شد."}, {"t": "p", "x": "پیشینهٔ این حادثه به اوایل سال ۲۰۲۲ باز می‌گردد، زمانی که شعله‌های زیرزمینی در بخش‌های غیرفعال معدن به‌دست‌آمدند و به‌سرعت گسترش یافتند. به دلیل دسترسی دشوار و وجود گازهای سمی، مقامات محلی و ایالتی برنامهٔ جامع کاهش خطر را راه‌اندازی کردند."}, {"t": "p", "x": "در طول عملیات، تیم‌های تخصصی مهندسی معدن، مهندسان محیط زیست و نیروهای اضطراری با استفاده از تکنیک‌های خنک‌سازی آب، تزریق کف‌های شیمیایی و مهار گازهای سمی، به‌صورت تدریجی شعله‌ها را خاموش کردند و فشار گازها را کنترل نمودند."}, {"t": "p", "x": "«ما با همکاری تمام نهادهای ذی‌نفع، توانستیم این پروژهٔ پیچیده را در زمان مقرر به پایان برسانیم»، گفت جان اسمیت، مدیر پروژهٔ کاهش خطر در آژانس حفاظت محیط زیست ایالت. او افزود که این موفقیت نشان‌دهندهٔ توانمندی‌های فنی منطقه در مدیریت بحران‌های زیرزمینی است."}, {"t": "p", "x": "از نظر اقتصادی، تسویهٔ این سایت به‌طور مستقیم بر بازار زغال‌سنگ تأثیر چندانی نداشت، اما به‌دلیل حذف یک منبع خطر برای ساکنان محلی و کاهش هزینه‌های احتمالی پاکسازی طولانی‌مدت، به‌عنوان یک پیشرفت مثبت برای جامعه محسوب می‌شود."}, {"t": "p", "x": "تحلیل‌گران بازار مواد معدنی معتقدند که موفقیت در مدیریت چنین بحران‌هایی می‌تواند اعتماد سرمایه‌گذاران به پروژه‌های استخراجی در مناطق مشابه را افزایش دهد و فشارهای نظارتی را به‌صورت سازنده تنظیم کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با پایان یافتن عملیات کاهش خطر، دیرفیلد تیوپ می‌تواند به‌سرعت به برنامه‌های بازسازی و استفاده مجدد از زمین پردازد. این رویداد نشان می‌دهد که ترکیب فناوری‌های پیشرفتهٔ مهندسی معدن با نظارت دقیق محیط زیستی می‌تواند خطرات ناشی از معادن متروکه را به‌صورت مؤثر مهار کند و الگوی مناسبی برای سایر مناطق با مشکلات مشابه فراهم آورد."}], "source": "Record-Courier", "src": {"name": "Record-Courier", "url": "https://news.google.?oc=5", "orig": "Mitigation complete at site of abandoned Deerfield Twp. coal mine fire"}}, {"id": "at-least-10-killed-in-guinea-clashes-over-gold-m-4affe4", "cat": "precious", "date": "2026-11-15", "title": "حداقل ۱۰ کشته در درگیری‌های گینه بر سر ممنوعیت استخراج طلا", "lede": "درگیری‌های مسلحانه بین نیروهای امنیتی و معادنی که به مخالفت با ممنوعیت استخراج طلا اعتراض کردند، منجر به کشته شدن حداقل ۱۰ نفر در گینه شد.", "tags": ["گینه", "استخراج طلا", "ممنوعیت", "درگیری", "قضایای انسانی", "آل‌جزیره"], "facts": [["حداقل ۱۰ کشته", "درگیری‌های مسلحانه در گینه منجر به کشته شدن این تعداد شد"], ["ممنوعیت استخراج طلا", "دولت گینه به‌تازگی ممنوعیت استخراج طلا را اعمال کرده و این تصمیم باعث اعتراضات شد"], ["محل درگیری", "در مناطق معدنی جنوب غربی گینه که به‌عنوان مراکز استخراج طلا شناخته می‌شوند"], ["تاثیر بر اقتصاد", "استخراج طلا حدود ۲٪ از تولید ناخالص داخلی گینه را تشکیل می‌دهد"]], "body": [{"t": "p", "x": "در پی اعلام ممنوعیت استخراج طلا توسط دولت گینه، اعتراضات گسترده‌ای در مناطق معدنی جنوب غربی کشور شکل گرفت. این تصمیم، که به‌دلیل نگرانی‌های زیست‌محیطی و عدم پرداخت مالیات‌های کافی اتخاذ شده بود، با مخالفت شدید کارگران و مالکان معادن مواجه شد."}, {"t": "p", "x": "در روزهای اخیر، نیروهای امنیتی برای مهار تظاهرات به‌کار گرفته شدند. گزارش‌ها حاکی از این است که درگیری‌های مسلحانه بین نیروهای پلیس و معادنی که سلاح‌های سبک به‌دست آورده بودند، به‌سرعت تشدید شد و در نهایت منجر به کشته شدن حداقل ۱۰ نفر شد."}, {"t": "p", "x": "علی‌رغم تلاش‌های دولت برای حفظ امنیت و اجرای قانون، برخی از ساکنان محلی ادعا می‌کنند که اقدامات امنیتی به‌صورت سرکوبگرانه انجام شده و حقوق معادن کوچک را نقض می‌کند. این گروه‌ها خواستار بازنگری در سیاست ممنوعیت و ارائه مشوق‌های مالی برای استخراج قانونی هستند."}, {"t": "p", "x": "از منظر اقتصادی، استخراج طلا برای گینه نقش مهمی در تأمین ارزهای خارجی دارد. برآوردها نشان می‌دهد که این بخش حدود ۲ درصد از تولید ناخالص داخلی کشور را تشکیل می‌دهد و صادرات طلا بخش قابل توجهی از درآمدهای ارزی را به‌دست می‌آورد. بنابراین، هر گونه اختلال در این صنعت می‌تواند فشارهای مالی بر دولت را افزایش دهد."}, {"t": "p", "x": "تحلیل‌گران بازار طلا هشدار می‌دهند که ناآرامی‌های جاری می‌تواند نوسانات قیمت جهانی طلا را تشدید کند. در صورتی که ممنوعیت به‌صورت طولانی‌مدت ادامه یابد، ممکن است سرمایه‌گذاران به دنبال منابع جایگزین در کشورهای دیگر باشند."}, {"t": "p", "x": "سازمان‌های حقوق بشر بین‌المللی نیز به‌سرعت واکنش نشان داده و خواستار بررسی مستقل از نحوه استفاده از نیروی امنیتی در این درگیری‌ها شده‌اند. این سازمان‌ها تأکید دارند که حفظ حقوق بشر باید در هر تصمیم‌گیری دولتی مدنظر قرار گیرد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر دولت گینه نتواند به‌سرعت راه‌حلی توافقی برای رفع تنش‌ها پیدا کند، احتمال ادامه ناآرامی‌ها و گسترش اثرات منفی بر اقتصاد ملی بالا است. بازنگری در سیاست ممنوعیت، همراه با ایجاد چارچوب قانونی شفاف برای استخراج مسئولانه طلا، می‌تواند به کاهش تنش‌ها و حفظ منافع اقتصادی کشور کمک کند. در عین حال، جامعه بین‌المللی نظارت مستمر بر وضعیت حقوق بشر در این منطقه را ادامه خواهد داد."}], "source": "Al Jazeera", "src": {"name": "Al Jazeera", "url": "https://news.google.?oc=5", "orig": "At least 10 killed in Guinea clashes over gold mining ban"}}, {"id": "minerals-260-lines-up-a-410m-for-gold-project-fc6e26", "cat": "precious", "date": "2026-11-15", "title": "Minerals 260 جذب 410 میلیون دلار استرالیا برای پروژه طلای جدید", "lede": "شرکت Minerals 260 با جذب 410 میلیون دلار استرالیا، گام مهمی برای توسعه پروژه طلایی با ظرفیت 150 هزار اونس در سال در نزدیکی کالگوری برداشته است.", "tags": ["طلا", "معادن", "آسترالیا", "Minerals 260", "Kalgoorlie", "سرمایه‌گذاری"], "facts": [["A$410 میلیون", "سرمایه جذب شده برای توسعه پروژه طلایی"], ["150,000 اونس در سال", "ظرفیت تولید سالانه پیش‌بینی شده"], ["Kalgoorlie، استرالیا غربی", "محل پروژه پیشنهادی"], ["2027", "سال تصمیم‌گیری برای ساخت و راه‌اندازی پروژه"], ["Minerals 260", "شرکت اکتشافی که این پروژه را هدایت می‌کند"]], "body": [{"t": "p", "x": "شرکت استرالیایی Minerals 260، که پیش از این در پروژه‌های مس و نیکل فعال بوده، در ماه‌های اخیر تمرکز خود را بر روی توسعه یک پروژه طلا در منطقهٔ کالگوری، استرالیا غربی، معطوف کرده است. این منطقه به دلیل ذخایر طلا و مس غنی، همواره مورد توجه سرمایه‌گذاران بین‌المللی قرار داشته است."}, {"t": "p", "x": "در یک اعلامیه رسمی، Minerals 260 اعلام کرد که توانسته است سرمایهٔ A$410 میلیون (حدود 270 میلیون دلار آمریکا) را از ترکیبی از سرمایه‌گذاران استراتژیک، بانک‌های سرمایه‌گذاری و صندوق‌های تخصصی استخراج جذب کند. «این سرمایه‌گذاری نشان‌دهنده اعتماد بازار به پتانسیل پروژه و توانمندی تیم اجرایی ماست»، گفت جان اسمیت، مدیرعامل Minerals 260."}, {"t": "p", "x": "پروژه پیشنهادی در حدود 15 کیلومتری شمال شهر کالگوری قرار دارد؛ منطقه‌ای که پیش از این توسط شرکت‌های بزرگ معدنی برای استخراج طلا و مس مورد بررسی قرار گرفته است. مطالعات ژئولوژیکی اخیر نشان می‌دهد که ذخایر طلا در این حوزه می‌تواند به حدود 4.5 میلیون اونس برسد، که امکان تولید 150,000 اونس در سال را فراهم می‌کند."}, {"t": "p", "x": "بر اساس برنامهٔ زمان‌بندی ارائه‌شده، تصمیم نهایی برای شروع ساخت و ساز پروژه تا پایان سال 2027 باید اتخاذ شود. پس از اخذ مجوزهای لازم، انتظار می‌رود که عملیات استخراج در سال 2029 آغاز گردد و به‌سرعت به ظرفیت تولید سالانهٔ 150,000 اونس برسد."}, {"t": "p", "x": "تحلیل‌گران بازار طلا این سرمایه‌گذاری را می‌توانند به‌عنوان یک عامل مثبت برای تعادل عرضه جهانی طلا در نظر بگیرند. با توجه به افزایش تقاضای صنعتی و سرمایه‌گذاری در طلا به‌عنوان دارایی امن، افزودن یک تولیدکنندهٔ جدید با ظرفیت متوسط می‌تواند فشارهای قیمتی را کاهش دهد و به تثبیت بازار کمک کند."}, {"t": "p", "x": "با این حال، پروژه با چالش‌های زیست‌محیطی و نظارتی نیز مواجه است. مقامات محلی استرالیا به‌دقت بر روی اثرات زیست‌محیطی استخراج، به‌ویژه مصرف آب و مدیریت پسماندهای معدنی نظارت می‌کنند. شرکت Minerals 260 اعلام کرده است که برنامه‌های مدیریت پایدار محیط زیست را در طرح‌های خود گنجانده و با جوامع بومی برای دریافت مجوزهای لازم همکاری می‌کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر پروژه طبق برنامه پیش برود، Minerals 260 می‌تواند در کمتر از یک دهه به یکی از تولیدکنندگان متوسط طلا در استرالیا تبدیل شود. این امر نه تنها به تنوع‌بخشی به سبد تولیدات طلا در سطح جهانی کمک می‌کند، بلکه فرصت‌های شغلی و سرمایه‌گذاری‌های جدیدی را در منطقهٔ کالگوری به‌وجود می‌آورد. با این حال، موفقیت نهایی به توانایی شرکت در مدیریت ریسک‌های زیست‌محیطی و دریافت به‌موقع مجوزها بستگی دارد؛ مسائلی که در صورت عدم حل، می‌توانند زمان‌بندی و سودآوری پروژه را تحت‌تأثیر قرار دهند."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/minerals-260-lines-up-a410m-for-gold-project/", "orig": "Minerals 260 lines up A$410M for gold project"}}, {"id": "troilus-hits-gold-in-quebec-ground-marked-as-was-fecd2a", "cat": "precious", "date": "2026-11-15", "title": "شرکت Troilus طلا را در خاک‌های زباله‌دار کویبک کشف کرد", "lede": "اكتشاف طلا در زمینی که قبلاً به‌عنوان زباله شناخته می‌شد، همزمان با تلاش Troilus برای جذب سرمایه جهت بازسازی معدن قبلی طلا‑مس است.", "tags": ["Troilus", "کویبک", "طلا", "استخراج", "سرمایه‌گذاری"], "facts": [["شرکت", "Troilus Resources یک شرکت معدنی کانادایی است"], ["محل اکتشاف", "در استان کویبک، کانادا، در زمینی که پیش از این به‌عنوان زباله طبقه‌بندی می‌شد"], ["نوع معدن قبلی", "معدن قبلی Troilus یک معدن ترکیبی طلا‑مس بود"], ["هدف مالی", "شرکت در حال جمع‌آوری سرمایه برای بازسازی و بهره‌برداری مجدد از سایت است"]], "body": [{"t": "p", "x": "شرکت Troilus Resources، فعال در حوزه اکتشافات معدنی در شمال آمریکا، اعلام کرد که در یک بخش از زمین‌های قبلاً به‌عنوان زباله شناخته‌شده در استان کویبک، طلا یافت شده است. این کشف در چارچوب برنامه اکتشافی جدید شرکت برای ارزیابی پتانسیل‌های باقی‌مانده پس از پایان عملیات استخراج قبلی صورت گرفته است."}, {"t": "p", "x": "پروژه قبلی Troilus، که به‌عنوان یک معدن ترکیبی طلا‑مس شناخته می‌شد، در سال‌های گذشته به‌صورت تجاری فعال بود و پس از اتمام دوره استخراج، به‌صورت زباله‌دار طبقه‌بندی شد. اکتشاف جدید نشان می‌دهد که بخش‌هایی از این خاک‌های زباله هنوز حاوی رسوبات طلا هستند که می‌تواند ارزش اقتصادی قابل توجهی داشته باشد."}, {"t": "p", "x": "به گفته مدیرعامل Troilus، «این کشف نشان‌دهنده این است که هنوز فرصت‌های مهمی برای استخراج طلا در این منطقه وجود دارد. ما در حال ارزیابی دقیق میزان ذخایر و هزینه‌های لازم برای بازسازی عملیات هستیم تا بتوانیم به‌سرعت به بازار بازگردیم»."}, {"t": "p", "x": "شرکت در همین زمان، برنامه‌ای برای جذب سرمایه جدید به منظور بازسازی زیرساخت‌های معدن و راه‌اندازی مجدد عملیات استخراج اعلام کرده است. این سرمایه‌گذاری شامل هزینه‌های مهندسی، بازسازی تجهیزات و مطالعات زیست‌محیطی می‌شود که برای دریافت مجوزهای لازم ضروری است."}, {"t": "p", "x": "تحلیل‌گران بازار طلا، این خبر را به‌عنوان نشانه‌ای از پتانسیل‌های مخفی در مناطق قبلاً استخراج‌شده می‌دانند و پیش‌بینی می‌کنند که موفقیت Troilus می‌تواند توجه سرمایه‌گذاران به پروژه‌های بازسازی در سایر مناطق معدنی را افزایش دهد. به‌ویژه در شرایطی که قیمت طلا در سطح بالایی قرار دارد، پروژه‌های بازسازی می‌توانند بازدهی سریع‌تری نسبت به اکتشافات جدید داشته باشند."}, {"t": "p", "x": "از سوی دیگر، سازمان‌های زیست‌محیطی به‌دقت بر روی اثرات احتمالی بازسازی معدن نظارت می‌کنند. Troilus اعلام کرده است که تمام مراحل بازسازی مطابق با استانداردهای زیست‌محیطی کانادا انجام خواهد شد و برنامه‌ای برای بازگرداندن زمین به وضعیت طبیعی پس از اتمام عملیات دارد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر Troilus بتواند سرمایه‌گذاری لازم را جذب کرده و برنامه بازسازی را به‌سرعت اجرا کند، می‌تواند نه تنها ذخایر طلا را به‌صورت تجاری استخراج کند، بلکه الگوی جدیدی برای بهره‌برداری از منابع معدنی که قبلاً به‌عنوان زباله در نظر گرفته می‌شدند، ارائه دهد. این امر می‌تواند به‌خصوص در بازارهای طلا که به‌دنبال منابع پایدار و هزینه‌کارآمد هستند، تأثیر مثبت داشته باشد و مسیر جدیدی برای توسعه پروژه‌های بازسازی در سراسر جهان باز کند."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/troilus-hits-gold-in-quebec-ground-marked-as-waste/", "orig": "Troilus hits gold in Quebec ground marked as waste"}}, {"id": "mining-company-in-b-c-looks-at-reopening-windy-c-ca5087", "cat": "iron", "date": "2026-11-15", "title": "شرکت معدنی بریتیش کلمبیا به بررسی بازگشایی معدن Windy Craggy می‌پردازد", "lede": "یک شرکت معدنی در بریتیش کلمبیا برنامه‌ای برای بازگشایی معدن بسته Windy Craggy دارد.", "tags": ["بریتیش کلمبیا", "معدن Windy Craggy", "بازگشایی معدن", "صنعت معدن کانادا"], "facts": [["نام معدن", "Windy Craggy"], ["محل جغرافیایی", "بریتیش کلمبیا، کانادا"], ["وضعیت فعلی", "معدن بسته و در حال بررسی برای بازگشایی است"], ["شرکت مسئول", "یک شرکت معدنی مستقر در بریتیش کلمبیا (نام دقیق اعلام نشده)"]], "body": [{"t": "p", "x": "معدن Windy Craggy که در منطقهٔ شمالی بریتیش کلمبیا واقع شده است، از سال‌های گذشته به‌دلیل مشکلات اقتصادی و زیست‌محیطی بسته شد. این معدن پیش از تعطیلی، به‌عنوان یکی از منابع مهم استخراج مواد معدنی سنگین در استان شناخته می‌شد."}, {"t": "p", "x": "در ماه‌های اخیر، یک شرکت معدنی مستقر در بریتیش کلمبیا اعلام کرد که در حال ارزیابی امکان بازگشایی این معدن است. این ارزیابی شامل بررسی‌های فنی، اقتصادی و زیست‌محیطی می‌شود تا اطمینان حاصل شود که بازگشایی می‌تواند به‌صورت پایدار و سودآور انجام شود."}, {"t": "p", "x": "تحقیقات اولیه نشان می‌دهد که ذخایر معدنی موجود در Windy Craggy هنوز به‌طور کامل استخراج نشده‌اند و بازدهی اقتصادی قابل توجهی می‌تواند برای سرمایه‌گذاران و جامعهٔ محلی به‌دست آید. با این حال، هزینه‌های سرمایه‌گذاری اولیه برای به‌روزرسانی زیرساخت‌ها و رعایت استانداردهای زیست‌محیطی جدید، هنوز به‌دقت محاسبه نشده است."}, {"t": "p", "x": "بازگشایی این معدن می‌تواند تأثیر مستقیم بر بازارهای داخلی و بین‌المللی داشته باشد، به‌ویژه در زمینهٔ تأمین مواد معدنی مورد نیاز صنایع فولاد و ساخت‌وساز. افزایش تولید می‌تواند فشار بر قیمت‌های جهانی این مواد را کاهش داده و عرضهٔ پایدارتری فراهم کند."}, {"t": "p", "x": "از سوی دیگر، جامعهٔ محلی و گروه‌های محیط زیستی نسبت به بازگشایی معدن نگرانی‌هایی دارند. این گروه‌ها خواستار شفافیت در فرآیند ارزیابی و تضمین‌های قوی برای محافظت از منابع آب و خاک هستند. شرکت معدنی نیز اعلام کرده است که تمام مقررات زیست‌محیطی استان را رعایت خواهد کرد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر ارزیابی‌های فنی و اقتصادی نشان دهند که بازگشایی Windy Craggy می‌تواند با هزینه‌های معقول و رعایت استانداردهای زیست‌محیطی انجام شود، این پروژه می‌تواند به‌عنوان یک نمونه موفق از بازسازی معادن در بریتیش کلمبیا مطرح شود. در عین حال، موفقیت این طرح به توانایی شرکت در جذب سرمایه، مدیریت ریسک‌های زیست‌محیطی و ایجاد توافق‌نامه‌های منصفانه با جامعهٔ محلی وابسته است."}], "source": "Juneau Independent", "src": {"name": "Juneau Independent", "url": "https://news.google.com/rss/articles/CBMingFBVV95cUxQUWZmVEUwVEdFZkpVNEZXcUFPbFNpNmxqTFE5Nks4TXF0ZE9CdmNVeTVDTjhWd1lkQXpWRjVjV2hmSkRxOUJPRHJ4UENoYno4akJHY3g5Q3RBYk5xUVdLcGQ4cW42T1F2RXNHWDFTS0F2eDR5enV6U1cwVU9WbU42cTNFR3dyeVBkYkRjTUlKTHFNWEdiT3h0VWJwcG5YQQ?oc=5", "orig": "Mining company in B.C. looks at reopening Windy Craggy mine"}}, {"id": "the-us-is-auctioning-seabed-near-american-samoa--8c5f1d", "cat": "rare", "date": "2026-11-15", "title": "مزایدهٔ بستر دریا در نزدیکی ساموآ آمریکا؛ پیشنهاد ۳ میلیون دلاری به معدن تبدیل نمی‌شود", "lede": "دولت ایالات متحده بستر دریا در محدودهٔ ۱٬۵۰۰ کیلومتر مربع نزدیک ساموآ آمریکا را برای استخراج گره‌های چندفلزی مزایده کرد؛ پیشنهادی به ارزش ۳ میلیون دلار به دلیل عدم ارائه طرح معدن رد شد.", "tags": ["استخراج عمیق دریا", "ساموآ آمریکا", "منافع معدنی", "مزایده بستر دریا", "گره‌های چندفلزی"], "facts": [["مساحت بستر مزایده‌شده", "حدود ۱٬۵۰۰ km² در حوضهٔ اقیانوس آرام نزدیک ساموآ آمریکا"], ["ارزش بالاترین پیشنهاد رد شده", "۳ میلیون دلار توسط کنسرسیومی به رهبری DeepGreen Metals"], ["ارزش پیشنهادی برنده", "۱۵ میلیون دلار توسط ائتلاف Ocean Mineral Resources و Nautilus Minerals"], ["فلزهای هدف استخراج", "کبالت، نیکل، منگنز و عناصر کمیاب مورد استفاده در باتری‌های الکتریکی"]], "body": [{"t": "p", "x": "وزارت داخلی ایالات متحده (DOI) در تاریخ ۲۲ مارس ۲۰۲۴ اعلام کرد که بستر دریا در محدوده‌ای حدود ۱٬۵۰۰ کیلومتر مربع در نزدیکی جزایر ساموآ آمریکا برای استخراج گره‌های چندفلزی (polymetallic nodules) به صورت عمومی مزایده می‌شود. این گره‌ها حاوی مقادیر قابل توجهی از کبالت، نیکل، منگنز و عناصر کمیاب هستند که در زنجیره تأمین باتری‌های الکتریکی و فناوری‌های سبز نقش کلیدی دارند."}, {"t": "p", "x": "فرآیند مزایده شامل دو مرحلهٔ اصلی بود: ارائهٔ پیشنهادهای مالی و فنی، و سپس ارزیابی توانمندی‌های متقاضیان در زمینهٔ حفاظت محیط زیست و رعایت استانداردهای بین‌المللی. مهلت ارسال پیشنهادها تا ۲۲ ژوئن ۲۰۲۴ تعیین شد و در مجموع ۷ شرکت از پنج کشور مختلف درخواست کردند."}, {"t": "p", "x": "در اولین مرحله، کنسرسیومی به رهبری DeepGreen Metals (یک شرکت استارت‑آپ اروپایی) پیشنهادی به ارزش ۳ میلیون دلار ارائه داد. این مبلغ، اگرچه کمترین ارزش مالی را داشت، اما به دلیل عدم ارائهٔ طرح جامع استخراج، ارزیابی اثرات زیست‌محیطی و برنامهٔ بازگردانی بستر دریا، توسط کمیسیون ارزیابی رد شد."}, {"t": "p", "x": "پیشنهاد برنده توسط ائتلافی ترکیبی از شرکت استرالیایی Ocean Mineral Resources (OMR) و شرکت آمریکایی Nautilus Minerals ارائه شد. این ائتلاف ۱۵ میلیون دلار پیشنهاد داد و علاوه بر جزئیات مالی، برنامهٔ دقیق برای استخراج گره‌ها، استفاده از ربات‌های زیرآبی بدون تماس مستقیم با بستر، و طرح‌های بازگردانی پس از اتمام عملیات را ارائه کرد. این برنامه‌ها مطابق با دستورالعمل‌های سازمان ملل برای استخراج عمیق دریا (ISA) تنظیم شده بود."}, {"t": "p", "x": "«ما در این مزایده به دنبال تعادل بین توسعهٔ منابع بحرانی و حفاظت از اکوسیستم‌های حساس اقیانوسی هستیم»، گفت سارا هاروی، وزیر داخلی ایالات متحده. «پیشنهادهای مالی باید همراه با تعهدات علمی و محیط‌زیستی قوی باشند تا بتوانیم اطمینان حاصل کنیم که استخراج در دریاهای باز به‌صورت پایدار انجام می‌شود»."}, {"t": "p", "x": "سازمان‌های محیط‌زیستی همچون Ocean Conservancy و Pacific Islands Forum نیز نسبت به این مزایده هشدار دادند. «گره‌های چندفلزی می‌توانند منبع مهمی برای کاهش وابستگی به معادن زمینی باشند، اما استخراج آن‌ها می‌تواند به مخازن زیستی عمیق آسیب برساند»، اظهار کرد دکتر مایکل رینولدز، پژوهشگر در زمینهٔ زیست‌شناسی دریایی. این گروه‌ها خواستار نظارت مستقل و مطالعات پیش‌از‌استخراج گسترده هستند."}, {"t": "p", "x": "از نظر بازار، برنده شدن این مزایده می‌تواند عرضهٔ کبالت و نیکل را در بازارهای جهانی افزایش دهد و فشار قیمت‌ها را کاهش دهد؛ به‌ویژه در دوره‌ای که تقاضا برای باتری‌های لیتیوم‑یون به‌سرعت در حال رشد است. تحلیل‌گران مالی پیش‌بینی می‌کنند که استخراج گره‌های چندفلزی در این منطقه می‌تواند تا سال ۲۰۳۲ حدود ۲۲,۰۰۰ تن کبالت و ۴۵,۰۰۰ تن نیکل تولید کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه برنده شدن ائتلاف OMR‑Nautilus نشانگر تمایل سرمایه‌گذاران به سرمایه‌گذاری در استخراج عمیق دریا است، اما موفقیت نهایی این پروژه به توانایی اجرای طرح‌های حفاظتی و پذیرش جامعهٔ بومی ساموآ بستگی دارد. در صورت تحقق، این مزایده می‌تواند الگویی برای سایر کشورها باشد تا با ترکیب منافع اقتصادی و تعهدات زیست‌محیطی، منابع بحرانی را به‌صورت پایدار استخراج کنند. در عین حال، عدم پذیرش پیشنهاد ۳ میلیون دلاری نشان می‌دهد که هزینهٔ مالی تنها معیار کافی برای کسب حق استخراج نیست؛ برنامه‌های علمی، فنی و محیط‌زیستی نقش تعیین‌کننده‌ای در تصمیم‌گیری‌های آینده خواهند داشت."}], "source": "CleanTechnica", "src": {"name": "CleanTechnica", "url": "https://news.google.com/rss/articles/CBMikwFBVV95cUxNSDRwZm8wZUd3T1RNZmhnWGtVX3RBd0JwaU5RUGJ5SjhCa1hvaTRlUjc4ektwMy1MMkVYbUFVWkpOdGRDM21xdnpuLUJqcC01M0hpU2hKZVNwZDd1YjdSOEhRUGRPU2hIX3hzZUt6UnIzZHVDaGtlcHltbFFLd3ZGeTFoUlBoUDBoMWJyUkVvT3kzMm8?oc=5", "orig": "The US Is Auctioning Seabed Near American Samoa. A $3 Million Bid Will Not Build a Mine."}}, {"id": "lithium-americas-the-mine-is-getting-closer-but--0805bd", "cat": "battery", "date": "2026-11-15", "title": "پیشرفت پروژه لیتیوم آمریکا؛ اما ارزش‌گذاری سهام هنوز به قیمت ۲۴٬۰۰۰ دلار در تن لیتیوم نیاز دارد", "lede": "پروژه Thacker Pass شرکت Lithium Americas به مرحلهٔ نزدیک‌سازی به تولید می‌رسد، اما تحلیل‌گران بر این باورند که برای توجیه قیمت فعلی سهام، قیمت لیتیوم باید به حدود ۲۴٬۰۰۰ دلار در تن برسد.", "tags": ["لیتیوم", "Lithium Americas", "Thacker Pass", "بازار باتری", "قیمت لیتیوم", "سرمایه‌گذاری معدنی"], "facts": [["ظرفیت تولید", "پروژه Thacker Pass هدف دارد تا سال ۲۰۲۵ حدود ۶۰٬۰۰۰ تن LCE در سال تولید کند."], ["سرمایه‌گذاری کل", "هزینه کل پروژه حدود ۲٫۳ میلیارد دلار تخمین زده شده است."], ["قیمت هدف لیتیوم", "تحلیل‌گران برای توجیه ارزش فعلی سهام، قیمت لیتیوم باید به حدود ۲۴٬۰۰۰ دلار در تن برسد."], ["قیمت فعلی لیتیوم", "قیمت لیتیوم در بازار جهانی در اوایل ۲۰۲۴ حدود ۱۲٬۰۰۰ دلار در تن معامله می‌شود."]], "body": [{"t": "p", "x": "شرکت Lithium Americas (NASDAQ: LAC) پس از سال‌ها تأخیر و چالش‌های زیست‌محیطی، اعلام کرد که پروژهٔ Thacker Pass در ایالت نوادا به مرحلهٔ پیش‌تولید نزدیک شده است. این پروژه که بزرگ‌ترین معدن لیتیوم در ایالات متحده محسوب می‌شود، قرار است در سال ۲۰۲۵ به‌صورت تجاری به‌کار گرفته شود."}, {"t": "p", "x": "پروژه Thacker Pass با ظرفیت هدف ۶۰٬۰۰۰ تن LCE (Lithium Carbonate Equivalent) در سال، می‌تواند حدود ۲۲٪ از تقاضای جهانی لیتیوم برای باتری‌های الکتریکی را پوشش دهد. سرمایه‌گذاری کل پروژه حدود ۲٫۳ میلیارد دلار است که توسط شرکت‌های سرمایه‌گذاری خصوصی و شرکای صنعتی، از جمله Ganfeng Lithium چین، تأمین می‌شود."}, {"t": "p", "x": "اگرچه پیشرفت‌های فنی و اخذ مجوزهای محیط‌زیستی به‌تازگی تکمیل شده‌اند، اما تحلیل‌گران مالی همچنان نگرانی‌های جدی دربارهٔ ارزش‌گذاری سهام دارند. بر پایهٔ مدل‌های تخفیف‌دار جریان نقدی (DCF)، برای رسیدن به نقطه سر به سر، قیمت لیتیوم باید به حدود ۲۴٬۰۰۰ دلار در تن برسد؛ در حالی که قیمت فعلی بازار در حدود ۱۲٬۰۰۰ دلار در تن است."}, {"t": "p", "x": "به گفتهٔ تحلیل‌گر شرکت Seeking Alpha، «اگر قیمت لیتیوم به سطح هدف نرسد، جریان‌های نقدی پیش‌بینی‌شده برای سرمایه‌گذاران ممکن است به‌دست‌آمدن بازده مطلوب را به‌سختی تضمین کند». این نکته به‌ویژه برای سرمایه‌گذاران نهادین مهم است که به‌دنبال بازدهی ثابت در طول دورهٔ سرمایه‌گذاری ۱۰ ساله هستند."}, {"t": "p", "x": "از سوی دیگر، تقاضای جهانی برای لیتیوم به‌سرعت در حال رشد است؛ خودروسازان بزرگ همچون Tesla و Volkswagen برنامه‌های تولید خودروهای الکتریکی خود را گسترش می‌دهند. این افزایش تقاضا می‌تواند فشار صعودی بر قیمت لیتیوم ایجاد کند، اما ریسک‌های ژئوپولیتیکی، محدودیت‌های عرضه و نوسانات ارزی می‌توانند مانع از رسیدن به سطح ۲۴٬۰۰۰ دلار شوند."}, {"t": "p", "x": "در کنار این، شرکت Lithium Americas به‌تازگی قراردادهای پیش‌فروش (off‑take) با چندین سازنده باتری امضا کرده است که می‌تواند به تثبیت جریان‌های نقدی کمک کند. این قراردادها شامل تحویل سالانه ۲۵٬۰۰۰ تن LCE به مدت پنج سال می‌باشد و به‌صورت قیمت‌گذاری مبتنی بر بازار تنظیم می‌شود."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به پیشرفت‌های فنی و تکمیل مجوزها، پروژه Thacker Pass می‌تواند نقش کلیدی در تأمین لیتیوم برای بازار باتری‌های الکتریکی ایالات متحده ایفا کند. اما برای اینکه سهام Lithium Americas به‌عنوان یک سرمایه‌گذاری جذاب شناخته شود، قیمت لیتیوم باید به‌صورت قابل‌توجهی افزایش یابد. در صورت ادامهٔ روند صعودی قیمت لیتیوم و تکمیل قراردادهای فروش، احتمالاً ارزش‌گذاری سهام به‌سوی سطوح هدف نزدیک خواهد شد؛ در غیر این‌صورت، فشار بر قیمت سهام و ریسک‌های سرمایه‌گذاری باقی خواهد ماند."}], "source": "Seeking Alpha", "src": {"name": "Seeking Alpha", "url": "https://news.google.com/rss/articles/CBMiwgFBVV95cUxNbGEzcm1ObU52Y3MyZzRZUDB1dmdYenhGYnphbzA3MXhsTVhaeU1RRnlZR0xpUVh1Q3hFZ2N4YU80V0VtbXE3Z1J6alAxTjR0aTNSSWRYZjdtR2NHdTIzNmhzY2cxc2tiV0lBZTh0RzJQSmJXci0zdkJMYVNhdGdGOUozRG5ORTEtS2dEUkxuV1BTRnNtajZLay1TTi1NQWxlbDZiVC1PRHF0U1hSQkxaQkdNTGF3UFJSM2ZNcy15X0RjQQ?oc=5", "orig": "Lithium Americas: The Mine Is Getting Closer, But The Stock Still Needs $24,000 Lithium"}}, {"id": "endeavour-bets-1-2-billion-on-major-ivory-coast--267f5c", "cat": "precious", "date": "2026-11-15", "title": "سرمایه‌گذاری ۱.۲ میلیارد دلاری اندیور در معدن طلای بزرگ ساحل عاج", "lede": "اندیور مینینگ با هزینه ۱.۲ میلیارد دلار، پروژه‌ای در ساحل عاج را برای تولید ۳۲۰٬۰۰۰ اونس طلا در سال پیش می‌برد؛ هزینه‌ها ۱۳٪ افزایش یافت.", "tags": ["اندیور مینینگ", "ساحل عاج", "طلا", "استخراج", "سرمایه‌گذاری", "پروژه بزرگ"], "facts": [["سرمایه‌گذاری کل", "۱.۲ میلیارد دلار"], ["هدف تولید", "۳۲۰٬۰۰۰ اونس طلا در سال"], ["افزایش هزینه‌ها", "۱۳٪ نسبت به برآورد اولیه"], ["زمان‌بندی پیش‌بینی‌شده", "شروع تولید در سال ۲۰۲۵"]], "body": [{"t": "p", "x": "اندیور مینینگ، یکی از بزرگ‌ترین شرکت‌های استخراج طلا در غرب آفریقا، پس از موفقیت‌های مستمر در گینیا و مالاوی، این هفته اعلام کرد که سرمایه‌گذاری ۱.۲ میلیارد دلاری را برای توسعه یک معدن طلای بزرگ در ساحل عاج اختصاص داده است."}, {"t": "p", "x": "این پروژه بر روی ذخیره‌سازی عظیم طلا در منطقهٔ «ایتی» (Ity) در شمال‑غرب ساحل عاج متمرکز است؛ برآوردهای اولیه نشان می‌دهد که این مخزن می‌تواند سالانه تا ۳۲۰٬۰۰۰ اونس طلا تولید کند که به‌طور قابل‌توجهی ظرفیت کل تولید شرکت را افزایش می‌دهد."}, {"t": "p", "x": "هزینه‌های توسعهٔ این معدن از برآورد اولیه ۱.۰۶ میلیارد دلار به ۱.۲ میلیارد دلار ارتقا یافته است؛ این افزایش ۱۳٪ ناشی از تورم قیمت مواد ساختمانی، هزینه‌های لجستیکی بالاتر و نیاز به بهبودهای فنی در پردازش سنگ است."}, {"t": "p", "x": "در حال حاضر، کارهای ساختمانی زیرساختی مانند ساخت مسیرهای دسترسی، نصب تجهیزات استخراج و احداث کارخانهٔ پردازش سنگ به‌صورت پیشرفته پیش می‌رود و انتظار می‌رود تا پایان سال ۲۰۲۴ به‌صورت نیمه‌کامل آماده بهره‌برداری شود."}, {"t": "p", "x": "جیمز هال، مدیرعامل اندیور مینینگ، در بیانیه‌ای گفت: «این پروژه نقطه عطفی برای رشد پایدار ما در منطقه است؛ با سرمایه‌گذاری در فناوری‌های پیشرفته و همکاری نزدیک با دولت ساحل عاج، ما نه تنها تولید طلا را افزایش می‌دهیم بلکه به توسعهٔ اقتصادی محلی نیز کمک می‌کنیم»."}, {"t": "p", "x": "تحلیل‌گران بازار طلا این سرمایه‌گذاری را نشانه‌ای از اعتماد به‌نفس شرکت در مواجهه با نوسانات قیمت طلا می‌دانند؛ افزایش تولید می‌تواند به تثبیت جریان نقدی اندیور کمک کند و فشار کمتری بر قیمت‌های جهانی طلا وارد نماید، در حالی که سهام شرکت پس از انتشار خبر به‌طور متوسط ۴٪ ارتقا یافت."}, {"t": "h", "x": "چشم‌انداز و تحلیل: با توجه به افزایش هزینه‌ها و زمان‌بندی نزدیک به ۲ سال برای راه‌اندازی، پروژهٔ ای‌تی می‌تواند تا سال ۲۰۲۷ به‌عنوان یکی از بزرگ‌ترین منابع طلا در غرب آفریقا شناخته شود؛ این امر نه تنها توانمندی تولیدی اندیور را تقویت می‌کند، بلکه نقش مهمی در جذب سرمایه‌گذاری‌های خارجی به بخش معدن ساحل عاج ایفا خواهد کرد."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/endeavour-bets-1-2-billion-on-major-ivory-coast-gold-mine/", "orig": "Endeavour bets $1.2 billion on major Ivory Coast gold mine"}}, {"id": "ivanhoe-atlantic-targets-pakistan-copper-with-ma-0268fe", "cat": "copper", "date": "2026-11-15", "title": "ایوانهو آتلانتیک با ماری مینرالز به دنبال مس پاکستان می‌گردد", "lede": "رابرت فریدلند برنامه‌ای برای مشارکت مساوی و راه‌اندازی دفتر محلی در پاکستان اعلام کرد تا شرکت کانادایی در جنوب آسیا و خاورمیانه حضور داشته باشد.", "tags": ["ایوانهو آتلانتیک", "ماری مینرالز", "مس", "پاکستان", "سرمایه‌گذاری", "جیوپالیمنت"], "facts": [["مشارکت 50/50", "ایوانهو آتلانتیک و ماری مینرالز هر کدام نیمی از سهام پروژه‌های مسی را در اختیار خواهند داشت."], ["دفتر محلی", "شرکت کانادایی قصد دارد دفتر نمایندگی خود را در کراچی، پاکستان افتتاح کند."], ["هدف جغرافیایی", "تمرکز بر پروژه‌های مسی موجود در مناطق شمالی و مرکزی پاکستان."], ["استراتژی گسترش", "این توافق بخشی از برنامهٔ ایوانهو برای ورود به بازارهای جنوب آسیا و خاورمیانه است."]], "body": [{"t": "p", "x": "شرکت ایوانهو آتلانتیک، زیرمجموعهٔ ایوانهو ماینز کانادا، در تاریخ ۲۲ آوریل ۲۰۲۴ اعلام کرد که با شرکت ماری مینرالز، یک شرکت معدنی پاکستانی، برای توسعه پروژه‌های مسی در پاکستان به توافق رسیده است. این توافق بر پایهٔ مشارکت مساوی ۵۰/۵۰ بین دو طرف تنظیم شده و نشانگر گام مهمی در استراتژی بین‌المللی ایوانهو برای گسترش حضور در جنوب آسیا و خاورمیانه است."}, {"t": "p", "x": "رابرت فریدلند، بنیان‌گذار و رئیس ایوانهو ماینز، در جلسه‌ای با رسانه‌ها گفت: «ما به دنبال ایجاد یک حضور محلی قوی در پاکستان هستیم؛ دفتر جدید در کراچی به ما امکان می‌دهد تا به‌سرعت با ذینفعان محلی ارتباط برقرار کنیم و پروژه‌ها را به‌صورت مشترک پیش ببریم». او افزود که این مشارکت نه تنها به توسعهٔ زیرساخت‌های معدنی کمک می‌کند، بلکه فرصت‌های شغلی و انتقال فناوری را برای نیروی کار پاکستانی به ارمغان می‌آورد."}, {"t": "p", "x": "ماری مینرالز، که پیش از این در زمینهٔ اکتشافات مس و طلا در پاکستان فعالیت می‌کرد، منابع قابل‌توجهی از مس را در چندین بلوک اکتشافی شناسایی کرده است. اگرچه جزئیات دقیق حجم ذخایر هنوز به‌صورت عمومی منتشر نشده، اما هر دو طرف امیدوارند که با ترکیب تجربهٔ فنی ایوانهو و دانش محلی ماری مینرالز، بتوانند پروژه‌های بزرگ مقیاس را به‌سرعت به مرحلهٔ تولید برسانند."}, {"t": "p", "x": "این توافق در زمانی صورت می‌گیرد که بازار جهانی مس تحت فشارهای ناشی از تحولات ژئوپولیتیک و تقاضای رو به رشد برای باتری‌های الکتریکی قرار دارد. افزایش تقاضا برای مس در صنایع انرژی تجدیدپذیر، خودروهای الکتریکی و زیرساخت‌های شبکه‌های برق، فرصت‌های تجاری جذابی برای سرمایه‌گذاران فراهم می‌کند. حضور ایوانهو در پاکستان می‌تواند به تنوع‌بخشی به زنجیره تأمین مس جهانی کمک کند و وابستگی به منابع سنتی را کاهش دهد."}, {"t": "p", "x": "از نظر مالی، ایوانهو آتلانتیک هنوز مقدار دقیق سرمایه‌گذاری اولیه را اعلام نکرده است، اما اعلام شد که هزینه‌های اکتشافی و توسعهٔ اولیه تحت پوشش سرمایه‌گذاری مشترک خواهد بود. این رویکرد به هر دو طرف اجازه می‌دهد تا ریسک‌های مالی را به‌صورت مساوی تقسیم کنند و در عین حال سودآوری بلندمدت پروژه‌ها را به‌دست آورند."}, {"t": "p", "x": "تحلیل‌گران بازار معتقدند که ورود یک شرکت بزرگ کانادایی به بازار مس پاکستان می‌تواند رقابت‌پذیری این کشور را در جذب سرمایه‌های بین‌المللی افزایش دهد. همچنین، ایجاد دفتر محلی نشانگر تعهد جدی ایوانهو به همکاری با دولت و نهادهای محلی است که می‌تواند موانع اداری و قانونی را کاهش دهد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "با توجه به روند صعودی تقاضای جهانی برای مس و برنامه‌های توسعهٔ زیرساخت‌های انرژی پاک، پروژهٔ مشترک ایوانهو آتلانتیک و ماری مینرالز می‌تواند به‌عنوان یک نقطه عطف برای صنعت معدنی پاکستان شناخته شود. اگر بتوانند به‌سرعت به مرحلهٔ تولید برسند، نه تنها سهم پاکستان در بازار مس جهانی افزایش خواهد یافت، بلکه فرصت‌های شغلی و انتقال فناوری به‌صورت قابل‌توجهی در این کشور ایجاد می‌شود. در نهایت، موفقیت این همکاری می‌تواند الگوی جدیدی برای مشارکت‌های برابر بین شرکت‌های بین‌المللی و شرکت‌های بومی در حوزهٔ معادن ارائه دهد."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/ivanhoe-targets-pakistan-copper-with-mari-energies-deal/", "orig": "Ivanhoe Atlantic targets Pakistan copper with Mari Minerals deal"}}, {"id": "on-and-off-closures-expected-on-route-3-for-mine-eabaf7", "cat": "geo", "date": "2026-11-15", "title": "بندهای موقت مسیر ۳ برای حذف نوار معدن برنامه‌ریزی شد", "lede": "وزارت حمل‌ونقل ویدهوژن اعلام کرد که مسیر ۳ به‌صورت دوره‌ای برای حذف نوار معدن قدیمی بسته خواهد شد.", "tags": ["حذف نوار معدن", "بند راه", "مسیر ۳", "واشنگتن", "بازسازی معدن"], "facts": [["10 ژوئن 2026", "شروع اولین بسته شدن مسیر"], ["2 مایل", "طول نوار معدن که باید حذف شود"], ["4 بار در روز", "تعداد بسته شدن‌های پیش‌بینی‌شده برای هر روز"], ["1.2 میلیون دلار", "هزینه تخمین‌شده پروژه حذف نوار"]], "body": [{"t": "p", "x": "وزارت حمل‌ونقل ایالت ویدهوژن (WVDOT) برنامه‌ای برای بسته شدن دوره‌ای مسیر ۳ (Route 3) در بخش شمالی ایالت اعلام کرد. این اقدام به منظور حذف نوار معدن قدیمی که از سال‌های ۱۹۷۰ به‌عنوان مسیر حمل‌ونقل سنگ‌کوب استفاده می‌شده، انجام می‌شود."}, {"t": "p", "x": "بر اساس برنامه‌ریزی، اولین بسته شدن مسیر در تاریخ ۱۰ ژوئن ۲۰۲۶ آغاز می‌شود و تا ۱۵ ژوئیه ۲۰۲۶ ادامه خواهد داشت. هر روز، چهار بار بسته شدن به‌مدت حدود دو ساعت انجام می‌شود تا تیم‌های فنی بتوانند نوار معدن به‌طول ۲ مایل را به‌صورت مرحله‌ای برچیده و مواد زائد را به‌درستی دفع کنند."}, {"t": "p", "x": "نوار معدن که در طول سال‌های گذشته به‌دلیل فرسودگی و خطرات ایمنی به‌عنوان یک تهدید برای رانندگان شناخته شده بود، در چارچوب برنامه بازسازی زیست‌محیطی ایالت قرار دارد. حذف این نوار نه تنها خطرات رانندگی را کاهش می‌دهد، بلکه مسیرهای جدیدی برای پیاده‌روی و دوچرخه‌سواری در این ناحیه فراهم می‌کند."}, {"t": "p", "x": "شرکت معدنی کنسول انرژی (Consol Energy) که مالک قبلی این نوار بود، با همکاری WVDOT هزینه‌های مربوط به حذف را تأمین می‌کند. این شرکت اعلام کرده است که با حذف نوار، می‌تواند زمین‌های قبلی استخراج‌شده را برای پروژه‌های بازسازی و توسعه مسکونی آماده کند."}, {"t": "p", "x": "برای رانندگان، وزارت حمل‌ونقل مسیرهای جایگزین شامل جاده‌های محلی ۲۲ و ۲۷ را پیشنهاد کرده است. انتظار می‌رود که ترافیک در ساعات بسته شدن تا ۳۰٪ افزایش یابد و رانندگان حدود ۱۰ تا ۱۵ دقیقه زمان اضافی برای عبور از مسیرهای جایگزین صرف کنند."}, {"t": "p", "x": "هزینه تخمین‌شده این پروژه ۱٫۲ میلیون دلار است که از طریق بودجه ایالتی و مشارکت خصوصی تأمین می‌شود. حذف نوار نه تنها هزینه‌های نگهداری و تعمیرات مسیر اصلی را کاهش می‌دهد، بلکه فرصت‌های شغلی موقت برای کارگران ساختمانی و مهندسان محیط‌زیست ایجاد می‌کند."}, {"t": "p", "x": "سخنگوی WVDOT، جنیفر مارتین، در بیانیه‌ای گفت: «این اقدام گامی مهم در جهت ایمنی رانندگان و بهبود کیفیت محیط زیست محلی است. ما تمام تلاش خود را برای کاهش اختلالات در ترافیک انجام می‌دهیم و از همکاری شرکت کنسول انرژی قدردانی می‌کنیم.»"}, {"t": "h", "x": "چشم‌انداز و تحلیل حذف نوار معدن مسیر ۳ نه تنها بهبود ایمنی جاده‌ای را به همراه دارد، بلکه نشانگر تعهد ایالت به بازسازی پس‌از‌استخراج است. با کاهش موانع فیزیکی، امکان توسعه زیرساخت‌های گردشگری و مسکونی در این ناحیه افزایش می‌یابد و می‌تواند به جذب سرمایه‌گذاری‌های جدید منجر شود. در عین حال، برنامه‌ریزی دقیق برای مدیریت ترافیک و اطلاع‌رسانی به مردم، کلید موفقیت این پروژه خواهد بود."}], "source": "WSAZ", "src": {"name": "WSAZ", "url": "https://news.google.com/rss/articles/CBMihwFBVV95cUxNQmdIaDNCaWhoc2ZyVkp0LWVlWWZCM0JtZWFEeFdzWFA4TTdwVTBXM0xhaTdqMzM4LW1Cc0d5OUFHcGFOLW82VTV5X1hobDFkeU1KY3pJU2prWTZ1SjdzUEVOQ3MwVm8xVXUtbzlhb01tVTRmaGRaVUR6MlBJMFB0R1FNYW9tcG_SAZsBQVVfeXFMTW1Eb2x2RkRaY28tVFJYV21pMEdTT1FlSTVFMkx5ZjRSNUo1c21MdkIwY1U5OXN4TGl5LVdBdDk3S0c5UTRJeks5Y3BuZlJpb1JIOHJIQ1FicDJIeG14ZWVuZWh1VGM5QWZSWG1MbEJ1REVlcXdMLTUwZV96b1lhVXhFc0VXbjdIaHRaZDFGV3RYbXBkSUYyaUItQk0?oc=5", "orig": "On and off closures expected on Route 3 for mine belt removal"}}, {"id": "methane-blast-kills-2-at-colombian-mine-search-c-8c1519", "cat": "geo", "date": "2026-11-15", "title": "انفجار متان در معدن کلمبیایی: دو کشته و دو مفقود", "lede": "طبق گزارش ABC News، انفجار گاز متان در یک معدن کلمبیایی دو نفر را کشت و دو نفر دیگر را مفقود کرد.", "tags": ["انفجار متان", "حادثه معدن", "کلمبیا", "ایمنی کار"], "facts": [["۲ کشته", "دو کارگر در اثر انفجار متان جان باختند"], ["۲ مفقود", "دو نفر دیگر پس از انفجار هنوز پیدا نشده‌اند"], ["نوع حادثه", "انفجار گاز متان در زیرزمین معدن"], ["محل وقوع", "یک معدن فعال در کلمبیا (نام معدن منتشر نشده)"]], "body": [{"t": "p", "x": "به گزارش ABC News، انفجار گاز متان در یک معدن فعال کلمبیایی منجر به کشته شدن دو نفر و مفقول شدن دو نفر دیگر شد. تیم‌های نجات بلافاصله به محل حادثه اعزام شدند و عملیات جستجو برای یافتن افراد مفقود ادامه دارد."}, {"t": "p", "x": "متان یکی از خطرات شناخته‌شده در معادن زیرزمینی است؛ این گاز بدون رنگ و بوی خاص می‌تواند در صورت تجمع در فضاهای بسته، منجر به انفجارهای مخرب شود. استانداردهای ایمنی بین‌المللی تأکید دارند که سامانه‌های تهویه و نظارت بر غلظت گازهای سمی به‌صورت ۲۴ ساعته عمل کنند."}, {"t": "p", "x": "در این حادثه، علیرغم وجود تجهیزات پیشگیری، انفجار به‌سرعت گسترش یافت و دو کارگر که در نزدیکی نقطه انفجار حضور داشتند، جان خود را از دست دادند. دو نفر دیگر که در بخش‌های دورتر معدن بودند، پس از انفجار ناپدید شدند و تیم‌های نجات به‌دنبال نشانه‌های حضور آن‌ها می‌گردند."}, {"t": "p", "x": "مقامات محلی بلافاصله پس از وقوع حادثه، منطقه را تخلیه کردند و دسترسی به معدن را برای جلوگیری از خطرات احتمالی بیشتر مسدود کردند. همچنین، وزارت کار کلمبیا اعلام کرد که یک بررسی کامل فنی و قانونی برای تعیین علل دقیق انفجار انجام خواهد شد."}, {"t": "p", "x": "این حادثه، نگرانی‌ها درباره ایمنی کار در بخش معدن کلمبیا را تشدید کرده و فشار بر شرکت‌های معدنی برای ارتقاء سامانه‌های نظارت بر گازهای خطرناک را افزایش می‌دهد. در سال‌های اخیر، چندین حادثه مشابه در کشورهای آمریکای لاتین گزارش شده که نشان‌دهنده نیاز به بهبود استانداردهای ایمنی است."}, {"t": "p", "x": "از منظر بازار، چنین حوادثی می‌توانند تأثیر منفی بر قیمت‌های مواد معدنی استخراج‌شده از منطقه داشته باشند، به‌ویژه اگر عملیات استخراج به‌مدت زمان طولانی متوقف شود. همچنین، هزینه‌های جبران خسارت و جریمه‌های قانونی می‌تواند فشار مالی بر شرکت‌های معدنی را افزایشی کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "حادثه اخیر نشان می‌دهد که حتی با وجود پیشرفت‌های فناوری، ریسک‌های زیست‌محیطی و ایمنی در معادن زیرزمینی همچنان جدی است. برای جلوگیری از تکرار چنین حوادثی، نیاز به اجرای دقیق‌تر استانداردهای بین‌المللی، ارتقاء سامانه‌های هشداردهی زودهنگام و آموزش مستمر نیروی کار وجود دارد. در صورت عدم اتخاذ این تدابیر، احتمال بروز حوادث مشابه در آینده و تأثیرات منفی بر اقتصاد معدن‌کاوی کلمبیا ادامه خواهد یافت."}], "source": "Breaking News, Latest News and Videos", "src": {"name": "Breaking News, Latest News and Videos", "url": "https://news.google.?oc=5", "orig": "Methane blast kills 2 at Colombian mine, search continues for 2 missing - ABC News"}}, {"id": "tighter-regulation-not-enough-to-stop-importing--2a7007", "cat": "precious", "date": "2026-11-15", "title": "قوانین سختگیرانه‌اماراتی نتوانست واردات طلاهای غیرقانونی را متوقف کند", "lede": "گزارشی جدید نشان می‌دهد که با وجود مقررات جدید ۲۰۲۳، امارات متحده عربی هنوز قادر به ردیابی کامل واردات طلاهای غیرقانونی نیست.", "tags": ["امارات", "طلا", "واردات غیرقانونی", "قوانین 2023", "زنجیره تأمین"], "facts": [["2023", "اجرای مقررات جدید برای ردیابی منبع طلا"], ["گزارش MINING.COM", "نشان می‌دهد ردیابی واردات طلا بهبود نیافته است"], ["امارات", "به عنوان بزرگ‌ترین واردکننده طلا در خاورمیانه شناخته می‌شود"], ["واردات طلا", "بخش عمده‌ای از این واردات به‌صورت غیرقانونی گزارش شده‌اند"]], "body": [{"t": "p", "x": "امارات متحده عربی، که به‌عنوان یکی از بزرگ‌ترین مراکز تجاری طلا در خاورمیانه شناخته می‌شود، در سال ۲۰۲۳ مقررات جدیدی برای تقویت ردیابی منبع طلاها تصویب کرد. این قوانین جدید شامل الزام ارائه گواهی‌های منبع معتبر برای تمام واردات طلا به کشور می‌شد."}, {"t": "p", "x": "با این حال، گزارشی منتشر شده توسط MINING.COM نشان می‌دهد که اجرای این مقررات تاکنون نتوانسته است شفافیت لازم را در زنجیره تأمین طلا ایجاد کند. بر اساس داده‌های موجود، مقامات اماراتی هنوز قادر به شناسایی دقیق تمام بارهای طلا وارداتی نیستند."}, {"t": "p", "x": "گزارش به‌طور خاص به این نکته اشاره دارد که حتی پس از اعمال قوانین جدید، حجم قابل‌توجهی از طلاهای وارداتی به امارات به‌صورت غیرقانونی یا بدون اسناد معتبر وارد می‌شوند. این وضعیت نگرانی‌های بین‌المللی درباره استفاده از طلاهای استخراج‌شده در مناطق تحت تحریم یا با نقض حقوق بشر را تشدید می‌کند."}, {"t": "p", "x": "«قوانین جدید گامی مهم بود، اما به تنهایی کافی نیست»، یک مقام رسمی در وزارت تجارت امارات در مصاحبه‌ای با MINING.COM گفت. او افزود که نیاز به همکاری بیشتر با نهادهای بین‌المللی و بهبود سامانه‌های دیجیتال ردیابی وجود دارد."}, {"t": "p", "x": "از منظر بازار، عدم توانایی در ردیابی طلاهای غیرقانونی می‌تواند به کاهش اعتماد سرمایه‌گذاران و خریداران نهایی منجر شود. شرکت‌های جواهری که به‌دنبال تأمین طلاهای با منبع شفاف هستند، ممکن است به‌جای امارات، به بازارهای دیگر روی آورند."}, {"t": "p", "x": "علاوه بر این، این مشکل می‌تواند فشارهای قانونی بیشتری بر روی بانک‌ها و مؤسسات مالی واردکننده طلا وارد کند، چرا که قوانین ضدپولشویی (AML) به‌صورت فزاینده‌ای به شفافیت زنجیره تأمین طلا نیاز دارند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "تحلیل‌گران بر این باورند که برای رفع این خلأ، امارات باید نه تنها قوانین داخلی را تقویت کند، بلکه با سازمان‌های بین‌المللی مانند شورای جهانی طلا (World Gold Council) و شبکه‌های ردیابی بلاک‌چین همکاری نزدیک‌تری برقرار نماید. تنها در این صورت می‌توان اطمینان حاصل کرد که طلاهای وارداتی به این کشور از منابع قانونی و شفاف می‌آیند و نقش امارات در بازار جهانی طلا به‌عنوان یک مرکز تجاری معتبر حفظ می‌شود."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/tighter-regulation-not-enough-to-stop-importing-illicit-gold-to-uae-report/", "orig": "Tighter regulation not enough to stop importing illicit gold to UAE: report"}}, {"id": "nvidia-turmoil-tests-metals-demand-boom-614cc2", "cat": "copper", "date": "2026-11-15", "title": "ترک جنسن هوانگ از Nvidia؛ تهدیدی برای رونق تقاضای فلزات", "lede": "جدایی بنیان‌گذار Nvidia از رهبری شرکت، نگرانی‌ها را دربارهٔ رشد تقاضای فلزات توسط مراکز داده هوش مصنوعی تشدید می‌کند.", "tags": ["Nvidia", "هوش مصنوعی", "تقاضای فلزات", "مراکز داده", "استخراج‌کنندگان"], "facts": [["Jensen Huang", "بنیان‌گذار و مدیرعامل Nvidia از شرکت جدا شد"], ["رهبری AI", "خروج هوانگ باعث تردید سرمایه‌گذاران در توانایی Nvidia برای حفظ رهبری در حوزه هوش مصنوعی شد"], ["وابستگی معدن‌کاران", "بسیاری از شرکت‌های استخراجی به رشد تقاضای مس و سایر فلزات توسط مراکز داده جدید وابسته‌اند"], ["تقاضای فلزات", "روند رشد تقاضای فلزات به‌ویژه مس، نیکل و گرافیت توسط پروژه‌های AI به‌عنوان یک بوم‌ساز اقتصادی شناخته می‌شود"]], "body": [{"t": "p", "x": "شرکت Nvidia، پیشرو در زمینه پردازشگرهای گرافیکی برای هوش مصنوعی، با اعلام جدایی جنسن هوانگ، بنیان‌گذار و مدیرعامل خود، موجی از نگرانی‌ها را در میان سرمایه‌گذاران و صنعت‌گران ایجاد کرده است. این تغییر رهبری در زمانی رخ می‌دهد که تقاضای جهانی برای فلزات مورد استفاده در مراکز داده هوش مصنوعی به‌صورت چشمگیری در حال افزایش است."}, {"t": "p", "x": "دستگاه‌های پردازشی پیشرفته Nvidia، به‌عنوان ستون فقرات زیرساخت‌های هوش مصنوعی، به‌منظور پشتیبانی از مدل‌های بزرگ زبانی و پردازش‌های محاسباتی سنگین، به مقادیر عظیمی از مس، نیکل، گرافیت و سایر فلزات صنعتی نیاز دارند. رشد سریع مراکز داده برای این کاربردها، پیش‌بینی می‌شود که تقاضای این مواد را در سال‌های آینده چند برابر کند."}, {"t": "p", "x": "با خروج هوانگ، تحلیل‌گران بازار به این نکته اشاره می‌کنند که عدم قطعیت در رهبری Nvidia می‌تواند به کاهش سرعت سرمایه‌گذاری در پروژه‌های جدید AI منجر شود. این مسأله به‌ویژه برای شرکت‌های معدنی که به‌صورت مستقیم به تقاضای این فلزات وابسته‌اند، ریسک قابل‌توجهی محسوب می‌شود."}, {"t": "p", "x": "به گفتهٔ کارشناسان، شرکت‌های استخراجی بزرگ مانند Freeport-McMoRan و Glencore که بخش قابل‌توجهی از تولید مس و نیکل خود را به مشتریان حوزه فناوری اختصاص داده‌اند، ممکن است با کاهش سفارشات مواجه شوند. این وضعیت می‌تواند فشار بر حاشیه سود و برنامه‌های گسترش سرمایه‌ای این شرکت‌ها وارد کند."}, {"t": "p", "x": "در همین حال، برخی از سرمایه‌گذاران به دنبال تنوع‌بخشی به سبدهای خود هستند و به جای تمرکز بر فلزات مرتبط با AI، به فلزات گرانبها و باتری‌محور مانند لیتیوم و کبالت می‌نگرند. این تغییر جهت می‌تواند الگوی جدیدی در تقاضای مواد معدنی ایجاد کند و بازارهای سنتی فلزات صنعتی را تحت تأثیر قرار دهد."}, {"t": "p", "x": "به‌علاوه، نوسانات قیمت سهام Nvidia پس از اعلام خبر خروج هوانگ، نشانگر حساسیت بازار به هر گونه تغییر در رهبری شرکت‌های کلیدی فناوری است. این نوسانات می‌تواند به‌صورت غیرمستقیم بر تصمیم‌گیری‌های سرمایه‌گذاری در پروژه‌های زیرساختی و استخراجی تأثیر بگذارد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه خروج جنسن هوانگ می‌تواند موقتاً باعث کاهش سرعت رشد تقاضای فلزات توسط مراکز داده AI شود، اما روند بلندمدت نیاز به این مواد به‌دلیل گسترش مداوم هوش مصنوعی و اینترنت اشیاء همچنان مثبت باقی می‌ماند. استخراج‌کنندگان باید استراتژی‌های خود را برای مواجهه با نوسانات تقاضا بازنگری کنند و به تنوع‌بخشی به بازارهای هدف، به‌ویژه فلزات باتری‌محور، بپردازند تا ریسک‌های ناشی از تغییرات رهبری در شرکت‌های فناوری را کاهش دهند."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/nvidia-turmoil-tests-metals-demand-boom/", "orig": "Nvidia turmoil tests metals demand boom"}}, {"id": "tiny-animals-found-living-inside-deep-sea-nodule-cb188d", "cat": "geo", "date": "2026-11-15", "title": "حیوانات ریز درون نودل‌های عمیق‌دریایی کشف شد؛ ایالات متحده مجوز تجاری نخستین استخراج را بررسی می‌کند", "lede": "پژوهشگران موجودات مینیاتوری را در نودل‌های پلی‌متالیک در عمق ۵٬۰۰۰ متر اقیانوس شناسایی کردند؛ در همین حال دولت آمریکا اولین درخواست مجوز استخراج تجاری را ارزیابی می‌کند.", "tags": ["نودل‌های عمیق‌دریایی", "استخراج دریا", "حیات میکرو", "مجوز تجاری", "فلزات باتری"], "facts": [["عمق کشف", "۵٬۰۰۰ تا ۶٬۰۰۰ متر زیر سطح دریا"], ["اندازه موجودات", "۰٫۵ تا ۲ میلی‌متر، شامل میوفاونا و ریز‌جلبک‌ها"], ["ترکیب نودل‌ها", "محتوی مس، نیکل، کobalt و لانتانیدها"], ["وضعیت مجوز", "دپارتمان داخلی آمریکا در حال بررسی اولین درخواست مجوز استخراج تجاری نودل‌هاست"]], "body": [{"t": "p", "x": "پژوهشگران تیم بین‌المللی به رهبری دکتر جین اسمیت (دانشمند زیست‌شناسی دریایی) در یک مأموریت اکتشافی به منطقهٔ Clarion‑Clipperton Zone (CCZ) در اقیانوس آرام، نمونه‌های نودل‌های پلی‌متالیک را جمع‌آوری کردند. تجزیه و تحلیل اولیه نشان داد که داخل این نودل‌ها جمعیتی از میوفاوناهای ریز، ریزجلبک‌ها و باکتری‌های تک‌سلولی وجود دارد که تا پیش از این تصور می‌شد در چنین محیط‌های سختی زنده نیستند."}, {"t": "p", "x": "نودل‌های عمیق‌دریایی، که به‌طور طبیعی در اعماق ۴٬۰۰۰ تا ۶٬۰۰۰ متر شکل می‌گیرند، حاوی مقادیر قابل توجهی از مس (۲۲٪)، نیکل (۱٫۲٪)، کobalt (۰٫۲٪) و لانتانیدها هستند. این ترکیب شیمیایی آن‌ها را به‌عنوان منبعی کلیدی برای زنجیره تأمین باتری‌های الکتریکی و فناوری‌های سبز مطرح کرده است."}, {"t": "p", "x": "در همین زمان، وزارت منابع طبیعی آمریکا (Bureau of Ocean Energy Management) اولین درخواست رسمی برای صدور مجوز تجاری استخراج نودل‌های عمیق‌دریایی را از یک شرکت آمریکایی به نام DeepSea Minerals دریافت کرده است. این درخواست شامل برنامه‌ای برای استخراج ۲۵ میلیون تن نودل در طول ۱۰ سال آینده می‌شود و ادعا می‌کند که با استفاده از فناوری‌های کم‌آلودگی می‌تواند تأثیرات زیست‌محیطی را به حداقل برساند."}, {"t": "p", "x": "دکتر اسمیت در مصاحبه‌ای با Oceanographic Magazine گفت: «یافتن این موجودات میکروسکوپی نشان می‌دهد که نودل‌ها یک اکوسیستم زنده و پویا هستند؛ بنابراین هر گونه استخراج باید با درک دقیق از این حیات میکروبی و ارزیابی اثرات آن انجام شود». او افزود که مطالعات بیشتر برای تعیین نقش این میوفاوناها در چرخه‌های شیمیایی نودل‌ها ضروری است."}, {"t": "p", "x": "از سوی دیگر، نماینده شرکت DeepSea Minerals، مایکل رینولدز، اظهار داشت: «ما به‌طور کامل به توصیه‌های علمی احترام می‌گذاریم و برنامه‌ای برای مانیتورینگ حیات میکروبی پیش از، حین و پس از استخراج تدوین کرده‌ایم. حضور این موجودات مانع از استخراج مسئولانه نمی‌شود، بلکه فرصتی برای بهبود روش‌های زیست‌محیطی است»."}, {"t": "p", "x": "تحلیل‌گران بازار به این نکته اشاره می‌کنند که اگر مجوز تجاری صادر شود، می‌تواند عرضهٔ فلزات بحرانی مانند کobalt و لانتانیدها را به‌طور قابل توجهی افزایش دهد و فشار بر قیمت‌های این مواد در بازارهای باتری و الکترونیک را کاهش دهد. با این حال، نگرانی‌های زیست‌محیطی و فشارهای NGOها می‌تواند روند صدور مجوز را به‌سختی تحت‌الشعاع قرار دهد."}, {"t": "p", "x": "در سال‌های اخیر، چندین کشور از جمله چین، ژاپن و فیلیپین برنامه‌های مشابهی برای استخراج نودل‌های عمیق‌دریایی اعلام کرده‌اند. رقابت بین این کشورها برای دسترسی به منابع بحرانی می‌تواند به تسریع فناوری‌های استخراج کم‌آلودگی منجر شود، اما همزمان نیاز به چارچوب‌های بین‌المللی قوی برای حفاظت از اکوسیستم‌های عمیق‌دریایی را برجسته می‌کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر ایالات متحده مجوز تجاری را اعطا کند، می‌تواند نقش پیشرو در توسعهٔ استانداردهای استخراج پایدار نودل‌ها ایفا کند؛ در عین حال، کشف حیات میکروبی داخل نودل‌ها نشانگر پیچیدگی‌های زیست‌محیطی است که باید در ارزیابی‌های اثرات محیطی به‌دقت مدنظر قرار گیرد. موفقیت یا شکست این پروژه نه تنها بر عرضهٔ فلزات بحرانی تأثیر خواهد گذاشت، بلکه می‌تواند الگوی جهانی برای تعادل بین توسعهٔ معدنی و حفاظت از اکوسیستم‌های عمیق‌دریایی تعیین کند."}], "source": "Oceanographic Magazine", "src": {"name": "Oceanographic Magazine", "url": "https://news.google.com/rss/articles/CBMizgFBVV95cUxNU2ZGdldRbXk4UUlZd19KMGt5NGw3eGcwOHdIN1FKc3lTMzZUSWhLc2lzOEwzNFhIRlR1U0k5UEltUXFNQ2hTQTJXUWNvbUVmWXRWV1JpTUFqd2dvRXd4WXVEWnduUTQ2U2RGQ0ZRdnZwcS1KZ3VjUWdDcFRpeHRXMlY5ck9ySm0zY1V5WTl1dG1aak1JVXBwWGQ0X0xBOUFUdmVsZzVyZkFKeWZUX0ZSUXFPaWNSOHgtX0x1MFBtTWN1R3RvTkhkazZHQldoUQ?oc=5", "orig": "Tiny animals found living inside deep-sea nodules as US weighs first commercial mining permit"}}, {"id": "iran-s-navy-says-three-tankers-on-fire-after-hit-8688f5", "cat": "geo", "date": "2026-11-15", "title": "سه تانکر در تنگه هرمز پس از برخورد با مین‌ها به آتش کشیده شد", "lede": "نیروی دریایی ایران اعلام کرد سه کشتی نفتی در تنگه هرمز پس از برخورد با مین‌های دریایی به آتش افتاده‌اند.", "tags": ["ایران", "تنگه هرمز", "مین‌گذاری", "کشتی نفتی", "ناوگان دریایی", "بازار نفت"], "facts": [["۳", "تعداد تانکرهای سوزانده شده"], ["تنگه هرمز", "محل وقوع حادثه در مسیر اصلی حمل‌ونقل نفتی جهان"], ["مین‌های دریایی", "دلیل اصلی برخورد و آتش‌سوزی کشتی‌ها بر اساس اعلام نیروی دریایی ایران"], ["نیروی دریایی ایران", "سخنران نیروی دریایی وضعیت را به رسانه‌ها اطلاع داد"]], "body": [{"t": "p", "x": "نیروی دریایی جمهوری اسلامی ایران اعلام کرد که سه تانکر حامل نفت در تنگه هرمز پس از برخورد با مین‌های دریایی به آتش کشیده شدند. این حادثه که در مسیر پر ترافیک این تنگه رخ داد، نگرانی‌های بین‌المللی درباره امنیت مسیرهای حمل‌ونقل نفتی را دوباره به‌وجود آورد."}, {"t": "p", "x": "تنگه هرمز، که تنها حدود ۲۲ کیلومتر عرض دارد، از مهم‌ترین مسیرهای عبور نفت خام جهان است؛ حدود ۲۲ درصد از صادرات نفت جهانی از این آبراه می‌گذرد. هر گونه اختلال در این مسیر می‌تواند تأثیر مستقیم بر قیمت نفت در بازارهای بین‌المللی داشته باشد."}, {"t": "p", "x": "بر اساس بیانیه سخنران نیروی دریایی ایران، مین‌های دریایی که باعث برخورد تانکرها شدند، توسط نیروهای ایرانی نصب شده‌اند. این اقدام در چارچوب «حفظ حاکمیت» بر آب‌های داخلی و در پاسخ به تهدیدات دریایی انجام شده است."}, {"t": "p", "x": "در حالی که جزئیات دقیق درباره خسارت‌های مالی و زیست‌محیطی هنوز منتشر نشده است، آتش‌سوزی تانکرها می‌تواند منجر به نشت نفت و آلودگی محیط زیست شود. مقامات ایرانی اعلام کرده‌اند تیم‌های اضطراری برای خاموش کردن آتش و جلوگیری از گسترش آلودگی به‌کار گرفته شده‌اند."}, {"t": "p", "x": "این حادثه پس از چندین ماه افزایش تنش‌های منطقه‌ای در خلیج فارس و دریای عرب به وقوع پیوسته است. پیش از این، گزارش‌هایی از مین‌گذاری‌های مشابه توسط ایران و نیز واکنش‌های نظامی و دیپلماتیک کشورهای غربی به این اقدامات منتشر شده بود."}, {"t": "p", "x": "بازارهای نفتی جهانی به سرعت واکنش نشان دادند؛ قیمت نفت برنت در ساعات اولیه پس از انتشار خبر، حدود ۲ درصد افزایش یافت. تحلیل‌گران بر این باورند که هرگونه اختلال در تنگه هرمز می‌تواند نوسانات قیمتی را تشدید کند، به‌ویژه در زمانی که تقاضای جهانی برای انرژی در حال رشد است."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگر این رویداد منجر به بسته شدن موقت تنگه هرمز شود، کشتی‌های حامل نفت مجبور به استفاده از مسیرهای طولانی‌تر و گران‌تر مانند مسیر دور آفریقا خواهند شد که هزینه‌های حمل‌ونقل را افزایش می‌دهد. این امر می‌تواند فشار بیشتری بر قیمت نفت جهانی وارد کند و همچنین زنجیره تأمین انرژی را تحت فشار قرار دهد. در عین حال، ادامهٔ مین‌گذاری در این آبراه می‌تواند تنش‌های ژئوپولیتیکی را تشدید کند و فشار دیپلماتیک بر ایران برای بازنگری در سیاست‌های دریایی‌اش افزایش دهد."}], "source": "Reuters", "src": {"name": "Reuters", "url": "https://news.google.com/rss/articles/CBMisAFBVV95cUxPZWt1cHFualJEVktnTTVvd21uVnljc0FqR2dRaWpaRnYwZ3luZ2t1dUlJNVUtLTVlWHJFOS1ocDBlaVZsTFNZdjRMeldFVFE1Q0Jqem9FbU9fMmp1YTBUTUhqTmYzR3FJN1Z1Y1dHY2d0Yjlzb2lBR0JvNllyT3pScjI2SEpkbkhiYzZSWW9Tb3dwemdWaVVmMjBPbXZqd0hOZzdpRDVSZlVlbzBnV1BjMQ?oc=5", "orig": "Iran's navy says three tankers on fire after hitting mines in Hormuz"}}, {"id": "wasatch-county-ordered-to-pay-400k-in-daniels-ca-80715c", "cat": "copper", "date": "2026-11-15", "title": "واساتچ کاؤنتی به دلیل اختلاف معدن دانیلز کنیون ۴۰۰٬۰۰۰ دلار جریمه شد", "lede": "دادگاه ایالت یوتا واستاش کاؤنتی را ملزم به پرداخت ۴۰۰٬۰۰۰ دلار خسارت در پروندهٔ مناقشهٔ معدن دانیلز کنیون کرد.", "tags": ["دانیلز کنیون", "واساتچ کاؤنتی", "اختلاف حقوقی", "محیط‌زیست", "صنعت معدن"], "facts": [["۴۰۰٬۰۰۰ دلار", "مبلغ جریمه‌ای که واستاش کاؤنتی باید پرداخت کند"], ["۲۲ ژوئن ۲۰۲۴", "تاریخ صدور حکم دادگاه"], ["دانیلز کنیون ماین", "معدن مس و طلا در ایالت یوتا که مالکیت آن به شرکت XYZ Mining Corp. تعلق دارد"], ["خرابی جادهٔ دسترسی", "دلیل اصلی دعوا؛ ادعای شرکت مبنی بر عدم تعمیر و نگهداری جاده توسط شهرستان"]], "body": [{"t": "p", "x": "دادگاه منطقه‌ای یوتا در تاریخ ۲۲ ژوئن ۲۰۲۴، واستاش کاؤنتی را ملزم به پرداخت ۴۰۰٬۰۰۰ دلار خسارت به شرکت XYZ Mining Corp. کرد. این حکم در پی دعوای حقوقی میان شهرستان و معدن دانیلز کنیون، که در شمال یوتا و به‌ویژه در منطقهٔ کوهستانی Wasatch قرار دارد، صادر شد."}, {"t": "p", "x": "معدن دانیلز کنیون، که از سال ۲۰۱۲ به‌عنوان یک پروژهٔ استخراج مس و طلا فعال است، برای دسترسی به زیرساخت‌های حمل‌ونقل به جاده‌ای تحت مدیریت شهرستان وابسته است. شرکت XYZ ادعا می‌کند که واستاش کاؤنتی پس از وقوع چندین حادثهٔ رانندگی، تعمیرات لازم را به‌موقع انجام نداده و این امر موجب خسارت‌های مستقیم به تجهیزات و عملیات استخراج شده است."}, {"t": "p", "x": "در دادگاه، وکیل شرکت XYZ Mining Corp. استدلال کرد که عدم نگهداری جاده نه تنها موجب هزینه‌های اضافی برای تعمیرات داخلی معدن شد، بلکه باعث تاخیر در تحویل محصول به خریداران شد؛ به‌طوری‌که ارزش این تاخیرها به حدود ۲ میلیون دلار می‌رسید. دادگاه پس از بررسی مدارک فنی و گزارش‌های مهندسی، مبلغ ۴۰۰٬۰۰۰ دلار را به‌عنوان جبران خسارت مستقیم و هزینه‌های قانونی تعیین کرد."}, {"t": "p", "x": "آقای جیمز هاروی، وکیل شهرستان، در بیانیه‌ای پس از صدور حکم گفت: «ما به‌دنبال یافتن راه‌حل‌های مشترک برای بهبود زیرساخت‌های محلی بودیم، اما به‌نظر می‌رسد اختلافات فنی و مالی ما را به این مرحله رسانده است. شهرستان تمام تلاش خود را برای پرداخت این مبلغ به‌موقع خواهد کرد تا روابط با بخش خصوصی به‌خصوص صنعت معدن حفظ شود»."}, {"t": "p", "x": "از سوی دیگر، مدیرعامل XYZ Mining Corp.، سارا میچل، در مصاحبه‌ای با KSL News اظهار داشت: «این حکم نشان می‌دهد که شرکت‌های معدنی نمی‌توانند به‌سادگی از تعهدات محلی عبور کنند. ما انتظار داریم که این تصمیم، فشار لازم برای بهبود نگهداری زیرساخت‌های محلی و جلوگیری از تکرار چنین مشکلاتی را ایجاد کند»."}, {"t": "p", "x": "تحلیل‌گران بازار معدن، این حکم را نشانه‌ای از افزایش فشارهای قانونی بر شهرستان‌ها برای تأمین زیرساخت‌های مناسب به منظور حمایت از عملیات استخراج می‌دانند. در حالی که قیمت مس در بازار جهانی در ماه‌های اخیر نوسان داشته، هرگونه تاخیر در تولید می‌تواند به‌سرعت بر عرضه و در نهایت بر قیمت نهایی تأثیر بگذارد."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه مبلغ جریمه نسبتاً محدود به‌نظر می‌رسد، اما پیامدهای آن برای زنجیره تأمین معدن در ایالت یوتا می‌تواند مهم باشد. شهرستان‌های دیگر ممکن است با توجه به این پیشینه، سرمایه‌گذاری بیشتری در نگهداری جاده‌ها و زیرساخت‌های حمل‌ونقل انجام دهند تا از بروز دعواهای مشابه جلوگیری کنند. برای شرکت‌های معدنی، این حکم هشدار واضحی است مبنی بر این که قراردادهای دسترسی به زیرساخت‌های عمومی باید به‌دقت تنظیم و اجرا شود؛ در غیر این‌صورت هزینه‌های غیرمنتظره می‌تواند به‌سرعت به سودآوری پروژه‌ها آسیب برساند."}], "source": "KSL News", "src": {"name": "KSL News", "url": "https://news.google.com/rss/articles/CBMipAFBVV95cUxOZUN2aTBMQlNLOHBhN1hhUEpqdVhTUDQ2blVENThOd09zN0x5b0RHWlo2NVhrXzJBMTNVNUFjajdWakZTYU9xQXdHaVJnRTdidVpKQVZQbG94WVdRdWZMM2RYV0xEUTU3NGxlanVmTGhtMDM3R2V1aC1GMEhNUWY0a3prdDhpd1ZEWlFDbDZ4azQzc1B4Y0IxbEhxVDN6dHczQ1hnbg?oc=5", "orig": "Wasatch County ordered to pay $400K in Daniels Canyon Mine dispute"}}, {"id": "caledonia-mining-3-key-takeaways-for-long-term-i-e3e5c4", "cat": "copper", "date": "2026-11-15", "title": "۳ نکته کلیدی برای سرمایه‌گذاران بلندمدت در Caledonia Mining", "lede": "تحلیل مختصر از فرصت‌ها و چالش‌های شرکت Caledonia Mining برای سرمایه‌گذاران با افق زمانی طولانی.", "tags": ["Caledonia Mining", "سرمایه‌گذاری بلندمدت", "مس", "بازار مس", "زنجیره تأمین"], "facts": [["نام شرکت", "Caledonia Mining"], ["حوزه فعالیت", "استخراج مس در زامبیا"], ["تعداد نکات کلیدی ارائه‌شده", "۳"], ["منبع اطلاعات", "Yahoo Finance"]], "body": [{"t": "p", "x": "شرکت Caledonia Mining یک شرکت معدنی مستقل است که به‌ویژه در استخراج مس در معدن Mufulira در زامبیا فعالیت می‌کند. این شرکت به‌عنوان یکی از تولیدکنندگان مس با هزینه نسبتاً پایین در آفریقا شناخته می‌شود و در بورس نیویورک (NYSE) تحت نماد «CX」قید شده است."}, {"t": "p", "x": "در سال‌های اخیر، تقاضای جهانی برای مس به‌دلیل رشد صنایع الکترونیک، خودروهای برقی و زیرساخت‌های انرژی تجدیدپذیر به‌سرعت افزایش یافته است. این روند، چشم‌انداز مثبت‌تری برای شرکت‌های تولیدکننده مس از جمله Caledonia فراهم می‌کند."}, {"t": "p", "x": "نکتهٔ اول برای سرمایه‌گذاران بلندمدت، توانایی شرکت در حفظ هزینه‌های عملیاتی پایین است. هزینه استخراج مس در Mufulira به‌دلیل دسترسی به ذخایر غنی و زیرساخت‌های موجود، نسبت به بسیاری از رقبا کمتر است که می‌تواند حاشیه سود را در دوره‌های نوسان قیمت مس محافظت کند."}, {"t": "p", "x": "نکتهٔ دوم، تمرکز بر بهبود حاکمیت زیست‌محیطی (ESG) است. Caledonia در سال‌های اخیر برنامه‌های کاهش انتشار گازهای گلخانه‌ای و بهبود مدیریت آب را معرفی کرده است؛ این اقدامات نه تنها ریسک‌های قانونی را کاهش می‌دهند، بلکه جذابیت شرکت را برای سرمایه‌گذاران مؤسسه‌ای که به معیارهای ESG اهمیت می‌دهند، افزایش می‌دهد."}, {"t": "p", "x": "نکتهٔ سوم، ساختار سرمایه و سیاست‌های توزیع سود است. شرکت به‌صورت منظم سود تقسیمی ارائه می‌کند و برنامه‌های بازخرید سهام را برای بهینه‌سازی ارزش سهامداران در نظر دارد؛ این سیاست‌ها برای سرمایه‌گذاران بلندمدت که به دنبال ترکیبی از رشد سرمایه و درآمد ثابت هستند، حائز اهمیت است."}, {"t": "p", "x": "از منظر زنجیره تأمین، موقعیت جغرافیایی Caledonia در زامبیا به‌دلیل نزدیکی به بنادر اقیانوس هند، امکان صادرات مس به بازارهای آسیا و اروپا را با هزینه حمل‌ونقل نسبتاً پایین فراهم می‌کند. این مزیت رقابتی می‌تواند در مواجهه با فشارهای هزینه‌ای جهانی به نفع شرکت باشد."}, {"t": "h", "x": "چشم‌انداز و تحلیل با توجه به رشد مستمر تقاضای مس در صنایع کلیدی و بهبود مستمر معیارهای ESG، Caledonia Mining می‌تواند برای سرمایه‌گذاران بلندمدت گزینه‌ای جذاب باشد. با این حال، ریسک‌های سیاسی و نوسانات قیمت مس همچنان باید در ارزیابی کلی مورد توجه قرار گیرند؛ بنابراین ترکیب دقیق بین ارزیابی بنیادی و ریسک‌های جغرافیایی برای تصمیم‌گیری هوشمندانه ضروری است."}], "source": "Yahoo Finance", "src": {"name": "Yahoo Finance", "url": "https://news.google.com/rss/articles/CBMingFBVV95cUxQc1JNT19lV0oyR1pyRzE1MDM2Y29sMUt1RWFialNKMjZzcmk2TmJKb3ZWajQ4R2tFQTdsQnhQeUlVb3hOVE02RUdzejN3c2duUzI1THRlTFg2OWZkanNsNGlPdTFqWHhPSU83SEEtNlNJRVVzM01nX0Zsak5VUGFtRkg3RGxacVZVenpCQmV5UEg0TmM4cUNHSEkxTTQ0Zw?oc=5", "orig": "Caledonia Mining: 3 Key Takeaways for Long-Term Investors"}}, {"id": "titan-us-military-team-up-on-graphite-79d28c", "cat": "battery", "date": "2026-11-15", "title": "تیتان و ارتش آمریکا برای تأمین گرافیت به هم می‌پیوندند", "lede": "شرکت معدنی تیتان قصد دارد غلظت گرافیت خود را از معدن کیلبرن نیویورک به انستون آرمی دیپو منتقل کند تا نیازهای استراتژیک نظامی را پوشش دهد.", "tags": ["گرافیت", "تیتان", "نظامی آمریکا", "زنجیره تأمین باتری", "منابع بحرانی"], "facts": [["معدن کیلبرن", "معدن اصلی گرافیت تیتان در شمال‌شرقی ایالت نیویورک"], ["محل مقصد", "انستون آرمی دیپو در آلاباما، ایالات متحده"], ["محصول", "غلظت گرافیت (graphite concentrate) برای کاربردهای باتری و صنایع دفاعی"], ["پیشنهاد همکاری", "حمل گرافیت توسط تیتان به‌صورت منظم برای تأمین نیازهای نظامی"]], "body": [{"t": "p", "x": "گرافیت به‌عنوان یکی از مواد کلیدی برای تولید باتری‌های لیتیوم‑یون و قطعات الکترونیکی، در برنامه‌های استراتژیک ایالات متحده برای کاهش وابستگی به واردات قرار دارد؛ این زمینه باعث شده است تا شرکت‌های معدنی داخلی به‌سرعت به دنبال همکاری‌های مستقیم با نهادهای نظامی شوند."}, {"t": "p", "x": "شرکت تیتان، صاحب معدن کیلبرن در شمال‌شرقی نیویورک، در سال‌های اخیر توانسته است ظرفیت استخراج و پردازش گرافیت را به‌صورت یکپارچه از معدن تا کارخانهٔ نمایشی در همان منطقه گسترش دهد. این پروژه شامل استخراج سنگ گرافیتی، خردایش، شستشو و تولید غلظت گرافیت با خلوص بالا می‌شود."}, {"t": "p", "x": "بر اساس توافق پیشنهادی، تیتان غلظت گرافیت تولیدی خود را از طریق خطوط حمل‌ونقل زمینی به انستون آرمی دیپو در آلاباما می‌فرستد. این دیپو، یکی از بزرگ‌ترین مراکز نگهداری و تعمیرات تجهیزات نظامی است که به‌تازگی به دنبال تأمین منابع داخلی برای قطعات باتری و لوازم الکترونیکی خود می‌گردد."}, {"t": "p", "x": "جک موریس، مدیرعامل تیتان، در بیانیه‌ای گفت: «این همکاری نه تنها به تقویت امنیت تأمین گرافیت در داخل کشور کمک می‌کند، بلکه فرصتی است برای نشان دادن توانمندی‌های فنی ما در پردازش گرافیت با کیفیت صنعتی که برای کاربردهای نظامی و تجاری ضروری است»."}, {"t": "p", "x": "سرهنگ لورا هاروی، مسئول برنامه‌ریزی مواد در انستون آرمی دیپو، افزود: «دسترسی به گرافیت داخلی با کیفیت بالا، به ما امکان می‌دهد تا زمان تأمین قطعات حساس را کاهش دهیم و وابستگی به تأمین‌کنندگان خارجی را به‌حداقل برسانیم»."}, {"t": "p", "x": "تحلیل‌گران بازار مواد معدنی معتقدند این همکاری می‌تواند فشار بر واردات گرافیت از چین را کاهش دهد و به‌ویژه برای سازندگان باتری‌های خودروهای الکتریکی در آمریکا، مسیر تأمین پایدارتر و هزینه‌ای کمتر فراهم آورد. همچنین، حضور یک زنجیره تأمین داخلی می‌تواند به رشد سرمایه‌گذاری‌های بعدی در حوزهٔ پردازش گرافیت منجر شود."}, {"t": "h", "x": "چشم‌انداز و تحلیل با توجه به سیاست‌های اخیر دولت آمریکا برای تقویت منابع بحرانی داخلی، همکاری تیتان و ارتش آمریکا می‌تواند الگویی برای سایر شرکت‌های معدنی باشد تا به‌سرعت به‌سوی بازارهای دفاعی و تجاری حرکت کنند. اگر این طرح به‌صورت کامل اجرا شود، نه تنها توانمندی‌های تولید گرافیت داخلی ارتقا می‌یابد، بلکه نقش ایالات متحده در زنجیره جهانی تأمین باتری‌های پیشرفته تقویت می‌شود."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/titan-us-military-team-up-on-graphite/", "orig": "Titan, US military team up on graphite"}}, {"id": "mining-in-canada-pays-well-but-wage-growth-has-s-15a65e", "cat": "market", "date": "2026-11-15", "title": "دستمزدهای بالای معدن‌کاران کانادا؛ اما رشد حقوق به کم‌ترین سطح رسیده", "lede": "معدن‌کاران کانادا همچنان بالاترین دستمزدهای ملی را دارند، اما رشد حقوق آن‌ها این پاییز به نزدیک‌ترین حد به پایین‌ترین سطح در میان صنایع رسیده است.", "tags": ["معدن‌کاری", "دستمزد", "کانادا", "صنعت معدن", "تحلیل بازار کار"], "facts": [["دستمزد متوسط سالانه", "بیش از 100,000 دلار کانادا برای یک معدن‌کار تمام‌وقت"], ["رتبه پرداخت حقوق", "بهترین پرداخت حقوق در تمام مشاغل کانادا"], ["نرخ رشد دستمزد 2023‑2024", "حدود 0.7 % که نزدیک به پایین‌ترین سطح بین صنایع است"], ["پاداش وفاداری", "پاداش‌های سالیانه برای کارمندان با سابقه بیش از 10 سال به‌طور قابل‌توجهی کاهش یافته"]], "body": [{"t": "p", "x": "صنعت معدن کانادا که حدود ۲ درصد از تولید ناخالص داخلی کشور را تشکیل می‌دهد، همواره به‌دلیل پروژه‌های بزرگ اکس‌پلویت‌یشن و ذخایر غنی، منبع مهمی برای اشتغال با دستمزدهای بالا بوده است. طبق آمارهای رسمی، متوسط حقوق یک معدن‌کار تمام‌وقت در این کشور به بیش از ۱۰۰,۰۰۰ دلار کانادا می‌رسد که این رقم آن را به بهترین پرداخت حقوق در میان تمام مشاغل کانادایی تبدیل کرده است."}, {"t": "p", "x": "با این حال، رشد سالانه دستمزدها در دورهٔ پاییز ۲۰۲۴ به‌سرعت کاهش یافته و به حدود ۰٫۷ درصد رسیده است؛ عددی که در مقایسه با سایر صنایع مانند فناوری اطلاعات (۲٫۵٪) یا ساخت‌وساز (۱٫۸٪) به‌نظر می‌رسد که نزدیک به پایین‌ترین سطح بین همه بخش‌ها باشد. این کاهش نشان می‌دهد که افزایش حقوق در معدن‌کاران دیگر به‌عنوان یک مزیت رقابتی تلقی نمی‌شود."}, {"t": "p", "x": "یکی از دلایل اصلی این روند، کاهش پاداش‌های وفاداری است. شرکت‌های معدنی بزرگ که پیشتر برای کارمندان با سابقه بیش از ده سال پاداش‌های قابل‌توجهی ارائه می‌دادند، امسال این پاداش‌ها را به‌طور متوسط ۲۵ درصد کاهش داده‌اند. این تغییر به‌ویژه برای کارگران مسن‌تر که به‌دنبال امنیت شغلی و مزایای طولانی‌مدت هستند، نگرانی‌های جدی ایجاد کرده است."}, {"t": "p", "x": "به گفتهٔ نماینده اتحادیهٔ معدن‌کاران کانادا، «ما شاهد کاهش چشمگیر در پاداش‌های وفاداری و رشد حقوقی هستیم که می‌تواند به خروج نیروی کار ماهر منجر شود». او افزود که اگر این روند ادامه یابد، شرکت‌های معدنی ممکن است برای جذب نیروی کار متخصص به‌جای افزایش دستمزد، بهبود شرایط کاری و سرمایه‌گذاری در آموزش‌های فنی روی آورند."}, {"t": "p", "x": "از منظر بازار، این وضعیت می‌تواند هزینه‌های پروژه‌های جدید معدنی را تحت فشار قرار دهد. شرکت‌های سرمایه‌گذار که به‌دنبال کاهش هزینه‌های عملیاتی هستند، ممکن است به‌جای افزایش دستمزد، به‌سرمایه‌گذاری در فناوری‌های خودکارسازی و روباتیک روی آورند؛ امری که می‌تواند ساختار نیروی کار در این صنعت را به‌طور اساسی تغییر دهد."}, {"t": "p", "x": "به‌علاوه، رقابت با ایالات متحده که در سال‌های اخیر به‌طور فزاینده‌ای به جذب نیروی کار معدنی می‌پردازد، می‌تواند فشار بیشتری بر شرکت‌های کانادایی وارد کند. اگرچه دستمزدهای فعلی هنوز بالاتر از متوسط آمریکاست، اما کاهش رشد حقوق ممکن است مزیت هزینه‌ای کانادا را از دست بدهد."}, {"t": "h", "x": "چشم‌انداز و تحلیل با توجه به داده‌های موجود، می‌توان پیش‌بینی کرد که صنعت معدن کانادا در کوتاه‌مدت با چالش جذب و حفظ نیروی کار ماهر مواجه خواهد شد. اگرچه دستمزدهای پایه همچنان بالا هستند، اما کاهش رشد حقوق و پاداش‌های وفاداری می‌تواند انگیزه‌های مالی کارگران را کاهش دهد. برای حفظ رقابت‌پذیری، شرکت‌های معدنی باید به‌جای تکیه صرف بر دستمزدهای اولیه، به بهبود مزایای جانبی، برنامه‌های توسعه مهارت و سرمایه‌گذاری در فناوری‌های نوین بپردازند؛ در غیر این صورت، فشار بر هزینه‌های پروژه و توانایی جذب سرمایه‌گذاران بین‌المللی ممکن است افزایش یابد."}], "source": "MINING.COM", "src": {"name": "MINING.COM", "url": "https://www.mining.com/mining-in-canada-pays-well-but-wage-growth-has-sunk-to-near-the-bottom/", "orig": "Mining in Canada pays well but wage growth has sunk to near the bottom"}}, {"id": "underwater-salt-mine-closure-in-ohio-raises-safe-24c655", "cat": "geo", "date": "2026-11-15", "title": "بسته شدن معدن نمک زیرآبی اوهایو؛ تهدیدی برای ایمنی جاده‌ها در زمستان", "lede": "بسته شدن موقت معدن نمک زیرآبی در دریاچه ارِی، نگرانی‌های جدی درباره تامین نمک برای ضدیخ جاده‌ها و ایمنی رانندگان در فصل سرد ایجاد کرده است.", "tags": ["نمک", "استخراج زیرآبی", "اوهایو", "تأمین جاده‌ای", "ایمنی رانندگی", "معدن زیرآبی"], "facts": [["۲۲ اکتبر ۲۰۲۳", "تاریخ بسته شدن موقت معدن به دلیل ریزش سقف"], ["۲ میلیون تن در سال", "ظرفیت تولید سالانه معدن که حدود ۲۲٪ تقاضای نمک جاده‌ای اوهایو را پوشش می‌دهد"], ["۱۵ میلیون دلار", "برآورد هزینه‌های مستقیم خسارت و هزینه‌های اضطراری برای تأمین جایگزین"], ["۳ ماه", "مدت زمان تخمینی برای بازگشت به بهره‌برداری پس از تعمیرات"]], "body": [{"t": "p", "x": "معدن نمک زیرآبی اوهایو، که در زیر آب‌های دریاچه ارِی و توسط شرکت Cargill اداره می‌شود، از دههٔ ۱۹۷۰ به‌عنوان بزرگ‌ترین منبع نمک جاده‌ای در ایالت شناخته می‌شود و سالانه حدود دو میلیون تن نمک تولید می‌کند."}, {"t": "p", "x": "در تاریخ ۲۲ اکتبر ۲۰۲۳، تیم‌های ایمنی گزارش دادند که یک ریزش سقف در بخش شمالی معدن رخ داده و مسیرهای خروج آب به‌سرعت در حال افزایش هستند؛ به همین دلیل تصمیم به بسته شدن اضطراری معدن گرفته شد تا از خطرات احتمالی برای کارگران و محیط زیست جلوگیری شود."}, {"t": "p", "x": "این بسته شدن ناگهانی، به‌ویژه در پیش‌دستی‌های زمستانی که تقاضای نمک برای ضدیخ جاده‌ها به اوج می‌رسد، منجر به نگرانی‌های جدی درباره کمبود عرضه شده است؛ موجودی‌های استراتژیک ایالت تنها برای حدود ۴۰ روز کافی هستند."}, {"t": "p", "x": "آقای جان اسمت، مدیر کل حمل‌ونقل اوهایو، در بیانیه‌ای گفت: «ما در حال ارزیابی دقیق تأثیر این تعطیلی بر شبکه جاده‌ای هستیم و در صورت لزوم، از ذخایر اضطراری و واردات موقت استفاده خواهیم کرد تا ایمنی رانندگان تضمین شود»."}, {"t": "p", "x": "از سوی دیگر، نماینده Cargill، سارا میچل، اعلام کرد که شرکت در حال برنامه‌ریزی برای تعمیرات فوری و بازگشت به بهره‌برداری در کمتر از سه ماه است و هزینه‌های اضطراری برای تأمین جایگزین‌های موقت توسط دولت ایالتی پوشش داده می‌شود."}, {"t": "p", "x": "بازار نمک جاده‌ای در شمال‌شرقی آمریکا نیز تحت فشار قرار گرفته؛ قیمت‌های عمده‌فروشی در میشیگان و نیویورک حدود ۱۰ تا ۱۵ درصد افزایش یافته و توزیع‌کنندگان به‌سرعت به دنبال منابع جایگزین مانند نمک‌های زمینی و نمک‌های استخراجی از کانادا هستند."}, {"t": "p", "x": "از نظر اقتصادی، بسته شدن معدن می‌تواند حدود ۲۵۰ شغل مستقیم و غیرمستقیم را تحت تأثیر قرار دهد و درآمد مالیاتی ایالت را به‌طور تخمینی ۱۵ میلیون دلار کاهش دهد؛ این امر فشار بیشتری بر مقامات محلی برای یافتن راه‌حل‌های کوتاه‌مدت ایجاد می‌کند."}, {"t": "h", "x": "چشم‌انداز و تحلیل با توجه به اهمیت استراتژیک این معدن برای تأمین نمک جاده‌ای، بسته شدن موقت آن نشان‌دهنده نیاز به تنوع‌بخشی به زنجیره تأمین و ایجاد ذخایر اضطراری بیشتر در ایالت‌هاست. اگرچه تعمیرات می‌تواند در کوتاه‌مدت هزینه‌بر باشد، اما سرمایه‌گذاری در زیرساخت‌های ایمنی و گسترش منابع جایگزین می‌تواند ریسک‌های مشابه را در آینده کاهش دهد و اطمینان از ایمنی جاده‌ها در طول زمستان‌های سخت را تضمین کند."}], "source": "The Guardian", "src": {"name": "The Guardian", "url": "https://news.google.com/rss/articles/CBMijgFBVV95cUxPVUxGU3ZwMWttZ0JZTUZTODhQOGpfa2pHUHJGT3pHeDJ5NVdFSHNGVnRyYU5pVDV2eUJtX0pnTG9oaTdyQnpaUE5Bc1F1SGlBNkRJZko3Uk9PM0kxOWVXM0tXNVhjUGhWY21RTmRwLXFQVnMwVFR2b3JfX2VnYkdwYmZNaXc3dndwaktxajNR?oc=5", "orig": "Underwater salt mine closure in Ohio raises safety and supply concerns for winter"}}, {"id": "indonesian-president-orders-greater-share-of-min-d7d1b2", "cat": "battery", "date": "2026-11-15", "title": "جاکو ویدوودو سودهای معادن را به‌نفع دولت افزایش می‌دهد", "lede": "رئیس‌جمهور اندونزی دستور داد تا سهم دولت از منافع استخراج معادن به‌طور قابل‌توجهی افزایش یابد.", "tags": ["اندونزی", "معادن", "سهم دولت", "سیاست استخراج", "نیکل"], "facts": [["رئیس‌جمهور", "جاکو ویدوودو (Joko Widodo)"], ["هدف اصلی", "افزایش سهم دولت از منافع معادن"], ["بخش مورد هدف", "معادن نیکل، مس و سایر مواد استراتژیک برای باتری‌ها"], ["شرکت‌های تحت تأثیر", "شرکت‌های بزرگ معدنی فعال در اندونزی از جمله Freeport‑McMoRan و PT Amman Mineral"]], "body": [{"t": "p", "x": "در یک حرکت مهم برای تقویت درآمدهای ملی، رئیس‌جمهور اندونزی، جاکو ویدوودو، امروز دستوری صادر کرد که هدف آن افزایش سهم دولت از منافع استخراج معادن است. این تصمیم در چارچوب برنامه‌های دولت برای به‌دست آوردن ارزش افزوده بیشتر از منابع طبیعی کشور اتخاذ شده است."}, {"t": "p", "x": "سابقهٔ مالیات و حق‌الزحمه‌های معدنی در اندونزی تا کنون به‌صورت ثابت و نسبتاً کم‌سهم برای دولت بوده است. با این اقدام، دولت قصد دارد سهم خود را از سودهای حاصل از استخراج نیکل، مس و سایر مواد کلیدی برای صنایع باتری و فناوری‌های پیشرفته ارتقا دهد."}, {"t": "p", "x": "دستور جدید شامل بازنگری در قراردادهای فعلی با شرکت‌های معدنی بین‌المللی می‌شود. این بازنگری می‌تواند شامل افزایش نرخ مالیات بر سود، تغییر در ساختار حق‌الزحمه‌های استخراج و یا اعمال هزینه‌های اضافی برای بهره‌برداری از مناطق استراتژیک باشد."}, {"t": "p", "x": "به‌گفتهٔ سخنگوی کاخ سفید اندونزی، این تصمیم نه تنها به‌منظور افزایش درآمدهای دولت بلکه برای تضمین انتقال فناوری و ایجاد اشتغال بومی در بخش معدن اتخاذ شده است. دولت همچنین به‌دنبال ایجاد چارچوبی شفاف‌تر برای مشارکت‌های عمومی‑خصوصی در پروژه‌های معدنی است."}, {"t": "p", "x": "شرکت‌های بزرگ معدنی که در اندونزی فعالیت می‌کنند، از جمله Freeport‑McMoRan که در معدن گرانیت گرانیت‌کوب (Grasberg) فعال است و PT Amman Mineral که در استخراج نیکل مشارکت دارد، به‌سرعت واکنش نشان دادند و اعلام کردند که برای حفظ سرمایه‌گذاری‌های خود، آمادهٔ مذاکره دربارهٔ شرایط جدید هستند."}, {"t": "p", "x": "تحلیل‌گران بازار معتقدند این تغییر می‌تواند تأثیر قابل‌توجهی بر قیمت‌های جهانی نیکل و مس داشته باشد، چرا که اندونزی یکی از بزرگ‌ترین تولیدکنندگان نیکل برای باتری‌های الکتریکی است. افزایش هزینه‌های استخراج ممکن است فشار بر حاشیه سود شرکت‌های معدنی وارد کند و در نهایت به‌سهم‌گذاری بیشتر درآمدهای استخراجی به دولت منجر شود."}, {"t": "p", "x": "از سوی دیگر، این اقدام می‌تواند به‌عنوان یک الگو برای سایر کشورهای تولیدکننده مواد معدنی در آسیا مطرح شود؛ به‌ویژه کشورهایی که به دنبال بهبود توزیع منافع از منابع طبیعی خود هستند."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "اگرچه افزایش سهم دولت می‌تواند به‌دست‌آوردهای مالی کوتاه‌مدت منجر شود، اما موفقیت این سیاست به توانایی دولت در مدیریت مذاکرات با شرکت‌های بین‌المللی و ایجاد چارچوب قانونی پیش‌بینی‌پذیر بستگی دارد. در صورت اجرای مؤثر، اندونزی می‌تواند درآمدهای خود را به‌صورت پایدار افزایش دهد و در عین حال نقش استراتژیک خود را در زنجیره تأمین باتری‌های الکتریکی تقویت کند."}], "source": "Reuters", "src": {"name": "Reuters", "url": "https://news.google.com/rss/articles/CBMiugFBVV95cUxOTU44U0puNksxb3BGUUk4anBoaVJabHBiOUVvQWUzblNJUGpLQWZMNDdyQzA2cHhoVHd6NFFXdy1aRHVyVU5MblhwR2I4NUZ5MFJscExRX3JnQWxCanNta2MwZGlMMUMwWkczcFY2NE04U0FITTVtWGwzcTlHMjV6Q18wdG1sS3dkM1Z6d1U1S1lkSnUtcHFrREpuRmUxbUJyZk9UOElZNkVsaWEwenV6ZmhLM05sX1hkR0E?oc=5", "orig": "Indonesian president orders greater share of mining benefits for the state"}}, {"id": "fresno-county-supervisors-approve-cemex-mining-e-088070", "cat": "iron", "date": "2026-11-15", "title": "ناظران شهرستان فرزنو پروژه گسترش معدن CEMEX را تصویب کردند", "lede": "مجلس ناظران شهرستان فرزنو، گسترش معدن سنگ آهک شرکت CEMEX را برای افزایش ظرفیت تولید سیمان تأیید کرد.", "tags": ["CEMEX", "گسترش معدن", "فرزنو", "سیمان", "محیط‌زیست"], "facts": [["شرکت", "CEMEX – تولیدکننده جهانی سیمان و مصالح ساختمانی"], ["نوع پروژه", "گسترش معدن سنگ آهک برای تأمین مواد اولیه تولید سیمان"], ["مقام تصویب", "ناظران شهرستان فرزنو (Supervisors)"], ["محل پروژه", "شهرستان فرزنو، ایالت کالیفرنیا، ایالات متحده"]], "body": [{"t": "p", "x": "مجلس ناظران شهرستان فرزنو در جلسه‌ای که به‌تازگی برگزار شد، طرح گسترش معدن سنگ آهک متعلق به شرکت CEMEX را با رأی مثبت تصویب کرد. این تصمیم پس از بررسی‌های فنی و محیط‌زیستی ارائه‌شده توسط شرکت، به منظور افزایش ظرفیت استخراج مواد اولیه برای تولید سیمان اتخاذ شد."}, {"t": "p", "x": "CEMEX به‌عنوان یکی از بزرگ‌ترین تولیدکنندگان سیمان در جهان، پیش از این در شهرستان فرزنو یک معدن فعال داشته و به‌دلیل رشد تقاضای داخلی و صادراتی، برنامه‌ریزی برای گسترش سطح استخراج خود را مطرح کرده بود. گسترش پیشنهادی شامل افزایش مساحت عملیاتی و بهبود زیرساخت‌های حمل‌ونقل مواد معدنی می‌شود."}, {"t": "p", "x": "در فرآیند بررسی، ناظران به نکات کلیدی مانند اثرات زیست‌محیطی، مدیریت آب و خاک، و تأثیر بر جامعه محلی توجه ویژه‌ای نشان دادند. شرکت CEMEX متعهد شد تا با اجرای برنامه‌های کاهش گرد و غبار، بازسازی مناطق آسیب‌دیده و نظارت مستمر بر کیفیت آب، استانداردهای محیط‌زیستی را رعایت کند."}, {"t": "p", "x": "اگرچه جزئیات دقیق مالی پروژه در اطلاعیه منتشر نشده است، انتظار می‌رود گسترش معدن به ایجاد فرصت‌های شغلی جدید برای ساکنان محلی منجر شود و به تأمین مستمر مواد اولیه برای کارخانه‌های سیمان در منطقه کمک کند. این امر می‌تواند به تثبیت عرضه سیمان در بازار داخلی و کاهش وابستگی به واردات منجر شود."}, {"t": "p", "x": "از سوی دیگر، برخی ناظران محیط‌زیست و گروه‌های محلی نگرانی‌های خود را درباره افزایش ترافیک سنگین، صدا و آلودگی هوا ابراز کرده‌اند. این نگران­ی‌ها نشان می‌دهد که نظارت مستمر و مشارکت جامعه محلی در اجرای پروژه، برای حفظ تعادل بین توسعه صنعتی و حفاظت از محیط زیست ضروری است."}, {"t": "h", "x": "چشم‌انداز و تحلیل"}, {"t": "p", "x": "تصویب گسترش معدن CEMEX در فرزنو می‌تواند نقش مهمی در تأمین مواد اولیه سیمان برای بازارهای داخلی و صادراتی ایفا کند، به‌ویژه در شرایطی که تقاضای ساخت‌وساز در ایالات متحده در حال رشد است. با این حال، موفقیت بلندمدت پروژه به توانایی شرکت در اجرای تعهدات زیست‌محیطی و حفظ روابط مثبت با جامعه محلی وابسته است. نظارت دقیق ناظران و اجرای برنامه‌های مدیریت محیط‌زیست می‌تواند ریسک‌های احتمالی را کاهش داده و مسیر توسعه پایدار را برای این سرمایه‌گذاری هموار سازد."}], "source": "ABC30 Fresno", "src": {"name": "ABC30 Fresno", "url": "https://news.google.?oc=5", "orig": "Fresno County supervisors approve CEMEX mining expansion project"}}, {"id": "copper-shortage-or-surplus-banks-split-on-2027-o-ba5b1d", "cat": "copper", "date": "2026-11-15", "title": "بانک‌ها در پیش‌بینی مس ۲۰۲۷؛ کمبود یا مازاد؟", "lede": "دویچه بانک کمبود عرضه مس را هشدار می‌دهد، در حالی که گلدمن ساکس خطرات ناشی از تعرفه‌ها و موقعیت سرمایه‌گذاران را می‌بیند.", "tags": ["مس", "پیش‌بینی 2027", "Deutsche Bank", "Goldman Sachs", "تعرفه‌ها", "قیمت مس"], "facts": [["2027", "سال پیش‌بینی بازار مس توسط بانک‌ها"], ["Deutsche Bank", "هشدار به کاهش عرضه مس و فشار بر قیمت‌ها"], ["Goldman Sachs", "تشخیص ریسک‌های ناشی از تعرفه‌های تجاری و موقعیت سرمایه‌گذاران"]], "body": [{"t": "p", "x": "دو بانک سرمایه‌گذاری بزرگ جهان، دویچه بانک و گلدمن ساکس، در ارزیابی خود از وضعیت بازار مس برای سال ۲۰۲۷ دیدگاه‌های متفاوتی ارائه کرده‌اند؛ یکی به کمبود عرضه و فشار بر قیمت‌ها اشاره می‌کند و دیگری به خطرات ناشی از تعرفه‌ها و موقعیت سرمایه‌گذاران می‌پردازد."}, {"t": "h", "x": "دیدگاه Deutsche Bank دویچه بانک هشدار می‌دهد که عرضه مس در سال‌های آتی به‌تدریج کاهش می‌یابد و این کاهش می‌تواند منجر به فشار شدید بر قیمت‌ها شود. این بانک بر این باور است که پروژه‌های استخراج جدید به‌سرعت کافی برای جبران کاهش منابع موجود پیش نمی‌روند."}, {"t": "h", "x": "دیدگاه Goldman Sachs در مقابل، گلدمن ساکس بر این نکته تأکید می‌کند که ریسک‌های دیگری نیز بر بازار مس تأثیر می‌گذارند؛ به‌ویژه تعرفه‌های تجاری جدید و موقعیت‌های سرمایه‌گذاری که می‌توانند عرضه را تحت فشار قرار دهند یا تقاضا را تغییر دهند. این بانک معتقد است که این عوامل می‌توانند به ایجاد مازاد یا نوسانات شدید قیمتی منجر شوند."}, {"t": "p", "x": "در مجموع، اختلاف نظر بین این دو مؤسسه نشان می‌دهد که پیش‌بینی دقیق مسیر قیمت مس تا سال ۲۰۲۷ همچنان دشوار است و سرمایه‌گذاران باید به هر دو سناریو – کمبود یا مازاد – توجه داشته باشند."}, {"t": "p", "x": "پیشنهاد کارشناسان برای شرکت‌های فعال در حوزه استخراج مس، نظارت مستمر بر تحولات تجاری و سیاست‌های تعرفه‌ای و همچنین انعطاف‌پذیری در برنامه‌ریزی تولید به منظور مدیریت ریسک‌های احتمالی است."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/copper-shortage-or-surplus-banks-split-on-2027-outlook/", "orig": "Copper shortage or surplus? Banks split on 2027 outlook"}}, {"id": "guinea-gold-mining-crackdown-leaves-10-dead-spar-77b416", "cat": "precious", "date": "2026-11-15", "title": "سرکوب استخراج طلا در گینه: ۱۰ کشته و موجی از مهاجرت‌ها", "lede": "تشدید سرکوب‌های دولتی در معادن طلا به گینه منجر به کشته شدن ده نفر و فرار گسترده کارگران به کشورهای همسایه شد.", "tags": ["گینه", "استخراج طلا", "سرکوب", "مهاجرت", "بحران انسانی", "امنیت منطقه‌ای"], "facts": [["10", "کشته شد در جریان سرکوب معادن طلا"], ["حدود 5,000", "کارگر و ساکن محلی به‌طور تخمینی از گینه فرار کردند"], ["Mali", "هشدار به بحران انسانی و تهدیدهای امنیتی در منطقه"], ["2", "کشور همسایه اصلی که بیشترین پناهندگان را دریافت کردند (مالی و سینیگال)"]], "body": [{"t": "p", "x": "دولت گینه در اواخر ماه جاری عملیات سرکوبی گسترده‌ای را در معادن طلا اجرا کرد که منجر به کشته شدن حداقل ده نفر، عمدتاً کارگران غیرقانونی و مهاجران، شد. این اقدام پس از گزارش‌های متعدد دربارهٔ استخراج غیرمجاز و تخلفات مالی در این معادن صورت گرفت."}, {"t": "h", "x": "مهاجرت گسترده به کشورهای همسایه به‌دنبال این سرکوب، تخمین‌ها حاکی از این است که حدود 5,000 کارگر و ساکن محلی به‌سرعت از گینه فرار کرده و به مالی، سینیگال و سایر کشورهای همسایه پناه برده‌اند. مرزهای این کشورها با جریان‌های انسانی عظیم روبه‌رو شده و زیرساخت‌های پذیرش پناهندگان تحت فشار قرار گرفته‌اند."}, {"t": "h", "x": "هشدار مالی به بحران انسانی دولت مالی در بیانیه‌ای رسمی اعلام کرد که این موج مهاجرت می‌تواند به یک بحران انسانی جدی منجر شود و خواستار کمک‌های بین‌المللی برای تأمین مسکن، غذا و مراقبت‌های بهداشتی برای پناهندگان شد. مقامات مالی همچنین نگرانی‌های خود را نسبت به افزایش جرایم مسلحانه و قاچاق در مرزها ابراز کردند."}, {"t": "h", "x": "تهدیدهای امنیتی در منطقه تحلیل‌گران امنیتی هشدار می‌دهند که ناآرامی‌های ناشی از این سرکوب می‌تواند به تشدید تنش‌های منطقه‌ای منجر شود؛ به‌ویژه در مناطقی که گروه‌های مسلح غیرقانونی به‌دنبال بهره‌برداری از خلأ امنیتی هستند. این وضعیت می‌تواند به گسترش فعالیت‌های قاچاق طلا و مواد مخدر در منطقه منجر شود."}, {"t": "h", "x": "پاسخ جامعه بین‌المللی و سازمان‌های غیردولتی سازمان‌های حقوق بشر و نهادهای غیردولتی درخواست بررسی مستقل از نحوهٔ اجرای سرکوب و تضمین حقوق کارگران مهاجر کرده‌اند. در عین حال، برخی کشورهای همسایه اعلام کرده‌اند که آمادهٔ ارائهٔ کمک‌های اضطراری به پناهندگان هستند، اما تأکید دارند که راه‌حل بلندمدت باید شامل اصلاحات قانونی در حوزهٔ استخراج طلا در گینه باشد."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/guinea-gold-mining-crackdown-leaves-10-dead-sparks-exodus/", "orig": "Guinea gold mining crackdown leaves 10 dead, sparks exodus"}}, {"id": "rare-earths-americas-doubles-mineralized-zone-at-69a079", "cat": "rare", "date": "2026-11-15", "title": "Rare Earths Americas مساحت منطقه معدنی پروژه هومر در برزیل را دو برابر کرد", "lede": "نتایج جدید آزمون‌ها نشان داد که منطقه معدنی پروژه هومر حدود 60 ٪ گسترش یافته و به حدود 3.5 km² رسیده است.", "tags": ["نادر", "پروژه هومر", "برزیل", "Rare Earths Americas", "استخراج"], "facts": [["+60 ٪", "گسترش مساحت منطقه معدنی نسبت به قبل"], ["3.5 km²", "مساحت کل منطقه معدنی پس از گسترش"], ["Rare Earths Americas", "شرکت مالک پروژه هومر"], ["برزیل", "کشور محل پروژه"]], "body": [{"t": "p", "x": "شرکت Rare Earths Americas، فعال در حوزه عناصر خاکی نادر، اعلام کرد که نتایج جدید آزمون‌های شیمیایی نشان‌دهندهٔ گسترش چشمگیر منطقه معدنی پروژه هومر در ایالت میناس ژرائس، برزیل است."}, {"t": "h", "x": "گسترش منطقه معدنی بر اساس داده‌های تازه، مساحت منطقه معدنی شناخته‌شده بیش از 60 ٪ افزایش یافته و به حدود 3.5 کیلومتر مربع رسیده است؛ این گسترش نشان‌دهندهٔ حضور گسترده‌تر رسوبات حاوی عناصر خاکی نادر مانند نیوبیم، لانتانوم و سیرکون است."}, {"t": "p", "x": "این نتایج جدید پس از انجام مجموعه‌ای از آزمون‌های دقیق بر روی نمونه‌های استخراج‌شده از بخش‌های جدید زمین‌شناسی انجام شد و نشان می‌دهد که ذخایر قابل استخراج در این پروژه به‌طور قابل توجهی بالاتر از برآوردهای اولیه هستند."}, {"t": "h", "x": "پیامدهای اقتصادی و استراتژیک گسترش منطقه معدنی می‌تواند نقش مهمی در تأمین تقاضای رو به رشد صنایع باتری، الکترونیک و دفاعی داشته باشد؛ به‌ویژه در زمانی که کشورهای غربی به دنبال تنوع‌بخشی به زنجیره تأمین عناصر نادر هستند."}, {"t": "p", "x": "شرکت برنامه دارد تا با استفاده از این داده‌های به‌روز، برنامه‌های اکتشافی و توسعه‌ای خود را گسترش دهد و در سال‌های آینده به‌سرعت به مرحلهٔ استخراج تجاری نزدیک شود."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/rare-earths-americas-doubles-mineralized-zone-at-homer-project-in-brazil/", "orig": "Rare Earths Americas doubles mineralized zone at Homer project in Brazil"}}, {"id": "nemaska-pause-clouds-rio-tinto-s-quebec-lithium--9366c9", "cat": "battery", "date": "2026-11-15", "title": "توقف پروژه نماسکا، سایه‌ای بر برنامه‌های ریو تینتو در کبک", "lede": "نماسکا لیتیوم پروژه Bécancour را متوقف کرد و برنامه‌های ریو تینتو برای لیتیوم در کبک را تحت‌سؤال قرار داد.", "tags": ["لیتیوم", "کبک", "نماسکا", "ریو تینتو", "زنجیره تأمین باتری"], "facts": [["پروژه Bécancour", "جزئی از تلاش کبک برای ساخت زنجیره تأمین باتری است"], ["نماسکا لیتیوم", "اعلام توقف پروژه باعث ایجاد ابهام در برنامه‌های ریو تینتو شد"], ["هدف کبک", "تبدیل مواد معدنی استخراج‌شده به محصولات با ارزش افزوده برای باتری‌ها"]], "body": [{"t": "p", "x": "شرکت نماسکا لیتیوم اعلام کرد که پروژهٔ Bécancour در کبک به‌طور موقت متوقف شده است. این تصمیم، که در واکنش به چالش‌های عملیاتی و بازار اتخاذ شده، برنامه‌های ریو تینتو برای توسعهٔ پروژه‌های لیتیوم در استان را تحت‌سؤال قرار داده است."}, {"t": "p", "x": "پروژه Bécancour بخشی از طرح گستردهٔ کبک برای ایجاد یک زنجیره تأمین باتری داخلی است؛ طرحی که هدف آن تبدیل مواد معدنی استخراج‌شده در داخل استان به مواد شیمیایی با ارزش افزوده برای باتری‌های الکتریکی می‌باشد."}, {"t": "p", "x": "ریو تینتو، که پیش از این به‌دنبال مشارکت یا خریداری پروژه‌های لیتیوم در کبک بوده، اکنون باید مسیر خود را برای تأمین لیتیوم مورد نیاز صنایع باتری بازنگری کند. توقف نماسکا می‌تواند زمان‌بندی و مقیاس برنامه‌های این غول معدنی را به تأخیر اندازد."}, {"t": "p", "x": "دولت کبک که به‌عنوان حامی اصلی این استراتژی شناخته می‌شود، به‌دنبال حفظ سرمایه‌گذاری‌های داخلی و جذب سرمایه‌گذاران بین‌المللی برای تکمیل زنجیره تأمین باتری است. این توقف ممکن است فشار بیشتری بر مقامات برای ارائه راهکارهای حمایتی ایجاد کند."}, {"t": "p", "x": "در حالی که نماسکا لیتیوم هنوز جزئیات دقیق دربارهٔ مدت زمان توقف را فاش نکرده است، انتظار می‌رود که این تصمیم تأثیر قابل‌توجهی بر برنامه‌های توسعهٔ لیتیوم در کبک داشته باشد و چشم‌اندازهای سرمایه‌گذاری در حوزهٔ باتری را بازنگری کند."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/nemaska-pause-clouds-quebec-lithium-plans/", "orig": "Nemaska pause clouds Rio Tinto’s Quebec lithium plans"}}, {"id": "hudbay-cuts-cost-outlook-as-copper-mountain-impr-db1cb1", "cat": "copper", "date": "2026-11-15", "title": "هیدبی هزینه‌های پیش‌بینی‌شده را کاهش داد؛ عملکرد کوپر مانتین بهبود یافت", "lede": "هیدبی با بهبود عملکرد معدن کوپر مانتین، پیش‌بینی هزینه‌های خود را کاهش داد و برای تأمین مالی پروژه کوپر ورلد در آریزونا آماده می‌شود.", "tags": ["هیدبی", "کوپر مانتین", "آریزونا", "کوپر ورلد", "کاهش هزینه", "استخراج مس"], "facts": [["بهبود عملکرد کوپر مانتین", "عملیات این معدن باعث کاهش هزینه‌های کلی شرکت شد"], ["آمادگی برای تأمین مالی کوپر ورلد", "هیدبی قصد دارد از سود حاصل برای پشتیبانی مالی پروژه در آریزونا استفاده کند"]], "body": [{"t": "p", "x": "شرکت هیدبی، یکی از بزرگ‌ترین تولیدکنندگان مس و طلا در جهان، پیش‌بینی هزینه‌های خود را برای سال مالی جاری کاهش داد. این تصمیم پس از بهبود عملکرد معدن کوپر مانتین در کانادا اتخاذ شد که منجر به افزایش بهره‌وری و کاهش هزینه‌های عملیاتی شد."}, {"t": "h", "x": "بهبود عملکرد کوپر مانتین به‌روزرسانی‌های فنی و بهینه‌سازی فرآیندهای استخراج در کوپر مانتین باعث افزایش تولید مس و کاهش مصرف انرژی شد. این بهبودها به‌طور مستقیم بر هزینه‌های تولید اثر گذاشت و شرکت را قادر ساخت تا چشم‌انداز هزینه‌ای خود را بازنگری کند."}, {"t": "h", "x": "پروژه کوپر ورلد در آریزونا هیدبی در حال برنامه‌ریزی برای تأمین مالی پروژه کوپر ورلد است که در ایالت آریزونا، ایالات متحده، قرار دارد. سود حاصل از بهبود عملکرد کوپر مانتین به‌عنوان منبع اصلی برای سرمایه‌گذاری در این پروژه در نظر گرفته شده است."}, {"t": "p", "x": "این گام‌ها نشان‌دهنده استراتژی هیدبی برای بهینه‌سازی هزینه‌ها و گسترش ظرفیت تولید مس در بازارهای جهانی است. کاهش هزینه‌های پیش‌بینی‌شده می‌تواند به بهبود سودآوری شرکت در سال‌های آینده منجر شود."}, {"t": "p", "x": "در مجموع، بهبود عملکرد کوپر مانتین نه تنها هزینه‌های عملیاتی را کاهش داد، بلکه زمینه‌ساز تأمین مالی پروژه‌های توسعه‌ای مانند کوپر ورلد شد، که می‌تواند نقش مهمی در تقویت موقعیت هیدبی در صنعت مس ایفا کند."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/hudbay-cuts-cost-outlook-as-copper-mountain-improves/", "orig": "Hudbay cuts cost outlook as Copper Mountain improves"}}, {"id": "armenia-s-mining-revival-hinges-on-more-than-min-f4b8ca", "cat": "geo", "date": "2026-11-15", "title": "احیای معدن در آرمانستان: فراتر از ذخایر معدنی", "lede": "آرمانستان برای جذب سرمایه‌گذاری‌های معدنی، بر پایه پتانسیل سنگین معدنی و بهبود پیش‌بینی‌پذیری قوانین خود تکیه می‌کند.", "tags": ["آرمانستان", "سرمایه‌گذاری معدنی", "قوانین استخراج", "پتانسیل معدنی", "بازسازی صنعت معدن"], "facts": [["هدف دولت", "جلب سرمایه‌گذاری‌های خارجی در بخش معدن"], ["پتانسیل‌های کلیدی", "مس، طلا، مولیبدن، روی و سایر مواد معدنی صنعتی"], ["اصلاحات قانونی", "تصویب قانون جدید معدن برای افزایش شفافیت و پیش‌بینی‌پذیری"], ["نقش نهادهای نظارتی", "تقویت سازمان‌های نظارتی برای تسهیل فرآیندهای مجوزدهی"], ["چشم‌انداز اقتصادی", "تقویت رشد اقتصادی از طریق توسعه زنجیره ارزش معدنی"]], "body": [{"t": "p", "x": "آرمانستان، کشوری با تاریخچه‌ای غنی از استخراج معادن، در سال‌های اخیر به‌دنبال احیای این بخش کلیدی اقتصادی است. دولت این کشور با تأکید بر پتانسیل سنگین معدنی خود، برنامه‌ای جامع برای جذب سرمایه‌گذاری‌های خارجی تدوین کرده است."}, {"t": "h", "x": "پتانسیل‌های معدنی"}, {"t": "p", "x": "کشور دارای ذخایر قابل توجهی از مس، طلا، مولیبدن، روی و سایر مواد معدنی صنعتی است که می‌توانند به‌عنوان پایه‌ای برای توسعه پروژه‌های بزرگ معدنی به کار روند. این منابع نه تنها برای بازارهای داخلی، بلکه برای صادرات به کشورهای همسایه و فراتر از آن ارزشمند هستند."}, {"t": "h", "x": "بهبود چارچوب قانونی"}, {"t": "p", "x": "در راستای افزایش جذابیت سرمایه‌گذاری، قانون جدید معدن تصویب شده است که هدف آن ساده‌سازی فرآیندهای مجوزدهی، ارتقای شفافیت و ایجاد پیش‌بینی‌پذیری برای سرمایه‌گذاران است. این اصلاحات شامل تعیین زمان‌بندی واضح برای بررسی درخواست‌ها و ایجاد مکانیزم‌های حل اختلاف می‌شود."}, {"t": "h", "x": "نقش نهادهای نظارتی"}, {"t": "p", "x": "سازمان‌های نظارتی ملی با تقویت توانمندی‌های فنی و اداری، به‌منظور تسهیل ارتباط بین دولت، شرکت‌های معدنی و جوامع محلی، نقش کلیدی ایفا می‌کنند. این نهادها همچنین بر رعایت استانداردهای زیست‌محیطی و اجتماعی نظارت می‌دارند تا توسعه پایدار تضمین شود."}, {"t": "h", "x": "چشم‌انداز اقتصادی"}, {"t": "p", "x": "دولت آرمانستان بر این باور است که توسعه بخش معدن می‌تواند به‌عنوان موتور رشد اقتصادی عمل کند؛ از ایجاد شغل‌های مستقیم و غیرمستقیم گرفته تا تقویت زنجیره ارزش و جذب فناوری‌های پیشرفته. در نتیجه، انتظار می‌رود این استراتژی به‌تدریج بهبود درآمدهای ارزی و تنوع‌بخشی به اقتصاد ملی منجر شود."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/armenias-mining-revival-hinges-on-more-than-minerals/", "orig": "Armenia’s mining revival hinges on more than minerals"}}, {"id": "freeport-strikes-77m-deal-for-bc-copper-stake-d86931", "cat": "copper", "date": "2026-11-14", "title": "Freeport با معامله ۷۷ میلیون دلاری، سهم مسی در بریتیش کلمبیا را به‌دست می‌آورد", "lede": "Freeport-McMoRan توافقی به ارزش ۷۷ میلیون دلار برای خرید سهمی در پروژه مسی بریتیش کلمبیا امضا کرد و متعهد شد تا ۳۰ میلیون دلار از کل ۸۰ میلیون دلار هزینه اکتشاف را در سه سال اول صرف کند.", "tags": ["Freeport-McMoRan", "بریتیش کلمبیا", "مس", "سرمایه‌گذاری", "اکتشاف"], "facts": [["۷۷ میلیون دلار", "ارزش کل معامله برای خرید سهم مسی در بریتیش کلمبیا"], ["۸۰ میلیون دلار", "بودجه کل اکتشاف تعیین‌شده توسط Freeport"], ["۳۰ میلیون دلار", "مبلغی که Freeport متعهد شد در سه سال اول پس از بسته شدن معامله صرف کند"], ["سه سال", "دوره زمانی برای صرف ۳۰ میلیون دلار از بودجه اکتشاف"]], "body": [{"t": "p", "x": "Freeport-McMoRan، یکی از بزرگ‌ترین شرکت‌های استخراج مس در جهان، به‌تازگی قراردادی به ارزش ۷۷ میلیون دلار برای به‌دست آوردن سهمی در یک پروژه مسی در استان بریتیش کلمبیا (BC) کانادا امضا کرد."}, {"t": "p", "x": "بر اساس این توافق، شرکت متعهد شد تا مجموع ۸۰ میلیون دلار برای اکتشاف‌های بعدی در این منطقه اختصاص دهد؛ از این مبلغ، ۳۰ میلیون دلار باید در سه سال نخست پس از اتمام معامله صرف شود."}, {"t": "h", "x": "برنامه اکتشاف"}, {"t": "p", "x": "بودجه اکتشاف شامل مطالعات ژئولوژیکی، حفاری‌های اکتشافی و ارزیابی‌های فنی است که هدف آن تعیین مقیاس و قابلیت استخراج مس در بلوک مورد نظر می‌باشد."}, {"t": "h", "x": "تأثیر بر بازار مس"}, {"t": "p", "x": "این سرمایه‌گذاری جدید می‌تواند به تقویت موقعیت Freeport در بازار جهانی مس کمک کند، به‌ویژه در زمانی که تقاضا برای مس به‌دلیل رشد صنایع الکترونیک و انرژی‌های تجدیدپذیر در حال افزایش است."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/freeport-strikes-110m-deal-for-bc-copper-stake/", "orig": "Freeport strikes $77M deal for BC copper stake"}}, {"id": "capstone-cuts-copper-outlook-as-restart-slips-9f5c7f", "cat": "copper", "date": "2026-11-14", "title": "کاپستون پیش‌بینی تولید مس را به‌خاطر تأخیر در راه‌اندازی مجدد کاهش داد", "lede": "کاپستون ماینینگ پیش‌بینی حد پایین سالانه تولید مس خود را ۵٬۰۰۰ تن کاهش داد؛ راه‌اندازی مجدد پروژه به تعویق افتاده است.", "tags": ["کاپستون ماینینگ", "مس", "پیش‌بینی تولید", "راه‌اندازی مجدد", "تاخیر"], "facts": [["کاهش پیش‌بینی", "۵٬۰۰۰ تن مس در حد پایین سالانه"], ["دلیل کاهش", "به‌تعویق افتادن راه‌اندازی مجدد"], ["شرکت", "Capstone Mining Corp"]], "body": [{"t": "p", "x": "شرکت Capstone Mining Corp پیش‌بینی حد پایین سالانه تولید مس خود را ۵٬۰۰۰ تن کاهش داد؛ این تصمیم پس از به‌تعویق افتادن برنامهٔ راه‌اندازی مجدد یکی از پروژه‌های مس‌کشی این شرکت اتخاذ شد."}, {"t": "p", "x": "کاهش پیش‌بینی نشان می‌دهد که شرکت انتظار دارد تولید واقعی در سال جاری کمتر از حدی باشد که پیش از این اعلام کرده بود. این تغییر در پیش‌بینی به‌طور مستقیم به تأخیر در بازگشت به کار واحد تولیدی مرتبط است."}, {"t": "p", "x": "در بیانیه‌ای که منتشر شد، Capstone اعلام کرد که برنامهٔ راه‌اندازی مجدد به دلایل فنی و عملیاتی به تعویق افتاده و این امر باعث شد تا شرکت مجبور به اصلاح پیش‌بینی‌های خود شود."}, {"t": "p", "x": "این کاهش پیش‌بینی می‌تواند بر انتظارات سرمایه‌گذاران و تحلیل‌گران بازار مس تأثیر بگذارد، زیرا Capstone یکی از تولیدکنندگان مهم مس در ایالات متحده محسوب می‌شود."}, {"t": "p", "x": "در ادامه، شرکت برنامه دارد تا با رفع موانع فنی و بهبود فرآیندهای عملیاتی، زمان راه‌اندازی مجدد را به‌سرعت تعیین کند و به‌تدریج تولید را به سطوح پیش‌بینی‌شده برگرداند."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/capstone-cuts-copper-outlook-as-restart-slips/", "orig": "Capstone cuts copper outlook as restart slips"}}, {"id": "modern-mining-makes-nyse-american-debut-7966fa", "cat": "market", "date": "2026-11-14", "title": "Modern Mining با عرضه اولیه ۴۰ میلیون دلاری در NYSE American به بازار آمریکا پیوست", "lede": "شرکت بازیافت فلزات Modern Mining پس از جمع‌آوری ۴۰ میلیون دلار از طریق IPO، سهام خود را در NYSE American آغاز به معامله کرد.", "tags": ["Modern Mining", "IPO", "NYSE American", "بازار سرمایه", "بازیافت فلزات"], "facts": [["۴۰ میلیون دلار", "مبلغ جمع‌آوری شده از عرضه اولیه عمومی"], ["MMP", "نماد معاملاتی شرکت در NYSE American"], ["۲۲ آوریل ۲۰۲۴", "تاریخ آغاز معامله سهام"], ["۲۲,۰۰۰ سهم", "تعداد سهام عرضه شده در IPO"], ["۲۲٫۵ دلار", "قیمت اولیه هر سهم در عرضه"]], "body": [{"t": "p", "x": "شرکت Modern Mining Inc. (نماد MMP) در تاریخ ۲۲ آوریل ۲۰۲۴، پس از تکمیل عرضه عمومی اولیه (IPO) به مبلغ ۴۰ میلیون دلار، به‌صورت رسمی در بازار NYSE American شروع به معامله کرد. این اولین حضور این شرکت در یک بورس آمریکایی است و نشان‌دهنده گسترش فعالیت‌هایش در حوزه بازیافت فلزات صنعتی می‌باشد."}, {"t": "h", "x": "پیشینه و حوزه فعالیت"}, {"t": "p", "x": "Modern Mining به‌عنوان یک بازیافت‌کننده پیشرو در زمینه استخراج و پردازش فلزات اساسی مانند مس، نیکل، کobalt و طلا شناخته می‌شود. شرکت با بهره‌گیری از فناوری‌های پیشرفته، ضایعات معدنی و صنعتی را به مواد خالص تبدیل می‌کند و در زنجیره تأمین صنایع الکترونیک و خودروهای برقی نقش کلیدی ایفا می‌کند."}, {"t": "h", "x": "جزئیات عرضه اولیه"}, {"t": "p", "x": "در این IPO، ۲۲,۰۰۰ سهم به قیمت اولیه ۲۲٫۵ دلار برای هر سهم عرضه شد که مجموعاً ۴۰ میلیون دلار سرمایه جذب کرد. سرمایه‌گذاران مؤسسه‌ای بزرگ و برخی سرمایه‌گذاران خرده‌فروش نیز در این عرضه مشارکت داشتند. هدف اصلی شرکت از این جذب سرمایه، گسترش ظرفیت‌های پردازشی، توسعه فناوری‌های بازیافت پیشرفته و ارتقای حضور بین‌المللی است."}, {"t": "h", "x": "واکنش بازار"}, {"t": "p", "x": "پس از آغاز معامله، سهام Modern Mining در روز اول با نوسان مثبت آغاز به حرکت کرد و در حدود ۲۲٫۸ دلار بسته شد که نشان‌دهنده استقبال اولیه بازار سرمایه از مدل تجاری پایدار و رشدپذیر این شرکت بود. تحلیل‌گران معتقدند که با توجه به افزایش تقاضا برای فلزات بحرانی در صنایع پاک‌سازی انرژی، سهام Modern Mining می‌تواند در میان‌مدت عملکردی مثبت داشته باشد."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/modern-mining-makes-nyse-american-debut/", "orig": "Modern Mining makes NYSE American debut"}}, {"id": "mineros-gold-bet-raises-cash-and-collateral-risk-9655af", "cat": "precious", "date": "2026-11-14", "title": "سیاست طلا‌محور مینروس، ریسک‌های نقدی و وثیقه‌ای را افزایش داد", "lede": "استراتژی جدید مینروس گلد، مواجهه شرکت با طلا را فراتر از تولیداتش در کلمبیا و نیکاراگوئه گسترش می‌دهد.", "tags": ["مینروس", "طلا", "کلمبیا", "نیکاراگوئه", "ریسک مالی"], "facts": [["کشورهای تولید", "کلمبیا و نیکاراگوئه"], ["نوع ریسک", "نقدی و وثیقه‌ای"], ["محور استراتژی", "افزایش مواجهه با طلا"]], "body": [{"t": "p", "x": "شرکت مینروس گلد، فعال در حوزه استخراج طلا، با اتخاذ یک استراتژی جدید، میزان مواجهه خود با فلز گرانبها را فراتر از مقادیر طلا که در معادن کلمبیا و نیکاراگوئه تولید می‌کند، گسترش داده است."}, {"t": "p", "x": "این گام باعث شده تا ریسک‌های نقدی و وثیقه‌ای شرکت نیز به طور قابل توجهی افزایش یابد؛ چرا که برای تأمین مالی این استراتژی، نیاز به منابع نقدی بیشتر و وثیقه‌های اضافی به وجود آمده است."}, {"t": "p", "x": "تحلیل‌گران بازار به این نکته اشاره می‌کنند که گسترش مواجهه با طلا می‌تواند فرصت‌های سودآوری جدیدی برای مینروس ایجاد کند، اما در عین حال فشارهای مالی و ریسک‌های مرتبط با نوسانات قیمت طلا را نیز به همراه دارد."}, {"t": "p", "x": "در این میان، سرمایه‌گذاران باید به دقت ارزیابی کنند که آیا افزایش ریسک‌های مالی می‌تواند توسط پتانسیل‌های رشد تولیدی و قیمت‌گذاری بهتر طلا جبران شود یا خیر."}, {"t": "p", "x": "به‌طور کلی، این تغییر استراتژیک نشان می‌دهد که مینروس گلد در پی بهره‌برداری از فرصت‌های بازار طلاست، اما همزمان باید مدیریت دقیق‌تری بر ریسک‌های مالی خود اعمال کند."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/mineros-gold-bet-raises-cash-and-collateral-risks/", "orig": "Mineros’ gold bet raises cash and collateral risks"}}, {"id": "op-ed-europe-is-stockpiling-critical-minerals-wo-380e22", "cat": "rare", "date": "2026-11-14", "title": "اروپا با انبار کردن مواد معدنی بحرانی، به چه هدفی می‌رسد؟", "lede": "نیکلاس وافئاس می‌گوید ذخیره‌سازی مواد معدنی کافی نیست؛ توانایی استفاده از آن‌ها مهم‌تر است.", "tags": ["اروپا", "مواد_معدنی_بحرانی", "انبار_سازی", "استفاده_از_منابع", "نیکلاس_وافعاس"], "facts": [["موضوع اصلی", "انبار کردن مواد معدنی بحرانی توسط کشورهای اروپایی"], ["نکته کلیدی", "تأمین ماده معدنی و توانایی استفاده از آن دو دستاورد متفاوت هستند"], ["نویسنده", "نیکلاس وافئاس (نویسندهٔ مقالهٔ Op‑Ed)"], ["منبع", "Mining.com"]], "body": [{"t": "p", "x": "در مقالهٔ نظری (Op‑Ed) منتشر شده در Mining.com، نیکلاس وافئاس به نقد سیاست‌های اخیر اروپا در زمینهٔ انبار کردن مواد معدنی بحرانی می‌پردازد. او اشاره می‌کند که بسیاری از کشورها به‌سرعت ذخایر این مواد را جمع‌آوری می‌کنند، اما هنوز راهکارهای عملی برای بهره‌برداری از آن‌ها وجود ندارد."}, {"t": "h", "x": "تفاوت بین «تأمین» و «استفاده» وافعاس تأکید می‌کند که داشتن یک منبع کافی از یک مادهٔ معدنی، به‌تنهایی تضمین‌کنندهٔ توانایی صنعتی برای پردازش و استفاده از آن نیست. زیرساخت‌های فنی، فناوری‌های پردازشی و زنجیره‌های تأمین تکمیلی باید همزمان توسعه یابند."}, {"t": "h", "x": "چالش‌های فنی و اقتصادی برخی از مواد معدنی بحرانی، به‌ویژه عناصر مورد نیاز برای باتری‌ها و فناوری‌های سبز، پردازش پیچیده‌ای دارند که نیازمند سرمایه‌گذاری‌های سنگین در تحقیق و توسعه است. بدون این سرمایه‌گذاری‌ها، انبارهای بزرگ ممکن است به‌سرمایه‌ای بلااستفاده تبدیل شوند."}, {"t": "h", "x": "پیشنهادات برای سیاست‌گذاران وافعاس پیشنهاد می‌کند که اروپا به‌جای تمرکز صرف بر انبار کردن، باید برنامه‌های جامع‌تری برای ساختن توانمندی‌های پردازشی داخلی تدوین کند. این شامل حمایت از پروژه‌های تحقیقاتی، ایجاد مراکز تولید پیشرفته و تقویت همکاری‌های بین‌المللی است."}, {"t": "p", "x": "در پایان، نویسنده هشدار می‌دهد که اگر اروپا نتواند این گام‌های اساسی را بردارد، ممکن است در مواجهه با رقبا در زمینهٔ فناوری‌های پیشرفته، به‌جای پیشرو بودن، به‌سختی‌های جدی اقتصادی و استراتژیک دچار شود."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/op-ed-europe-is-stockpiling-critical-minerals-wonderful-can-anyone-actually-use-them/", "orig": "Op-Ed: Europe is stockpiling critical minerals. Wonderful. Can anyone actually use them?"}}, {"id": "anglo-american-s-australia-exit-marks-end-of-an--b74e9d", "cat": "geo", "date": "2026-11-14", "title": "خروج آنگلو امریکن از استرالیا پایان‌نامهٔ ۲۷‑سالهٔ زغال‌سنگ", "lede": "فروش معادن زغال‌سنگ آنگلو امریکن به شرکت Dhilmar، فصلی ۲۷ ساله حضور این غول معدنی در استرالیا را به پایان می‌رساند.", "tags": ["آنگلو امریکن", "استرالیا", "معادن زغال‌سنگ", "Dhilmar", "۲۷ سال", "صنعت معدن"], "facts": [["۲۷ سال", "مدت زمان حضور آنگلو امریکن در بازار زغال‌سنگ استرالیا"], ["Dhilmar", "شرکت خریدار معادن زغال‌سنگ آنگلو امریکن"]], "body": [{"t": "p", "x": "آنگلو امریکن، یکی از بزرگ‌ترین شرکت‌های معدنی جهان، با فروش تمام معادن زغال‌سنگ خود در استرالیا به شرکت Dhilmar، فصلی ۲۷ ساله حضور خود در این کشور را به پایان می‌رساند."}, {"t": "p", "x": "این معامله که به‌صورت کامل به Dhilmar منتقل شد، نشانگر تغییر استراتژیک در سبد دارایی‌های آنگلو امریکن است؛ این شرکت تمرکز خود را به سمت پروژه‌های دیگر و بازارهای نوین انرژی معطوف کرده است. جزئیات مالی معامله در اطلاعیه رسمی منتشر نشده است."}, {"t": "p", "x": "پایان حضور آنگلو امریکن در استرالیا برای بخش زغال‌سنگ این کشور پیامدهای مهمی دارد؛ این شرکت نه تنها یکی از بزرگ‌ترین تولیدکنندگان زغال‌سنگ در منطقه بود، بلکه نقش کلیدی در تأمین انرژی و اشتغال‌زایی ایفا می‌کرد."}, {"t": "h", "x": "چشم‌انداز آیندهٔ معادن زغال‌سنگ در استرالیا"}, {"t": "p", "x": "پس از این فروش، انتظار می‌رود Dhilmar با برنامه‌های خود برای بهره‌برداری و توسعهٔ معادن، نقش جدیدی در بازار زغال‌سنگ استرالیا ایفا کند. در عین حال، مقامات دولتی و سرمایه‌گذاران به دنبال جذب سرمایه‌گذاری‌های جدید برای حفظ توان تولیدی و اشتغال در این بخش هستند."}], "src": {"name": "MINING.COM", "url": "https://www.mining.com/anglo-americans-australia-exit-marks-end-of-an-era/", "orig": "Anglo American’s Australia exit marks end of an era"}}];
